    pub fn snapshotLsmNativeStorageStats(self: *DB) lsm_backend_mod.NativeStorageStats {
        lockApplyShared(self);
        defer self.core.unlockApplyShared();
        return self.snapshotLsmNativeStorageStatsLocked();
    }

    pub fn trySnapshotLsmNativeStorageStats(self: *DB) ?lsm_backend_mod.NativeStorageStats {
        if (!self.core.tryLockApplyShared()) return null;
        defer self.core.unlockApplyShared();
        return self.snapshotLsmNativeStorageStatsLocked();
    }

    fn snapshotLsmNativeStorageStatsLocked(self: *DB) lsm_backend_mod.NativeStorageStats {
        var native_storage_stats = lsm_backend_mod.NativeStorageStats{};
        if (self.core.primary_store_owner.snapshotLsmNativeStorageStats()) |primary_stats| {
            native_storage_stats.fd_cache_entries +|= primary_stats.fd_cache_entries;
            native_storage_stats.fd_cache_capacity +|= primary_stats.fd_cache_capacity;
        }
        const index_stats = self.core.index_manager.snapshotLsmNativeStorageStats();
        native_storage_stats.fd_cache_entries +|= index_stats.fd_cache_entries;
        native_storage_stats.fd_cache_capacity +|= index_stats.fd_cache_capacity;
        return native_storage_stats;
    }

    pub fn runLsmMaintenanceStep(self: *DB) !bool {
        lockApply(self);
        defer self.core.unlockApply();

        const primary_score = self.core.primary_store_owner.lsmMaintenanceScore();
        const index_score = self.core.index_manager.lsmMaintenanceScore();
        if (primary_score == 0 and index_score == 0) {
            self.core.primary_store_owner.refreshLsmMaintenanceDebtHint();
            self.core.index_manager.refreshLsmMaintenanceDebtHint();
            return false;
        }
        if (primary_score >= index_score) {
            return try self.core.primary_store_owner.runLsmMaintenanceStep();
        }
        return try self.core.index_manager.runLsmMaintenanceStep();
    }

    pub fn runLsmMaintenanceStepBestEffort(self: *DB) !bool {
        if (!self.core.tryLockApplyExclusive()) return false;
        defer self.core.unlockApply();

        const primary_score = self.core.primary_store_owner.lsmMaintenanceDebtHint();
        if (primary_score > 0) {
            if (try self.core.primary_store_owner.runLsmMaintenanceStepBestEffort()) return true;
        }
        if (try self.core.index_manager.runLsmMaintenanceStepBestEffort()) return true;
        if (primary_score > 0) {
            self.core.primary_store_owner.refreshLsmMaintenanceDebtHint();
        }
        return false;
    }

    pub fn hasActiveDenseBulkWork(self: *const DB) bool {
        return asyncContextHasActiveDenseBulkWork(self.async_context);
    }

    pub fn runLsmMaintenanceUntilIdle(self: *DB) !usize {
        var steps: usize = 0;
        while (try self.runLsmMaintenanceStep()) {
            steps += 1;
        }
        return steps;
    }

    pub fn batch(self: *DB, req: types.BatchRequest) anyerror!void {
        if (benchMetricsEnabled()) {
            var profile = BatchProfile{};
            try self.batchInternal(req, &profile, .{});
            logBatchProfile(req, profile);
        } else {
            try self.batchInternal(req, null, .{});
        }
    }

    pub fn batchProfiled(self: *DB, req: types.BatchRequest, profile: *BatchProfile) anyerror!void {
        try self.batchInternal(req, profile, .{});
    }

    pub fn batchWithoutRangeValidation(self: *DB, req: types.BatchRequest) anyerror!void {
        try self.batchInternal(req, null, .{ .validate_range_ownership = false });
    }

    pub fn batchReplicatedApply(self: *DB, req: types.BatchRequest) anyerror!void {
        var apply_req = req;
        apply_req.sync_level = .write;
        try self.batchInternal(apply_req, null, .{
            .validate_range_ownership = false,
            .wait_for_sync_level = false,
        });
    }

    fn batchInternal(self: *DB, req: types.BatchRequest, profile: ?*BatchProfile, opts: BatchExecutionOptions) anyerror!void {
        if (openModeRequiresReadOnlyBackends(self.open_mode)) return error.ReadOnly;
        const total_start_ns = monotonicTimeNs();
        defer {
            if (profile) |active_profile| {
                active_profile.total_ns += monotonicTimeNs() - total_start_ns;
            }
        }

        try self.executor.failIfUnhealthy();

        lockApply(self);
        var apply_mutex_held = true;
        errdefer if (apply_mutex_held) self.core.unlockApply();

        if (self.bulk_ingest_coalescer.active and !self.flushing_bulk_ingest_coalescer) {
            if (self.bulk_ingest_coalescer.hasPending()) {
                self.core.unlockApply();
                apply_mutex_held = false;
                try self.flushBulkIngestCoalescerWithSyncLevel(req.sync_level, profile);
                lockApply(self);
                apply_mutex_held = true;
            }
        }

        const resolve_transforms_start_ns = monotonicTimeNs();
        var effective_ops = try coalesceKeyValueRequest(self, types.BatchWrite, req.writes, req.deletes, req.transforms);
        defer effective_ops.deinit(self.alloc);
        if (profile) |active_profile| recordProfileNs(profile, &active_profile.resolve_transforms_ns, resolve_transforms_start_ns);

        const merge_effective_req_start_ns = monotonicTimeNs();

        const effective_req: types.BatchRequest = .{
            .writes = effective_ops.writes,
            .deletes = effective_ops.deletes,
            .relational_identity_rewrites = req.relational_identity_rewrites,
            .graph_writes = req.graph_writes,
            .graph_deletes = req.graph_deletes,
            .transforms = &.{},
            .predicates = req.predicates,
            .timestamp_ns = req.timestamp_ns,
            .sync_level = req.sync_level,
        };
        if (profile) |active_profile| recordProfileNs(profile, &active_profile.merge_effective_req_ns, merge_effective_req_start_ns);

        var effective_predicates = std.ArrayListUnmanaged(transactions_mod.VersionPredicate).empty;
        defer effective_predicates.deinit(self.alloc);
        var owned_row_claim_predicate_keys = std.ArrayListUnmanaged([]u8).empty;
        defer {
            for (owned_row_claim_predicate_keys.items) |key| self.alloc.free(key);
            owned_row_claim_predicate_keys.deinit(self.alloc);
        }
        if (effective_req.predicates.len > 0) {
            for (effective_req.predicates) |predicate| {
                try effective_predicates.append(self.alloc, .{
                    .key = predicate.key,
                    .expected_version = predicate.expected_version,
                });
            }
        }
        try appendRowClaimPredicatesForMutationKeys(
            self.alloc,
            &effective_predicates,
            &owned_row_claim_predicate_keys,
            effective_req.writes,
            effective_req.deletes,
        );
        try appendRowClaimPredicatesForIdentityRewrites(
            self.alloc,
            &effective_predicates,
            &owned_row_claim_predicate_keys,
            effective_req.relational_identity_rewrites,
        );
        _ = try reclaimExpiredRowClaimIntentsForMutationKeys(
            self,
            effective_req.writes,
            effective_req.deletes,
            null,
            monotonicTimeNs(),
            true,
        );
        _ = try reclaimExpiredRowClaimIntentsForIdentityRewrites(
            self,
            effective_req.relational_identity_rewrites,
            null,
            monotonicTimeNs(),
            true,
        );

        if (effective_predicates.items.len > 0) {
            const predicates_start_ns = monotonicTimeNs();
            try self.core.checkVersionPredicates(effective_predicates.items, null);
            if (profile) |active_profile| recordProfileNs(profile, &active_profile.predicates_ns, predicates_start_ns);
        }

        if (opts.validate_range_ownership) {
            const validate_range_start_ns = monotonicTimeNs();
            try self.core.validateBatchRangeOwnership(effective_req);
            if (profile) |active_profile| recordProfileNs(profile, &active_profile.validate_range_ns, validate_range_start_ns);
        }

        const extract_writes_start_ns = monotonicTimeNs();
        var extracted = try self.alloc.alloc(mapper.ExtractedWrite, effective_req.writes.len);
        var extracted_initialized: usize = 0;
        defer {
            for (extracted[0..extracted_initialized]) |*item| item.deinit(self.alloc);
            self.alloc.free(extracted);
        }

        var store_writes = std.ArrayListUnmanaged(docstore_mod.KVPair).empty;
        defer store_writes.deinit(self.alloc);
        var owned_store_keys = std.ArrayListUnmanaged([]u8).empty;
        defer {
            for (owned_store_keys.items) |key| self.alloc.free(key);
            owned_store_keys.deinit(self.alloc);
        }
        var owned_store_values = std.ArrayListUnmanaged([]u8).empty;
        defer {
            for (owned_store_values.items) |value| self.alloc.free(value);
            owned_store_values.deinit(self.alloc);
        }
        const vector_field_names_start_ns = monotonicTimeNs();
        const vector_store_field_names = try self.core.index_manager.vectorStoreFieldNamesAlloc(self.alloc);
        if (profile) |active_profile| recordProfileNs(profile, &active_profile.extract_vector_field_names_ns, vector_field_names_start_ns);
        defer {
            for (vector_store_field_names) |field| self.alloc.free(field);
            if (vector_store_field_names.len > 0) self.alloc.free(vector_store_field_names);
        }
        var timestamp_writes = std.ArrayListUnmanaged(docstore_mod.KVPair).empty;
        defer {
            for (timestamp_writes.items) |item| {
                self.alloc.free(@constCast(item.key));
                self.alloc.free(@constCast(item.value));
            }
            timestamp_writes.deinit(self.alloc);
        }
        var explicit_embedding_artifact_writes = std.ArrayListUnmanaged(types.BatchWrite).empty;
        defer {
            for (explicit_embedding_artifact_writes.items) |item| {
                self.alloc.free(@constCast(item.key));
                self.alloc.free(@constCast(item.value));
            }
            explicit_embedding_artifact_writes.deinit(self.alloc);
        }
        var explicit_graph_artifact_writes = std.ArrayListUnmanaged(types.BatchWrite).empty;
        defer {
            for (explicit_graph_artifact_writes.items) |item| {
                self.alloc.free(@constCast(item.key));
                self.alloc.free(@constCast(item.value));
            }
            explicit_graph_artifact_writes.deinit(self.alloc);
        }
        var delete_keys = std.ArrayListUnmanaged([]const u8).empty;
        defer delete_keys.deinit(self.alloc);
        var owned_delete_keys = std.ArrayListUnmanaged([]u8).empty;
        defer {
            for (owned_delete_keys.items) |key| self.alloc.free(key);
            owned_delete_keys.deinit(self.alloc);
        }
        var relational_participant = relational_store_mod.WriteParticipant.initWithColumnIndexPolicy(
            self.alloc,
            self.core.store,
            &store_writes,
            &delete_keys,
            &owned_store_keys,
            &owned_store_values,
            self.relationalColumnIndexPolicyForStore(),
        );
        if (self.core.schema) |runtime_schema| {
            relational_participant.configureForeignKeys(runtime_schema.default_type, runtime_schema.foreign_keys, effective_req.deletes);
            relational_participant.configurePrimaryKey(runtime_schema.primary_key);
            relational_participant.configureUniqueConstraints(runtime_schema.unique_constraints);
            relational_participant.configurePeriods(runtime_schema.periods, runtime_schema.relational_columns);
        }
        var relational_participant_prepared = false;
        var relational_participant_closed = false;
        defer if (relational_participant_prepared and !relational_participant_closed)
            relational_participant.abort(null);
        var graph_artifact_clears = std.ArrayListUnmanaged(GraphArtifactClear).empty;
        defer {
            for (graph_artifact_clears.items) |*item| item.deinit(self.alloc);
            graph_artifact_clears.deinit(self.alloc);
        }
        var timestamp_delete_keys = std.ArrayListUnmanaged([]const u8).empty;
        defer {
            for (timestamp_delete_keys.items) |key| self.alloc.free(@constCast(key));
            timestamp_delete_keys.deinit(self.alloc);
        }
        var overwritten_flags = try self.alloc.alloc(bool, effective_req.writes.len);
        defer self.alloc.free(overwritten_flags);
        @memset(overwritten_flags, false);
        var overwrite_probe_entries = std.ArrayListUnmanaged(OverwriteProbeEntry).empty;
        defer overwrite_probe_entries.deinit(self.alloc);
        var identity_upsert_keys = std.ArrayListUnmanaged([]const u8).empty;
        defer identity_upsert_keys.deinit(self.alloc);
        var identity_upsert_write_indexes = std.ArrayListUnmanaged(usize).empty;
        defer identity_upsert_write_indexes.deinit(self.alloc);
        var identity_writes = std.ArrayListUnmanaged(docstore_mod.KVPair).empty;
        defer {
            for (identity_writes.items) |item| {
                self.alloc.free(@constCast(item.key));
                self.alloc.free(@constCast(item.value));
            }
            identity_writes.deinit(self.alloc);
        }

        const batch_timestamp_ns = if (effective_req.timestamp_ns != 0) effective_req.timestamp_ns else currentTimeNs();

        for (effective_req.writes, 0..) |write, i| {
            if (isMetadataKey(write.key)) {
                extracted[i] = .{
                    .cleaned_value = null,
                    .graph_writes = &.{},
                    .mentioned_graph_indexes = &.{},
                    .dense_embeddings = &.{},
                    .sparse_embeddings = &.{},
                };
                extracted_initialized += 1;
                try store_writes.append(self.alloc, .{
                    .key = write.key,
                    .value = write.value,
                });
                continue;
            }
            const mapper_extract_start_ns = monotonicTimeNs();
            extracted[i] = try mapper.extractWrite(self.alloc, write.key, write.value);
            if (profile) |active_profile| recordProfileNs(profile, &active_profile.extract_mapper_ns, mapper_extract_start_ns);
            const graph_field_extract_start_ns = monotonicTimeNs();
            try augmentExtractedWriteWithGraphFieldEdges(self, self.alloc, write.key, write.value, &extracted[i]);
            if (profile) |active_profile| recordProfileNs(profile, &active_profile.extract_graph_fields_ns, graph_field_extract_start_ns);
            const index_field_embeddings_start_ns = monotonicTimeNs();
            try self.core.index_manager.appendIndexFieldEmbeddingsToExtractedWrite(self.alloc, write.key, write.value, &extracted[i]);
            if (profile) |active_profile| recordProfileNs(profile, &active_profile.extract_index_field_embeddings_ns, index_field_embeddings_start_ns);
            extracted_initialized += 1;
            const embedding_artifacts_start_ns = monotonicTimeNs();
            for (extracted[i].dense_embeddings) |*embedding| {
                if (embedding.artifact_key != null) continue;
                embedding.artifact_key = try appendEmbeddingArtifactWrite(
                    self.alloc,
                    &explicit_embedding_artifact_writes,
                    write.key,
                    write.key,
                    embedding.index_name,
                    "_embeddings",
                    null,
                    null,
                    embedding.vector,
                );
            }
            for (extracted[i].sparse_embeddings) |*embedding| {
                if (embedding.artifact_key != null) continue;
                embedding.artifact_key = try appendSparseEmbeddingArtifactWrite(
                    self.alloc,
                    &explicit_embedding_artifact_writes,
                    write.key,
                    embedding.index_name,
                    null,
                    embedding.indices,
                    embedding.values,
                );
            }
            if (profile) |active_profile| recordProfileNs(profile, &active_profile.extract_embedding_artifacts_ns, embedding_artifacts_start_ns);
            const graph_artifacts_start_ns = monotonicTimeNs();
            for (extracted[i].graph_writes) |graph_write| {
                try appendGraphEdgeArtifactWrite(self.alloc, &explicit_graph_artifact_writes, graph_write);
            }
            for (extracted[i].mentioned_graph_indexes) |index_name| {
                try graph_artifact_clears.append(self.alloc, .{
                    .doc_key = try self.alloc.dupe(u8, write.key),
                    .index_name = try self.alloc.dupe(u8, index_name),
                });
            }
            if (profile) |active_profile| recordProfileNs(profile, &active_profile.extract_graph_artifacts_ns, graph_artifacts_start_ns);
            if (extracted[i].cleaned_value) |cleaned| {
                const strip_store_value_start_ns = monotonicTimeNs();
                // Relational tables project the document once into a typed row
                // and store that row as the table's only base document record.
                // Document-mode tables keep the JSON blob under the primary
                // document key.
                const relational_columns = self.relationalColumnsForStore();
                const store_value = if (relational_columns) |columns|
                    try relationalStoreRowValueAlloc(self.alloc, cleaned, columns, &owned_store_values)
                else
                    try strippedStoredDocumentValueAlloc(
                        self.alloc,
                        cleaned,
                        vector_store_field_names,
                        &owned_store_values,
                    );
                if (profile) |active_profile| recordProfileNs(profile, &active_profile.extract_strip_store_value_ns, strip_store_value_start_ns);
                const store_key = if (relational_columns != null) blk: {
                    const row_write_index = store_writes.items.len;
                    relational_participant.prepareUpsert("", write.key, store_value, null) catch |err| {
                        if (err == error.ForeignKeyViolation) self.recordForeignKeyChildWriteReject();
                        return err;
                    };
                    relational_participant_prepared = true;
                    const primary_key = try internal_keys.documentKeyAlloc(self.alloc, write.key);
                    var primary_key_owned = true;
                    errdefer if (primary_key_owned) self.alloc.free(primary_key);
                    try owned_delete_keys.append(self.alloc, primary_key);
                    primary_key_owned = false;
                    try delete_keys.append(self.alloc, primary_key);
                    break :blk store_writes.items[row_write_index].key;
                } else blk: {
                    const key = try internal_keys.documentKeyAlloc(self.alloc, write.key);
                    try owned_store_keys.append(self.alloc, key);
                    try store_writes.append(self.alloc, .{
                        .key = key,
                        .value = store_value,
                    });
                    break :blk key;
                };
                try overwrite_probe_entries.append(self.alloc, .{
                    .key = store_key,
                    .write_index = i,
                });
                try identity_upsert_keys.append(self.alloc, write.key);
                try identity_upsert_write_indexes.append(self.alloc, i);
                if (shouldWriteTimestamp(write.key)) {
                    const timestamp_start_ns = monotonicTimeNs();
                    const write_timestamp_ns = try resolveWriteTimestampNs(self, batch_timestamp_ns, write.value);
                    const timestamp_key = try makeTimestampKey(self.alloc, write.key);
                    const timestamp_value = try encodeTimestampValue(self.alloc, write_timestamp_ns);
                    try timestamp_writes.append(self.alloc, .{
                        .key = timestamp_key,
                        .value = timestamp_value,
                    });
                    if (profile) |active_profile| recordProfileNs(profile, &active_profile.extract_timestamp_ns, timestamp_start_ns);
                }
            }
        }
        for (effective_req.relational_identity_rewrites) |rewrite| {
            const relational_columns = self.relationalColumnsForStore() orelse return error.UnsupportedOperation;
            const store_value = try relationalStoreRowValueAlloc(self.alloc, rewrite.value, relational_columns, &owned_store_values);
            relational_participant.prepareIdentityRewrite("", rewrite.old_key, rewrite.new_key, store_value, null) catch |err| {
                if (err == error.ForeignKeyViolation) self.recordForeignKeyParentDeleteReject();
                return err;
            };
            relational_participant_prepared = true;
            try identity_upsert_keys.append(self.alloc, rewrite.new_key);
            const old_document_key = try internal_keys.documentKeyAlloc(self.alloc, rewrite.old_key);
            var old_document_key_owned = true;
            errdefer if (old_document_key_owned) self.alloc.free(old_document_key);
            try owned_delete_keys.append(self.alloc, old_document_key);
            old_document_key_owned = false;
            try delete_keys.append(self.alloc, old_document_key);
            const new_document_key = try internal_keys.documentKeyAlloc(self.alloc, rewrite.new_key);
            var new_document_key_owned = true;
            errdefer if (new_document_key_owned) self.alloc.free(new_document_key);
            try owned_delete_keys.append(self.alloc, new_document_key);
            new_document_key_owned = false;
            try delete_keys.append(self.alloc, new_document_key);
        }
        if (profile) |active_profile| {
            active_profile.identity_upsert_keys += @intCast(identity_upsert_keys.items.len);
            active_profile.identity_delete_keys += @intCast(effective_req.deletes.len);
        }
        const identity_capacity_start_ns = monotonicTimeNs();
        if (!self.bulk_ingest_identity_all_new or effective_req.deletes.len != 0) {
            try self.failIfIdentityOrdinalExhaustedForNewUpserts(identity_upsert_keys.items);
        }
        if (profile) |active_profile| recordProfileNs(profile, &active_profile.identity_capacity_check_ns, identity_capacity_start_ns);

        var assume_all_new_identity_upserts = false;
        if (self.bulk_ingest_identity_all_new and effective_req.deletes.len == 0 and identity_upsert_keys.items.len > 0) {
            assume_all_new_identity_upserts = try self.rememberBulkIngestAllNewIdentityUpserts(identity_upsert_keys.items);
            if (!assume_all_new_identity_upserts) self.clearBulkIngestIdentityAllNewLocked();
        }

        if (!assume_all_new_identity_upserts and overwrite_probe_entries.items.len > 0) {
            const overwrite_probe_start_ns = monotonicTimeNs();
            std.sort.pdq(OverwriteProbeEntry, overwrite_probe_entries.items, {}, overwriteProbeLessThan);
            const probe_keys = try self.alloc.alloc([]const u8, overwrite_probe_entries.items.len);
            defer self.alloc.free(probe_keys);
            const probe_values = try self.alloc.alloc(?[]const u8, overwrite_probe_entries.items.len);
            defer self.alloc.free(probe_values);
            for (overwrite_probe_entries.items, 0..) |entry, i| {
                probe_keys[i] = entry.key;
            }
            var overwrite_probe_txn = try self.core.store.beginProbeTxn();
            defer overwrite_probe_txn.abort();
            try overwrite_probe_txn.getManySorted(probe_keys, probe_values);
            for (overwrite_probe_entries.items, 0..) |entry, i| {
                overwritten_flags[entry.write_index] = probe_values[i] != null;
            }
            if (profile) |active_profile| recordProfileNs(profile, &active_profile.overwrite_probe_ns, overwrite_probe_start_ns);
        }

        for (effective_req.graph_writes) |graph_write| {
            try appendGraphEdgeArtifactWrite(self.alloc, &explicit_graph_artifact_writes, graph_write);
        }

        var changed_graph_artifact_keys = std.ArrayListUnmanaged([]u8).empty;
        defer {
            for (changed_graph_artifact_keys.items) |key| self.alloc.free(key);
            changed_graph_artifact_keys.deinit(self.alloc);
        }
        for (graph_artifact_clears.items) |clear| {
            const existing = try collectGraphArtifactsForDocIndex(self.alloc, self.core.store, clear.doc_key, clear.index_name);
            defer docstore_mod.DocStore.freeResults(self.alloc, existing);
            for (existing) |entry| {
                if (containsBatchWriteKey(explicit_graph_artifact_writes.items, entry.key)) continue;
                if (containsOwnedKey(owned_delete_keys.items, entry.key)) continue;
                const owned_key = try self.alloc.dupe(u8, entry.key);
                try owned_delete_keys.append(self.alloc, owned_key);
                try delete_keys.append(self.alloc, owned_key);
                try appendUniqueOwnedKey(self.alloc, &changed_graph_artifact_keys, entry.key);
            }
        }

        try store_writes.appendSlice(self.alloc, timestamp_writes.items);
        for (explicit_embedding_artifact_writes.items) |write| {
            try store_writes.append(self.alloc, .{
                .key = write.key,
                .value = write.value,
            });
        }
        for (explicit_graph_artifact_writes.items) |write| {
            try store_writes.append(self.alloc, .{
                .key = write.key,
                .value = write.value,
            });
            try appendUniqueOwnedKey(self.alloc, &changed_graph_artifact_keys, write.key);
        }
        for (effective_req.graph_deletes) |delete| {
            const artifact_key = try internal_keys.graphEdgeArtifactKeyAlloc(self.alloc, delete.source, delete.index_name, delete.edge_type, delete.target);
            defer self.alloc.free(artifact_key);
            if (containsBatchWriteKey(explicit_graph_artifact_writes.items, artifact_key)) continue;
            if (containsOwnedKey(owned_delete_keys.items, artifact_key)) continue;
            const owned_key = try self.alloc.dupe(u8, artifact_key);
            try owned_delete_keys.append(self.alloc, owned_key);
            try delete_keys.append(self.alloc, owned_key);
            try appendUniqueOwnedKey(self.alloc, &changed_graph_artifact_keys, artifact_key);
        }
        for (effective_req.deletes) |key| {
            if (self.relationalColumnsForStore() != null) {
                relational_participant.prepareDelete("", key, null) catch |err| {
                    if (err == error.ForeignKeyViolation) self.recordForeignKeyParentDeleteReject();
                    return err;
                };
                relational_participant_prepared = true;
                const primary_key = try internal_keys.documentKeyAlloc(self.alloc, key);
                var primary_key_owned = true;
                errdefer if (primary_key_owned) self.alloc.free(primary_key);
                try owned_delete_keys.append(self.alloc, primary_key);
                primary_key_owned = false;
                try delete_keys.append(self.alloc, primary_key);
            } else {
                const store_key = try internal_keys.documentKeyAlloc(self.alloc, key);
                try owned_delete_keys.append(self.alloc, store_key);
                try delete_keys.append(self.alloc, store_key);
            }
            if (shouldWriteTimestamp(key)) {
                const timestamp_key = try makeTimestampKey(self.alloc, key);
                try timestamp_delete_keys.append(self.alloc, timestamp_key);
                try delete_keys.append(self.alloc, timestamp_key);
            }
        }
        if (profile) |active_profile| recordProfileNs(profile, &active_profile.extract_writes_ns, extract_writes_start_ns);

        const delete_artifacts_start_ns = monotonicTimeNs();
        const deleted_artifact_keys = try deleteEnrichmentArtifactsForBatch(self, effective_req, extracted[0..extracted_initialized]);
        defer freeOwnedKeySlice(self.alloc, deleted_artifact_keys);
        if (profile) |active_profile| recordProfileNs(profile, &active_profile.delete_artifacts_ns, delete_artifacts_start_ns);

        const use_thin_replay_fast_path =
            effective_req.sync_level != .full_text and
            effective_req.sync_level != .enrichments and
            effective_req.sync_level != .aknn and
            effective_req.sync_level != .full_index and
            !splitShadowRequiresMaterializedDerivedBatch(self);
        const include_generated_enrichment_hint = use_thin_replay_fast_path and
            self.core.hasGeneratedEnrichmentTargets();

        var precomputed_generated: PrecomputedGeneratedBatch = .{};
        defer precomputed_generated.deinit(self.alloc);
        var materialized_graph_artifact_writes = std.ArrayListUnmanaged(types.BatchWrite).empty;
        defer {
            for (materialized_graph_artifact_writes.items) |write| {
                self.alloc.free(@constCast(write.key));
                self.alloc.free(@constCast(write.value));
            }
            materialized_graph_artifact_writes.deinit(self.alloc);
        }
        if (!use_thin_replay_fast_path) {
            const precompute_generated_start_ns = monotonicTimeNs();
            precomputed_generated = try prepareGeneratedEnrichments(
                self,
                effective_req,
                extracted[0..extracted_initialized],
                generatedPrecomputeModeForSyncLevel(effective_req.sync_level),
            );

            for (precomputed_generated.artifact_writes) |write| {
                try store_writes.append(self.alloc, .{
                    .key = write.key,
                    .value = write.value,
                });
                try appendUniqueOwnedKey(self.alloc, &changed_graph_artifact_keys, write.key);
            }
            for (precomputed_generated.artifact_delete_keys) |key| {
                try delete_keys.append(self.alloc, key);
                if (internal_keys.isAssetArtifactKey(key)) {
                    try appendUniqueOwnedKey(self.alloc, &changed_graph_artifact_keys, key);
                }
            }
            try appendPrecomputedGraphSourceArtifacts(
                self,
                precomputed_generated.artifact_writes,
                precomputed_generated.artifact_delete_keys,
                &materialized_graph_artifact_writes,
                &store_writes,
                &delete_keys,
                &owned_delete_keys,
                &changed_graph_artifact_keys,
            );
            if (profile) |active_profile| recordProfileNs(profile, &active_profile.precompute_generated_ns, precompute_generated_start_ns);
        }
        if (explicit_embedding_artifact_writes.items.len > 0 or
            explicit_graph_artifact_writes.items.len > 0 or
            materialized_graph_artifact_writes.items.len > 0 or
            precomputed_generated.artifact_writes.len > 0)
        {
            try self.core.appendArtifactPresenceMarker(&store_writes);
        }
        try appendAssetArtifactSourceIndexMutations(
            self.alloc,
            &store_writes,
            deleted_artifact_keys,
            &delete_keys,
            &owned_store_keys,
            &owned_store_values,
            &owned_delete_keys,
        );

        var sync_targets: ManagedSyncTargets = .{};
        defer sync_targets.deinit(self.alloc);
        var materialized_derived_batch: ?derived_types.DerivedBatch = null;
        defer if (materialized_derived_batch) |*materialized_batch| derived_types.deinitDerivedBatch(self.alloc, materialized_batch);
        const sequence = self.core.reserveDerivedAppendSequence();
        const identity_metadata_start_ns = monotonicTimeNs();
        var used_trusted_identity_path = false;
        if (effective_req.deletes.len != 0) {
            self.clearBulkIngestIdentityAllNewLocked();
        }
        if (self.bulk_ingest_identity_all_new and
            effective_req.deletes.len == 0 and
            identity_upsert_keys.items.len > 0 and
            (assume_all_new_identity_upserts or identityUpsertStoreWritesAreNew(identity_upsert_write_indexes.items, overwritten_flags)))
        {
            used_trusted_identity_path = try doc_identity.appendBatchIdentityMetadataAllNewTrustedStateForNamespaceAlloc(
                self.alloc,
                self.core.identity_namespace,
                sequence,
                &identity_writes,
                identity_upsert_keys.items,
                &self.bulk_ingest_identity_state,
            );
            if (!used_trusted_identity_path) self.clearBulkIngestIdentityAllNewLocked();
        }
        if (!used_trusted_identity_path) {
            try doc_identity.appendBatchIdentityMetadataForNamespaceAlloc(
                self.alloc,
                self.core.store,
                self.core.identity_namespace,
                sequence,
                &identity_writes,
                identity_upsert_keys.items,
                effective_req.deletes,
            );
        }
        if (profile) |active_profile| {
            recordProfileNs(profile, &active_profile.identity_metadata_ns, identity_metadata_start_ns);
            active_profile.identity_metadata_writes += @intCast(identity_writes.items.len);
        }
        const pending_identity_visibility_summary = try doc_identity.visibilitySummaryFromWrites(identity_writes.items);
        try store_writes.appendSlice(self.alloc, identity_writes.items);
        const build_derived_start_ns = monotonicTimeNs();
        const replay_payload = if (use_thin_replay_fast_path)
            try encodeThinReplayRecordPayload(
                self.alloc,
                effective_req,
                extracted[0..extracted_initialized],
                deleted_artifact_keys,
                changed_graph_artifact_keys.items,
                overwritten_flags,
                sequence,
                include_generated_enrichment_hint,
            )
        else blk: {
            materialized_derived_batch = try buildDerivedBatch(self.alloc, effective_req, extracted[0..extracted_initialized], deleted_artifact_keys, changed_graph_artifact_keys.items);
            for (materialized_derived_batch.?.overwritten_doc_keys) |key| self.alloc.free(@constCast(key));
            if (materialized_derived_batch.?.overwritten_doc_keys.len > 0) self.alloc.free(materialized_derived_batch.?.overwritten_doc_keys);
            materialized_derived_batch.?.overwritten_doc_keys = try buildOverwrittenDocKeys(self.alloc, effective_req.writes, overwritten_flags);
            materialized_derived_batch.?.documents = try takeOwnedSlice(derived_types.DerivedDocument, self.alloc, materialized_derived_batch.?.documents, &precomputed_generated.documents);
            materialized_derived_batch.?.dense_embeddings = try takeOwnedSlice(derived_types.DerivedDenseEmbeddingWrite, self.alloc, materialized_derived_batch.?.dense_embeddings, &precomputed_generated.dense_embeddings);
            materialized_derived_batch.?.sparse_embeddings = try takeOwnedSlice(derived_types.DerivedSparseEmbeddingWrite, self.alloc, materialized_derived_batch.?.sparse_embeddings, &precomputed_generated.sparse_embeddings);
            materialized_derived_batch.?.generated_enrichment_refs = precomputed_generated.generated_enrichment_refs;
            precomputed_generated.generated_enrichment_refs = &.{};
            materialized_derived_batch.?.sequence = sequence;
            const payload = try encodeChangeRecordPayload(&self.batchContext(), materialized_derived_batch.?, sequence);
            try attachInlineUpsertDocumentValues(self.alloc, &materialized_derived_batch.?, effective_req, extracted[0..extracted_initialized]);

            const apply_shadow_start_ns = monotonicTimeNs();
            try applyDerivedBatchToShadowIfNeeded(self, materialized_derived_batch.?);
            if (profile) |active_profile| recordProfileNs(profile, &active_profile.apply_shadow_ns, apply_shadow_start_ns);

            const collect_sync_targets_start_ns = monotonicTimeNs();
            sync_targets = try collectManagedSyncTargets(self.alloc, self.core.index_manager, materialized_derived_batch.?);
            if (profile) |active_profile| recordProfileNs(profile, &active_profile.collect_sync_targets_ns, collect_sync_targets_start_ns);
            break :blk payload;
        };
        defer self.alloc.free(replay_payload);
        if (profile) |active_profile| recordProfileNs(profile, &active_profile.build_derived_ns, build_derived_start_ns);

        const store_write_start_ns = monotonicTimeNs();
        const store_batch_options: backend_types.BatchOptions = if (opts.store_batch_options.mode != .default)
            opts.store_batch_options
        else if (self.bulk_ingest_coalescer.active)
            .{ .mode = .bulk_ingest }
        else
            .{};
        if (relational_participant_prepared) {
            relational_participant.commit(null, sequence) catch |err| {
                if (err == error.ForeignKeyViolation) self.recordForeignKeyChildWriteReject();
                return err;
            };
            relational_participant_closed = true;
        }
        try self.core.store.putBatchWithReplayWithOptions(
            self.backend_runtime.io(),
            store_writes.items,
            delete_keys.items,
            .{
                .sequence = sequence,
                .payload = replay_payload,
            },
            store_batch_options,
        );
        if (pending_identity_visibility_summary) |summary| {
            self.identity_visibility_summary_cache = summary;
        }
        if (profile) |active_profile| {
            recordProfileNs(profile, &active_profile.store_write_ns, store_write_start_ns);
            active_profile.store_write_count += @intCast(store_writes.items.len);
            active_profile.store_delete_count += @intCast(delete_keys.items.len);
        }
        if (shouldAppendSplitDelta(self)) {
            const split_delta_start_ns = monotonicTimeNs();
            try self.core.appendSplitDelta(batch_timestamp_ns, store_writes.items, delete_keys.items);
            if (profile) |active_profile| recordProfileNs(profile, &active_profile.split_delta_ns, split_delta_start_ns);
        }

        const append_replay_journal_start_ns = monotonicTimeNs();
        self.executor.trackBacklogBytes(sequence, @intCast(replay_payload.len)) catch {};
        if (profile) |active_profile| recordProfileNs(profile, &active_profile.append_replay_journal_ns, append_replay_journal_start_ns);
        self.core.unlockApply();
        apply_mutex_held = false;
        var pressure_ctx = self.batchContext();
        const backlog_pressure_start_ns = monotonicTimeNs();
        try self.markPrecomputedEnrichmentAppliedForSync(effective_req.sync_level, sequence);
        try applyDerivedBacklogPressureContext(&pressure_ctx, sequence, effective_req.sync_level, sync_targets);
        if (profile) |active_profile| recordProfileNs(profile, &active_profile.backlog_pressure_ns, backlog_pressure_start_ns);
        const wait_sync_start_ns = monotonicTimeNs();
        if (self.executor.hasWorkers()) {
            const notify_executor_start_ns = monotonicTimeNs();
            notifyExecutorForSyncLevelWithDenseBulkDeferral(self.async_context, self.executor, effective_req.sync_level, sequence, sync_targets);
            if (profile) |active_profile| recordProfileNs(profile, &active_profile.executor_notify_ns, notify_executor_start_ns);
            if (opts.wait_for_sync_level) {
                const sync_wait_start_ns = monotonicTimeNs();
                try self.waitForSyncLevel(effective_req.sync_level, sequence, sync_targets);
                if (profile) |active_profile| recordProfileNs(profile, &active_profile.sync_wait_ns, sync_wait_start_ns);
            }
        } else {
            if (opts.wait_for_sync_level and syncLevelRequiresDerivedVisibility(effective_req.sync_level)) {
                const derived_apply_start_ns = monotonicTimeNs();
                if (effective_req.sync_level == .full_text) {
                    try applyDerivedBatchTargetsProfiled(self, materialized_derived_batch.?, sync_targets.full_text_indexes, profile);
                } else {
                    try applyDerivedBatchProfiled(self, materialized_derived_batch.?, profile);
                }
                if (profile) |active_profile| recordProfileNs(profile, &active_profile.derived_apply_ns, derived_apply_start_ns);
            }
            if (opts.wait_for_sync_level) {
                const sync_wait_start_ns = monotonicTimeNs();
                try self.waitForSyncLevel(effective_req.sync_level, sequence, sync_targets);
                if (profile) |active_profile| recordProfileNs(profile, &active_profile.sync_wait_ns, sync_wait_start_ns);
            }
        }
        if (opts.wait_for_sync_level and effective_req.sync_level == .full_index and self.text_merge_runtime == null) {
            try self.drainScheduledTextMerges();
        }
        if (profile) |active_profile| recordProfileNs(profile, &active_profile.wait_sync_ns, wait_sync_start_ns);
        if (self.enrichment_runtime) |runtime| {
            const notify_enrichment_start_ns = monotonicTimeNs();
            runtime.notifySequence(sequence);
            if (profile) |active_profile| recordProfileNs(profile, &active_profile.notify_enrichment_ns, notify_enrichment_start_ns);
        }
        self.notifyResolverReplayRuntimes(sequence);
    }

    /// Inject (or clear) the cross-shard entity-resolution candidate source on
    /// an already-open DB. The serving layer (managed write cache) calls this
    /// right after a DB is opened, since managed DBs open lazily and cannot
    /// thread the source through `OpenOptions`. No-op when this DB has no
    /// resolution runtime (e.g. read-only / status opens).
    pub fn setResolutionCandidateSource(self: *DB, src: ?resolution_runtime_mod.CandidateSource) void {
        self.resolution_candidate_source = src;
        if (self.resolution_runtime) |runtime| runtime.setCandidateSource(src);
    }

    /// Inject (or clear) the cross-shard entity sink on an already-open DB. The
    /// serving layer (managed write cache) calls this right after a DB is opened,
    /// since managed DBs open lazily and cannot thread the sink through
    /// `OpenOptions`. No-op when this DB has no promotion runtime.
    pub fn setEntitySink(self: *DB, sink: ?promotion_runtime_mod.EntitySink) void {
        self.entity_sink = sink;
        if (self.promotion_runtime) |runtime| runtime.setSink(sink);
    }

    /// Inject (or clear) the source-shard promotion owner on an already-open DB.
    /// Serving-layer managed DBs use this to keep follower raft apply from
    /// turning replay into public entity-table writes.
    pub fn setPromotionOwner(self: *DB, owner: ?promotion_runtime_mod.PromotionOwner) void {
        self.promotion_owner = owner;
        if (self.promotion_runtime) |runtime| runtime.setOwner(owner);
    }

    fn failIfIdentityOrdinalExhaustedForNewUpserts(self: *DB, doc_ids: []const []const u8) !void {
        if (doc_ids.len == 0) return;

        var txn = try self.core.store.beginProbeTxn();
        defer txn.abort();

        const raw_next = txn.get(internal_keys.identity_next_ordinal_key[0..]) catch |err| switch (err) {
            error.NotFound => return,
            else => return err,
        };
        if (raw_next.len != @sizeOf(doc_identity.DocOrdinal)) return error.InvalidDocIdentity;
        const next_ordinal = std.mem.readInt(doc_identity.DocOrdinal, raw_next[0..4], .big);
        if (next_ordinal != 0 and next_ordinal < std.math.maxInt(doc_identity.DocOrdinal)) return;

        var seen = std.StringHashMapUnmanaged(void).empty;
        defer seen.deinit(self.alloc);
        for (doc_ids) |doc_id| {
            if (seen.contains(doc_id)) continue;
            try seen.put(self.alloc, doc_id, {});
            if (try doc_identity.lookupOrdinalTxn(self.alloc, &txn, doc_id) != null) continue;
            return error.DocOrdinalExhausted;
        }
    }

    fn configureBulkIngestIdentityAllNewLocked(self: *DB) !void {
        self.clearBulkIngestIdentityAllNewLocked();
        if (!try self.primaryUserNamespaceIsEmptyLocked()) return;
        if (try doc_identity.loadAllNewTrustedStateForNamespace(self.core.store, self.core.identity_namespace)) |state| {
            self.bulk_ingest_identity_state = state;
            self.identity_visibility_summary_cache = state.visibility_summary;
            self.bulk_ingest_identity_all_new = true;
        }
    }

    fn clearBulkIngestIdentityAllNewLocked(self: *DB) void {
        self.bulk_ingest_identity_all_new = false;
        self.bulk_ingest_identity_state = .{};
        self.clearBulkIngestSeenDocKeysLocked();
    }

    fn clearBulkIngestSeenDocKeysLocked(self: *DB) void {
        var it = self.bulk_ingest_seen_doc_keys.keyIterator();
        while (it.next()) |key_ptr| self.alloc.free(@constCast(key_ptr.*));
        self.bulk_ingest_seen_doc_keys.clearRetainingCapacity();
    }

    fn primaryUserNamespaceIsEmptyLocked(self: *DB) !bool {
        var txn = try self.core.store.beginCurrentScanTxn();
        defer txn.abort();
        var cur = try txn.openCursor();
        defer cur.close();

        const lower = [_]u8{internal_keys.user_namespace};
        const first = (try cur.seekAtOrAfter(lower[0..])) orelse return true;
        return first.key.len == 0 or first.key[0] != internal_keys.user_namespace;
    }

    fn rememberBulkIngestAllNewIdentityUpserts(self: *DB, doc_ids: []const []const u8) !bool {
        var batch_seen = std.StringHashMapUnmanaged(void).empty;
        defer batch_seen.deinit(self.alloc);
        for (doc_ids) |doc_id| {
            if (self.bulk_ingest_seen_doc_keys.contains(doc_id)) return false;
            if (batch_seen.contains(doc_id)) return false;
            try batch_seen.put(self.alloc, doc_id, {});
        }

        for (doc_ids) |doc_id| {
            const owned = try self.alloc.dupe(u8, doc_id);
            errdefer self.alloc.free(owned);
            try self.bulk_ingest_seen_doc_keys.put(self.alloc, owned, {});
        }
        return true;
    }

    fn identityUpsertStoreWritesAreNew(write_indexes: []const usize, overwritten_flags: []const bool) bool {
        for (write_indexes) |write_index| {
            if (write_index >= overwritten_flags.len) return false;
            if (overwritten_flags[write_index]) return false;
        }
        return true;
    }

    fn CoalescedKeyValueRequest(comptime T: type) type {
        return struct {
            const Entry = struct {
                key: []const u8,
                value: ?[]const u8 = null,
                kind: enum { write, delete },
                owned_key: bool = false,
                owned_value: bool = false,
            };

            entries: []Entry = &.{},
            writes: []T = &.{},
            deletes: [][]const u8 = &.{},

            fn deinit(self: *@This(), alloc: Allocator) void {
                for (self.entries) |entry| {
                    if (entry.owned_key) alloc.free(@constCast(entry.key));
                    if (entry.owned_value) alloc.free(@constCast(entry.value.?));
                }
                if (self.entries.len > 0) alloc.free(self.entries);
                if (self.writes.len > 0) alloc.free(self.writes);
                if (self.deletes.len > 0) alloc.free(self.deletes);
                self.* = .{};
            }
        };
    }

    const BulkIngestCoalescer = struct {
        const Stats = struct {
            active_session: std.atomic.Value(u8) = .init(0),
            staged_keys: AtomicU64 = .init(0),
            stage_batches: AtomicU64 = .init(0),
            stage_writes: AtomicU64 = .init(0),
            stage_deletes: AtomicU64 = .init(0),
            stage_transforms: AtomicU64 = .init(0),
            flush_calls: AtomicU64 = .init(0),
            flushed_keys: AtomicU64 = .init(0),

            fn snapshot(self: *const @This()) types.BulkCoalescingStats {
                return .{
                    .active_session = self.active_session.load(.monotonic) != 0,
                    .staged_keys = self.staged_keys.load(.monotonic),
                    .stage_batches = self.stage_batches.load(.monotonic),
                    .stage_writes = self.stage_writes.load(.monotonic),
                    .stage_deletes = self.stage_deletes.load(.monotonic),
                    .stage_transforms = self.stage_transforms.load(.monotonic),
                    .flush_calls = self.flush_calls.load(.monotonic),
                    .flushed_keys = self.flushed_keys.load(.monotonic),
                };
            }
        };

        const Entry = struct {
            key: []u8,
            value: ?[]u8 = null,
            kind: enum { write, delete },
        };

        const RequestView = struct {
            writes: []types.BatchWrite = &.{},
            deletes: [][]const u8 = &.{},

            fn deinit(self: @This(), alloc: Allocator) void {
                if (self.writes.len > 0) alloc.free(self.writes);
                if (self.deletes.len > 0) alloc.free(self.deletes);
            }
        };

        active: bool = false,
        entries: std.ArrayListUnmanaged(Entry) = .empty,
        positions: std.StringHashMapUnmanaged(usize) = .empty,
        stats: Stats = .{},

        fn begin(self: *@This()) void {
            self.active = true;
            self.stats.active_session.store(1, .monotonic);
        }

        fn deinit(self: *@This(), alloc: Allocator) void {
            self.clear(alloc);
            self.entries.deinit(alloc);
            self.positions.deinit(alloc);
            self.* = .{};
        }

        fn clear(self: *@This(), alloc: Allocator) void {
            self.resetPending(alloc);
            self.active = false;
            self.stats.active_session.store(0, .monotonic);
        }

        fn resetPending(self: *@This(), alloc: Allocator) void {
            for (self.entries.items) |entry| {
                alloc.free(entry.key);
                if (entry.value) |value| alloc.free(value);
            }
            self.entries.clearRetainingCapacity();
            self.positions.clearRetainingCapacity();
            self.stats.staged_keys.store(0, .monotonic);
        }

        fn hasPending(self: *const @This()) bool {
            return self.entries.items.len > 0;
        }

        fn snapshotRequestView(self: *const @This(), alloc: Allocator) !RequestView {
            var result = RequestView{};
            errdefer result.deinit(alloc);

            var write_count: usize = 0;
            var delete_count: usize = 0;
            for (self.entries.items) |entry| {
                switch (entry.kind) {
                    .write => write_count += 1,
                    .delete => delete_count += 1,
                }
            }

            if (write_count > 0) result.writes = try alloc.alloc(types.BatchWrite, write_count);
            if (delete_count > 0) result.deletes = try alloc.alloc([]const u8, delete_count);

            var write_index: usize = 0;
            var delete_index: usize = 0;
            for (self.entries.items) |entry| {
                switch (entry.kind) {
                    .write => {
                        result.writes[write_index] = .{
                            .key = entry.key,
                            .value = entry.value.?,
                        };
                        write_index += 1;
                    },
                    .delete => {
                        result.deletes[delete_index] = entry.key;
                        delete_index += 1;
                    },
                }
            }
            return result;
        }

        fn stageBatch(self: *@This(), db: *DB, req: types.BatchRequest) !void {
            std.debug.assert(self.active);
            _ = self.stats.stage_batches.fetchAdd(1, .monotonic);
            _ = self.stats.stage_writes.fetchAdd(@intCast(req.writes.len), .monotonic);
            _ = self.stats.stage_deletes.fetchAdd(@intCast(req.deletes.len), .monotonic);
            _ = self.stats.stage_transforms.fetchAdd(@intCast(req.transforms.len), .monotonic);

            for (req.writes) |write| {
                try self.stageWrite(db.alloc, write.key, write.value);
            }
            for (req.deletes) |key| {
                try self.stageDelete(db.alloc, key);
            }
            for (req.transforms) |transform| {
                try self.stageTransform(db, transform);
            }
            self.stats.staged_keys.store(@intCast(self.entries.items.len), .monotonic);
        }

        fn stageWrite(self: *@This(), alloc: Allocator, key: []const u8, value: []const u8) !void {
            const gop = try self.positions.getOrPut(alloc, key);
            if (!gop.found_existing) {
                const owned_key = try alloc.dupe(u8, key);
                errdefer alloc.free(owned_key);
                const owned_value = try alloc.dupe(u8, value);
                errdefer alloc.free(owned_value);
                gop.key_ptr.* = owned_key;
                gop.value_ptr.* = self.entries.items.len;
                try self.entries.append(alloc, .{
                    .key = owned_key,
                    .value = owned_value,
                    .kind = .write,
                });
                return;
            }

            const entry = &self.entries.items[gop.value_ptr.*];
            if (entry.value) |existing| alloc.free(existing);
            entry.value = try alloc.dupe(u8, value);
            entry.kind = .write;
        }

        fn stageDelete(self: *@This(), alloc: Allocator, key: []const u8) !void {
            const gop = try self.positions.getOrPut(alloc, key);
            if (!gop.found_existing) {
                const owned_key = try alloc.dupe(u8, key);
                errdefer alloc.free(owned_key);
                gop.key_ptr.* = owned_key;
                gop.value_ptr.* = self.entries.items.len;
                try self.entries.append(alloc, .{
                    .key = owned_key,
                    .kind = .delete,
                });
                return;
            }

            const entry = &self.entries.items[gop.value_ptr.*];
            if (entry.value) |existing| {
                alloc.free(existing);
                entry.value = null;
            }
            entry.kind = .delete;
        }

        fn stageTransform(self: *@This(), db: *DB, transform: types.DocumentTransform) !void {
            const existing = if (self.positions.get(transform.key)) |entry_index|
                switch (self.entries.items[entry_index].kind) {
                    .write => self.entries.items[entry_index].value,
                    .delete => null,
                }
            else
                try db.get(db.alloc, transform.key);
            defer if (self.positions.get(transform.key) == null) {
                if (existing) |body| db.alloc.free(body);
            };

            const resolved = try transform_mod.resolveDocumentTransform(db.alloc, existing, transform) orelse return;
            errdefer db.alloc.free(resolved);
            try self.stageWriteOwned(db.alloc, transform.key, resolved);
        }

        fn stageWriteOwned(self: *@This(), alloc: Allocator, key: []const u8, owned_value: []u8) !void {
            const gop = try self.positions.getOrPut(alloc, key);
            if (!gop.found_existing) {
                const owned_key = try alloc.dupe(u8, key);
                errdefer alloc.free(owned_key);
                gop.key_ptr.* = owned_key;
                gop.value_ptr.* = self.entries.items.len;
                try self.entries.append(alloc, .{
                    .key = owned_key,
                    .value = owned_value,
                    .kind = .write,
                });
                return;
            }

            const entry = &self.entries.items[gop.value_ptr.*];
            if (entry.value) |existing| alloc.free(existing);
            entry.value = owned_value;
            entry.kind = .write;
        }
    };

    fn resetCoalescedEntryToDelete(comptime T: type, entry: *CoalescedKeyValueRequest(T).Entry) void {
        if (entry.owned_value) {
            // Caller frees previous owned value before switching the entry.
            entry.owned_value = false;
        }
        entry.value = null;
        entry.kind = .delete;
    }

    fn setCoalescedEntryToBorrowedWrite(comptime T: type, entry: *CoalescedKeyValueRequest(T).Entry, write: T) void {
        entry.key = write.key;
        entry.value = write.value;
        entry.kind = .write;
        entry.owned_key = false;
        entry.owned_value = false;
    }

    fn setCoalescedEntryToOwnedWrite(
        comptime T: type,
        alloc: Allocator,
        entry: *CoalescedKeyValueRequest(T).Entry,
        key: []const u8,
        value: []u8,
    ) !void {
        if (!entry.owned_key) {
            entry.key = try alloc.dupe(u8, key);
            entry.owned_key = true;
        }
        entry.value = value;
        entry.kind = .write;
        entry.owned_value = true;
    }

    fn coalesceKeyValueRequest(
        self: *DB,
        comptime T: type,
        writes: []const T,
        deletes: []const []const u8,
        transforms: []const types.DocumentTransform,
    ) !CoalescedKeyValueRequest(T) {
        var result = CoalescedKeyValueRequest(T){};
        var order = std.ArrayListUnmanaged(CoalescedKeyValueRequest(T).Entry).empty;
        errdefer {
            result.entries = order.items;
            order.items = &.{};
            order.capacity = 0;
            result.deinit(self.alloc);
        }
        defer order.deinit(self.alloc);

        var positions = std.StringHashMapUnmanaged(usize){};
        defer positions.deinit(self.alloc);

        for (writes) |write| {
            const gop = try positions.getOrPut(self.alloc, write.key);
            if (!gop.found_existing) {
                gop.value_ptr.* = order.items.len;
                try order.append(self.alloc, .{
                    .key = write.key,
                    .value = write.value,
                    .kind = .write,
                });
                continue;
            }
            const entry = &order.items[gop.value_ptr.*];
            if (entry.owned_value) self.alloc.free(@constCast(entry.value.?));
            if (entry.owned_key) self.alloc.free(@constCast(entry.key));
            setCoalescedEntryToBorrowedWrite(T, entry, write);
        }

        for (deletes) |key| {
            const gop = try positions.getOrPut(self.alloc, key);
            if (!gop.found_existing) {
                gop.value_ptr.* = order.items.len;
                try order.append(self.alloc, .{
                    .key = key,
                    .kind = .delete,
                });
                continue;
            }
            const entry = &order.items[gop.value_ptr.*];
            if (entry.owned_value) self.alloc.free(@constCast(entry.value.?));
            entry.owned_value = false;
            resetCoalescedEntryToDelete(T, entry);
        }

        for (transforms) |transform| {
            const maybe_index = positions.get(transform.key);
            const base_json = blk: {
                if (maybe_index) |entry_index| {
                    const entry = order.items[entry_index];
                    break :blk if (entry.kind == .write) entry.value.? else null;
                }
                break :blk try self.get(self.alloc, transform.key);
            };
            defer if (maybe_index == null) {
                if (base_json) |body| self.alloc.free(body);
            };

            const resolved = try transform_mod.resolveDocumentTransform(self.alloc, base_json, transform) orelse {
                if (maybe_index == null) continue;
                const entry = order.items[maybe_index.?];
                if (entry.kind == .delete) continue;
                continue;
            };
            errdefer self.alloc.free(resolved);

            const gop = try positions.getOrPut(self.alloc, transform.key);
            if (!gop.found_existing) {
                gop.value_ptr.* = order.items.len;
                try order.append(self.alloc, .{
                    .key = try self.alloc.dupe(u8, transform.key),
                    .value = resolved,
                    .kind = .write,
                    .owned_key = true,
                    .owned_value = true,
                });
                continue;
            }

            const entry = &order.items[gop.value_ptr.*];
            if (entry.owned_value) self.alloc.free(@constCast(entry.value.?));
            try setCoalescedEntryToOwnedWrite(T, self.alloc, entry, transform.key, resolved);
        }

        var write_count: usize = 0;
        var delete_count: usize = 0;
        for (order.items) |entry| {
            switch (entry.kind) {
                .write => write_count += 1,
                .delete => delete_count += 1,
            }
        }

        const final_entries = try order.toOwnedSlice(self.alloc);
        result.entries = final_entries;
        if (write_count > 0) result.writes = try self.alloc.alloc(T, write_count);
        if (delete_count > 0) result.deletes = try self.alloc.alloc([]const u8, delete_count);

        var write_index: usize = 0;
        var delete_index: usize = 0;
        for (final_entries) |entry| {
            switch (entry.kind) {
                .write => {
                    result.writes[write_index] = .{
                        .key = entry.key,
                        .value = entry.value.?,
                    };
                    write_index += 1;
                },
                .delete => {
                    result.deletes[delete_index] = entry.key;
                    delete_index += 1;
                },
            }
        }
        return result;
    }

    fn flushBulkIngestCoalescerWithSyncLevel(self: *DB, sync_level: types.SyncLevel, profile: ?*BatchProfile) anyerror!void {
        if (!self.bulk_ingest_coalescer.active or !self.bulk_ingest_coalescer.hasPending()) return;
        _ = self.bulk_ingest_coalescer.stats.flush_calls.fetchAdd(1, .monotonic);
        _ = self.bulk_ingest_coalescer.stats.flushed_keys.fetchAdd(@intCast(self.bulk_ingest_coalescer.entries.items.len), .monotonic);

        lockApply(self);
        var view = try self.bulk_ingest_coalescer.snapshotRequestView(self.alloc);
        self.core.unlockApply();
        defer view.deinit(self.alloc);

        self.flushing_bulk_ingest_coalescer = true;
        defer self.flushing_bulk_ingest_coalescer = false;

        try self.batchInternal(.{
            .writes = view.writes,
            .deletes = view.deletes,
            .sync_level = sync_level,
        }, profile, .{ .store_batch_options = .{ .mode = .bulk_ingest } });

        lockApply(self);
        defer self.core.unlockApply();
        self.bulk_ingest_coalescer.resetPending(self.alloc);
        self.bulk_ingest_coalescer.active = true;
    }

    pub fn get(self: *DB, alloc: Allocator, key: []const u8) !?[]u8 {
        if (self.relationalColumnsForStore() != null and !isMetadataKey(key) and !internal_keys.isInternalPhysicalTableDataKey(key)) {
            return try relational_store_mod.getMaterializedAlloc(alloc, self.core.store, key);
        }
        const store_key = try encodeStoreLookupKeyAlloc(alloc, key);
        defer alloc.free(store_key);
        const value = try self.core.getStoreValue(alloc, store_key) orelse return null;
        return try mapper.materializeOwnedDocumentValueAlloc(alloc, value);
    }

    pub fn getRawStoreValue(self: *DB, alloc: Allocator, key: []const u8) !?[]u8 {
        return self.core.getStoreValue(alloc, key) catch |err| switch (err) {
            error.NotFound => null,
            else => err,
        };
    }

    pub fn lookupRelationalTemporalUniqueOwner(
        self: *DB,
        alloc: Allocator,
        constraint_name: []const u8,
        encoded_value: []const u8,
        encoded_point: []const u8,
    ) !?[]u8 {
        return try relational_store_mod.lookupTemporalUniqueOwnerAlloc(alloc, self.core.store, constraint_name, encoded_value, encoded_point);
    }

    pub fn lookupRelationalTemporalUniqueOverlapOwner(
        self: *DB,
        alloc: Allocator,
        constraint_name: []const u8,
        encoded_value: []const u8,
        encoded_start: []const u8,
        encoded_end: []const u8,
    ) !?[]u8 {
        return try relational_store_mod.lookupTemporalUniqueOverlapOwnerAlloc(alloc, self.core.store, constraint_name, encoded_value, encoded_start, encoded_end);
    }

    pub fn getGroupCreatedAtMillis(self: *DB, alloc: Allocator, group_id: u64) !?u64 {
        const key = try groupCreatedAtMetadataKeyAlloc(alloc, group_id);
        defer alloc.free(key);
        const raw = try self.get(alloc, key) orelse return null;
        defer alloc.free(raw);
        return try std.fmt.parseInt(u64, raw, 10);
    }

    pub fn ensureGroupCreatedAtMillis(self: *DB, alloc: Allocator, group_id: u64, now_ms: u64) !u64 {
        if (try self.getGroupCreatedAtMillis(alloc, group_id)) |created_at_millis| return created_at_millis;

        const key = try groupCreatedAtMetadataKeyAlloc(alloc, group_id);
        defer alloc.free(key);
        const encoded = try std.fmt.allocPrint(alloc, "{d}", .{now_ms});
        defer alloc.free(encoded);

        try self.batch(.{
            .writes = &.{
                .{
                    .key = key,
                    .value = encoded,
                },
            },
        });
        return now_ms;
    }

    pub fn getArtifact(self: *DB, alloc: Allocator, artifact_id: []const u8) !?types.ArtifactRecord {
        var artifact_ref = (try artifact_ids.decodeArtifactPublicIdAlloc(alloc, artifact_id)) orelse return error.InvalidArgument;
        errdefer artifact_ref.deinit(alloc);

        const internal_key = try artifact_ids.internalKeyForArtifactRefAlloc(alloc, artifact_ref);
        defer alloc.free(internal_key);

        const value = try self.core.getStoreValue(alloc, internal_key) orelse return null;
        errdefer alloc.free(value);

        return .{
            .id = try alloc.dupe(u8, artifact_id),
            .value = value,
            .artifact_ref = artifact_ref,
        };
    }

    pub fn getDocument(self: *DB, alloc: Allocator, key: []const u8, opts: types.LookupOptions) !?types.LookupResult {
        return try self.lookup(alloc, key, opts);
    }

    pub fn lookup(self: *DB, alloc: Allocator, key: []const u8, opts: types.LookupOptions) !?types.LookupResult {
        if (!internal_keys.isInternalPhysicalTableDataKey(key) and (try isExpiredDocumentKey(self, alloc, key))) return null;
        const raw = try self.get(alloc, key) orelse return null;
        defer alloc.free(raw);
        const stored = try projectLookupStoredBytes(self, alloc, key, raw, opts);
        return .{ .json = stored };
    }

    pub fn getTimestamp(self: *DB, alloc: Allocator, key: []const u8) !u64 {
        if (internal_keys.isInternalPhysicalTableDataKey(key)) return 0;
        return try self.core.readTimestamp(alloc, key);
    }

    pub fn updateRange(self: *DB, byte_range: types.ByteRange) !void {
        lockApply(self);
        defer self.core.unlockApply();
        try self.core.updateRange(byte_range);
    }

    pub fn getRange(self: *DB) types.ByteRange {
        return self.core.byteRange();
    }

    pub fn findMedianKey(self: *DB, alloc: Allocator) ![]u8 {
        const byte_range = self.getRange();
        const lower = try self.core.documentRangeLowerAlloc(byte_range.start);
        defer self.core.alloc.free(lower);
        const upper = if (byte_range.end.len > 0) try self.core.documentRangeUpperAlloc(byte_range.end) else null;
        defer if (upper) |buf| self.core.alloc.free(buf);

        const skip_fn = if (self.relationalColumnsForStore() != null)
            &skipNonRelationalMedianKey
        else
            &skipNonPrimaryMedianKey;
        const internal_key = self.core.findMedianStoreKey(alloc, lower, if (upper) |buf| buf else "", .{
            .skip_fn = skip_fn,
        }) catch |err| switch (err) {
            error.NotFound => return try doc_identity.findMedianDocIdAlloc(alloc, self.core.store, byte_range.start, byte_range.end),
            else => return err,
        };
        defer alloc.free(internal_key);

        return (try internal_keys.decodeStoredDocumentRowKeyAlloc(alloc, internal_key)) orelse error.NotFound;
    }

    pub fn getSplitState(self: *DB, alloc: Allocator) !?types.SplitState {
        lockApplyShared(self);
        defer self.core.unlockApplyShared();
        const state = self.core.splitState() orelse return null;
        return .{
            .phase = state.phase,
            .split_key = try alloc.dupe(u8, state.split_key),
            .new_shard_id = state.new_shard_id,
            .started_at = state.started_at,
            .original_range_end = try alloc.dupe(u8, state.original_range_end),
        };
    }

    pub fn setSplitState(self: *DB, state: ?types.SplitState) !void {
        lockApply(self);
        defer self.core.unlockApply();
        if (state == null) {
            try self.core.setSplitState(null);
            return;
        }
        try self.core.setSplitState(.{
            .phase = state.?.phase,
            .split_key = state.?.split_key,
            .new_shard_id = state.?.new_shard_id,
            .started_at = state.?.started_at,
            .original_range_end = state.?.original_range_end,
        });
    }

    pub fn clearSplitState(self: *DB) !void {
        try self.setSplitState(null);
    }

    pub fn getSplitDeltaSeq(self: *DB) u64 {
        return self.core.splitDeltaSequence();
    }

    pub fn getSplitDeltaFinalSeq(self: *DB, alloc: Allocator) !u64 {
        return try self.core.loadSplitDeltaFinalSeq(alloc);
    }

    pub fn setSplitDeltaFinalSeq(self: *DB, seq: u64) !void {
        lockApply(self);
        defer self.core.unlockApply();
        try self.core.saveSplitDeltaFinalSeq(seq);
    }

    pub fn clearSplitDeltaFinalSeq(self: *DB) !void {
        lockApply(self);
        defer self.core.unlockApply();
        try self.core.clearSplitDeltaFinalSeq();
    }

    pub fn listSplitDeltaEntriesAfter(self: *DB, alloc: Allocator, after_seq: u64) ![]types.SplitDeltaEntry {
        lockApplyShared(self);
        defer self.core.unlockApplyShared();

        const deltas = try self.core.listSplitDeltasAfter(alloc, after_seq);
        defer shard_mod.freeDeltas(alloc, deltas);

        var entries = std.ArrayListUnmanaged(types.SplitDeltaEntry).empty;
        errdefer {
            for (entries.items) |*entry| entry.deinit(alloc);
            entries.deinit(alloc);
        }

        for (deltas) |delta| {
            var writes = try alloc.alloc(types.BatchWrite, delta.writes.len);
            errdefer alloc.free(writes);
            for (delta.writes, 0..) |write, i| {
                writes[i] = .{
                    .key = try alloc.dupe(u8, write.key),
                    .value = try alloc.dupe(u8, write.value),
                };
            }

            var deletes = try alloc.alloc([]u8, delta.deletes.len);
            errdefer {
                for (deletes) |key| alloc.free(key);
                alloc.free(deletes);
            }
            for (delta.deletes, 0..) |key, i| {
                deletes[i] = try alloc.dupe(u8, key);
            }

            try entries.append(alloc, .{
                .sequence = delta.sequence,
                .timestamp = delta.timestamp,
                .writes = writes,
                .deletes = deletes,
            });
        }

        return try entries.toOwnedSlice(alloc);
    }

    pub fn clearSplitDeltaEntries(self: *DB) !void {
        lockApply(self);
        defer self.core.unlockApply();
        try self.core.clearSplitDeltas();
    }

    pub fn createShadowIndexManager(self: *DB, split_key: []const u8, original_range_end: []const u8) !void {
        lockApply(self);
        defer self.core.unlockApply();
        if (self.shadow != null) return error.ShadowIndexManagerExists;

        const base_path = try std.fmt.allocPrint(self.alloc, "{s}/.shadow-{d}", .{ self.core.path, monotonicTimeNs() });
        errdefer self.alloc.free(base_path);
        const indexes_path = try std.fmt.allocPrint(self.alloc, "{s}/indexes", .{base_path});
        errdefer self.alloc.free(indexes_path);

        try ensureDirPath(indexes_path);

        const shadow_manager = try self.alloc.create(index_manager_mod.IndexManager);
        errdefer self.alloc.destroy(shadow_manager);
        shadow_manager.* = try index_manager_mod.IndexManager.initWithOptions(
            self.alloc,
            base_path,
            self.index_backends,
        );
        errdefer shadow_manager.deinit();
        shadow_manager.setRelationalBaseRows(self.relationalColumnsForStore() != null);

        const shadow_start = try self.alloc.dupe(u8, split_key);
        errdefer self.alloc.free(shadow_start);
        const shadow_end = try self.alloc.dupe(u8, original_range_end);
        errdefer self.alloc.free(shadow_end);
        shadow_manager.updateRange(.{ .start = shadow_start, .end = shadow_end });

        try self.core.registerShadowIndexes(self.alloc, shadow_manager);

        self.shadow = .{
            .manager = shadow_manager,
            .base_path = base_path,
            .indexes_path = indexes_path,
            .range_start = shadow_start,
            .range_end = shadow_end,
        };
    }

    pub fn closeShadowIndexManager(self: *DB) !void {
        const shadow = self.shadow orelse return;
        shadow.manager.deinit();
        self.alloc.destroy(shadow.manager);
        self.alloc.free(shadow.base_path);
        self.alloc.free(shadow.indexes_path);
        self.alloc.free(shadow.range_start);
        self.alloc.free(shadow.range_end);
        self.shadow = null;
    }

    pub fn getShadowIndexDir(self: *DB) []const u8 {
        const shadow = self.shadow orelse return "";
        return shadow.indexes_path;
    }

    pub fn split(
        self: *DB,
        curr_range: types.ByteRange,
        split_key: []const u8,
        dest_dir1: []const u8,
        dest_dir2: []const u8,
        prepare_only: bool,
    ) !void {
        _ = dest_dir1;
        while (true) {
            const target_sequence = self.core.nextDerivedSequence();
            try self.runMaintenanceUntil(target_sequence, .{});

            lockApply(self);
            if (self.core.nextDerivedSequence() == target_sequence) break;
            self.core.unlockApply();
        }
        defer self.core.unlockApply();

        if (!byteRangesEqual(self.core.byteRange(), curr_range)) return error.KeyOutOfRange;
        if (!curr_range.contains(split_key)) return error.KeyOutOfRange;

        const range2 = types.ByteRange{
            .start = split_key,
            .end = curr_range.end,
        };

        if (self.core.splitState() == null) {
            try self.core.prepareSplit(split_key);
        }

        try prepareSplitDestination(self, range2, dest_dir2);
        if (prepare_only) return;

        try finalizeSplitLocked(self, .{
            .start = curr_range.start,
            .end = split_key,
        });
    }

    pub fn finalizeSplit(self: *DB, new_range: types.ByteRange) !void {
        lockApply(self);
        defer self.core.unlockApply();
        try finalizeSplitLocked(self, new_range);
    }

    pub fn snapshot(self: *DB, id: []const u8) !u64 {
        lockApply(self);
        defer self.core.unlockApply();

        try self.core.syncStore(true);

        const snapshot_root = try std.fmt.allocPrint(self.alloc, "{s}.snapshots/{s}", .{ self.core.path, id });
        defer self.alloc.free(snapshot_root);
        try ensureDirPath(snapshot_root);

        return try self.core.writeSnapshot(snapshot_root);
    }

    pub fn sync(self: *DB, full: bool) !void {
        lockApply(self);
        defer self.core.unlockApply();
        try self.core.syncStore(full);
    }

    fn restoreSnapshotStoreTo(alloc: Allocator, snapshot_root: []const u8, path: []const u8, opts: OpenOptions, restore_identity: ?RestoreIdentity) !void {
        if (restore_identity) |identity| try beginRestoreImport(alloc, path, snapshot_root, identity);
        var opened_primary = try openPrimaryStore(alloc, path, .{
            .map_size = opts.map_size,
            .no_sync = opts.no_sync,
            .primary_backend = opts.primary_backend,
            .storage = opts.storage,
            .index_backends = opts.index_backends,
        });
        defer {
            opened_primary.store.close();
            opened_primary.owner.close(alloc);
        }

        try db_core.clearAllKeysFromStore(alloc, &opened_primary.store);
        try db_core.importStoreSnapshot(alloc, &opened_primary.store, snapshot_root);
        try doc_identity.validateStoreAlloc(alloc, &opened_primary.store);
        try validateRestoredIdentityNamespace(&opened_primary.store, opts);
        try db_core.importChangeJournalSnapshot(alloc, &opened_primary.store, snapshot_root);
        if (restore_identity) |identity| try markRestorePrimaryRestored(
            alloc,
            path,
            identity.backup_id,
            identity.location,
            identity.snapshot_path,
            identity.group_id,
        );
    }

    fn validateRestoredIdentityNamespace(store: *docstore_mod.DocStore, opts: OpenOptions) !void {
        if (opts.identity_namespace == null or opts.prefer_existing_identity_namespace) return;
        const stored = (try doc_identity.loadNamespaceFromStore(store)) orelse return;
        if (!stored.eql(opts.identity_namespace.?)) return error.IdentityNamespaceMismatch;
    }

    pub fn restoreSnapshotTo(alloc: Allocator, snapshot_root: []const u8, path: []const u8, opts: OpenOptions) !void {
        try restoreSnapshotStoreTo(alloc, snapshot_root, path, opts, null);
        // Graph reverse indexes are derived from stored outgoing edge keys, so
        // restore them after the logical store and derived log are rehydrated.
        var restored = try DB.open(alloc, path, opts);
        defer restored.close();
        _ = try restored.core.index_manager.rebuildGraphSplitDestination(
            restored.getRange().start,
            restored.getRange().end,
        );
    }

    pub fn restoreSnapshotToDeferredRuntimeRepair(
        alloc: Allocator,
        snapshot_root: []const u8,
        path: []const u8,
        opts: OpenOptions,
        identity: RestoreIdentity,
    ) !void {
        try restoreSnapshotStoreTo(alloc, snapshot_root, path, opts, identity);
    }

    fn beginRestoreImport(alloc: Allocator, path: []const u8, snapshot_root: []const u8, identity: RestoreIdentity) !void {
        try ensureDirPath(path);
        const repair_marker_path = try restoreRepairMarkerPathAlloc(alloc, path);
        defer alloc.free(repair_marker_path);
        const restore_intent_path = try restoreIntentMarkerPathAlloc(alloc, path);
        defer alloc.free(restore_intent_path);
        const restore_state_path = try restoreStateMarkerPathAlloc(alloc, path);
        defer alloc.free(restore_state_path);
        const import_marker_path = try restoreImportMarkerPathAlloc(alloc, path);
        defer alloc.free(import_marker_path);

        var io_impl = threadedIo();
        defer io_impl.deinit();
        const io = io_impl.io();
        try deleteFileIfExists(io, repair_marker_path);
        try deleteFileIfExists(io, restore_intent_path);
        try deleteFileIfExists(io, restore_state_path);
        const marker = try std.fmt.allocPrint(
            alloc,
            "restore_import_v1\nsnapshot_root={s}\nbackup_id={s}\nlocation={s}\nsnapshot_path={s}\ngroup_id={d}\n",
            .{
                snapshot_root,
                identity.backup_id,
                identity.location,
                identity.snapshot_path,
                identity.group_id,
            },
        );
        defer alloc.free(marker);
        try std.Io.Dir.cwd().writeFile(io, .{
            .sub_path = import_marker_path,
            .data = marker,
        });
    }

    pub fn recoverIncompleteRestoreImportIfNeeded(alloc: Allocator, path: []const u8, opts: OpenOptions) !bool {
        if (try readRestoreStateForPathAlloc(alloc, path)) |state_value| {
            var state = state_value;
            state.deinit(alloc);
            return false;
        }

        var import_state = (try readRestoreImportStateAlloc(alloc, path)) orelse return false;
        defer import_state.deinit(alloc);
        const identity_state = import_state.identity orelse return error.InvalidRestoreImportMarker;
        const identity: RestoreIdentity = .{
            .backup_id = identity_state.backup_id,
            .location = identity_state.location,
            .snapshot_path = identity_state.snapshot_path,
            .group_id = identity_state.group_id,
        };
        std.log.warn("recovering incomplete restore import path={s} snapshot_root={s}", .{ path, import_state.snapshot_root });
        try restoreSnapshotStoreTo(alloc, import_state.snapshot_root, path, opts, identity);
        return true;
    }

    pub fn readRestoreStateForPath(alloc: Allocator, path: []const u8) !?RestoreState {
        return try readRestoreStateForPathAlloc(alloc, path);
    }

    pub fn markRestorePrimaryRestoredForPath(
        alloc: Allocator,
        path: []const u8,
        backup_id: []const u8,
        location: []const u8,
        snapshot_path: []const u8,
        group_id: u64,
    ) !void {
        try markRestorePrimaryRestored(alloc, path, backup_id, location, snapshot_path, group_id);
    }

    fn markRestorePrimaryRestored(
        alloc: Allocator,
        path: []const u8,
        backup_id: []const u8,
        location: []const u8,
        snapshot_path: []const u8,
        group_id: u64,
    ) !void {
        var state = try restoreStateAlloc(alloc, backup_id, location, snapshot_path, group_id, "runtime_repair", true, false, "");
        defer state.deinit(alloc);
        try writeRestoreStateForPath(alloc, path, state);
        const repair_marker_path = try restoreRepairMarkerPathAlloc(alloc, path);
        defer alloc.free(repair_marker_path);
        const import_marker_path = try restoreImportMarkerPathAlloc(alloc, path);
        defer alloc.free(import_marker_path);
        var io_impl = threadedIo();
        defer io_impl.deinit();
        const io = io_impl.io();
        try deleteFileIfExists(io, repair_marker_path);
        try deleteFileIfExists(io, import_marker_path);
    }

    pub fn restoreRuntimeRepairNeededForPath(alloc: Allocator, path: []const u8) !bool {
        var state = (try readRestoreStateForPathAlloc(alloc, path)) orelse return false;
        defer state.deinit(alloc);
        return state.primary_restored and !state.runtime_repair_complete;
    }

    fn markRestoreRuntimeRepairNeeded(alloc: Allocator, path: []const u8) !void {
        const repair_marker_path = try restoreRepairMarkerPathAlloc(alloc, path);
        defer alloc.free(repair_marker_path);
        const import_marker_path = try restoreImportMarkerPathAlloc(alloc, path);
        defer alloc.free(import_marker_path);
        var io_impl = threadedIo();
        defer io_impl.deinit();
        const io = io_impl.io();
        try deleteFileIfExists(io, repair_marker_path);

        var state = (try readRestoreStateForPathAlloc(alloc, path)) orelse return error.InvalidRestoreState;
        defer state.deinit(alloc);
        const new_phase = try alloc.dupe(u8, "runtime_repair");
        alloc.free(state.phase);
        state.phase = new_phase;
        state.primary_restored = true;
        state.runtime_repair_complete = false;
        try writeRestoreStateForPath(alloc, path, state);
        try deleteFileIfExists(io, import_marker_path);
    }

    fn markRestoreRuntimeRepairComplete(alloc: Allocator, path: []const u8) !void {
        var state = (try readRestoreStateForPathAlloc(alloc, path)) orelse return error.InvalidRestoreState;
        defer state.deinit(alloc);
        const new_phase = try alloc.dupe(u8, "complete");
        alloc.free(state.phase);
        state.phase = new_phase;
        state.primary_restored = true;
        state.runtime_repair_complete = true;
        try writeRestoreStateForPath(alloc, path, state);
        const repair_marker_path = try restoreRepairMarkerPathAlloc(alloc, path);
        defer alloc.free(repair_marker_path);
        var io_impl = threadedIo();
        defer io_impl.deinit();
        try std.Io.Dir.cwd().writeFile(io_impl.io(), .{
            .sub_path = repair_marker_path,
            .data = "done\n",
        });
    }

    pub fn restoreRuntimeRepairNeeded(self: *DB) !bool {
        return try restoreRuntimeRepairNeededForPath(self.alloc, self.core.path);
    }

    fn updateRestoreRuntimeRepairPhase(self: *DB, alloc: Allocator, phase: []const u8, complete: bool) !void {
        var state = (try readRestoreStateForPathAlloc(alloc, self.core.path)) orelse return error.InvalidRestoreState;
        defer state.deinit(alloc);
        const new_phase = try alloc.dupe(u8, phase);
        alloc.free(state.phase);
        state.phase = new_phase;
        state.primary_restored = true;
        state.runtime_repair_complete = complete;
        const new_last_error = try alloc.dupe(u8, "");
        alloc.free(state.last_error);
        state.last_error = new_last_error;
        try writeRestoreStateForPath(alloc, self.core.path, state);
    }

    pub fn repairRestoreRuntimeStateStepIfNeeded(self: *DB, alloc: Allocator) !bool {
        if (!try self.restoreRuntimeRepairNeeded()) return false;

        var state = (try readRestoreStateForPathAlloc(alloc, self.core.path)) orelse return false;
        defer state.deinit(alloc);
        const phase = state.phase;

        if (std.mem.eql(u8, phase, "runtime_repair") or std.mem.eql(u8, phase, "reset_watermarks")) {
            std.log.info("restore runtime repair reset managed index watermarks path={s}", .{self.core.path});
            try self.resetManagedIndexAppliedSequences();
            try self.refreshManagedIndexWorkersLocked();
            try self.updateRestoreRuntimeRepairPhase(alloc, "rebuild_graph", false);
            return true;
        }
        if (std.mem.eql(u8, phase, "rebuild_graph")) {
            std.log.info("restore runtime repair rebuild graph state path={s}", .{self.core.path});
            _ = try self.rebuildGraphDerivedState();
            try self.updateRestoreRuntimeRepairPhase(alloc, "rebuild_artifacts", false);
            return true;
        }
        if (std.mem.eql(u8, phase, "rebuild_artifacts")) {
            std.log.info("restore runtime repair rebuild stored embedding artifacts path={s}", .{self.core.path});
            _ = try self.rebuildDenseIndexesFromStoredEmbeddingArtifactsIfNeeded(alloc);
            try self.updateRestoreRuntimeRepairPhase(alloc, "replay_enrichments", false);
            return true;
        }
        if (std.mem.eql(u8, phase, "replay_enrichments")) {
            if (self.core.hasGeneratedEnrichmentTargets()) {
                if (self.enrichment_runtime == null) return error.RestoreRepairRequiresEnrichmentRuntime;
                std.log.info("restore runtime repair replay generated enrichments path={s}", .{self.core.path});
                _ = try self.replayGeneratedEnrichmentsFromStoredDocs(alloc);
            }
            try self.updateRestoreRuntimeRepairPhase(alloc, "drain_async", false);
            return true;
        }
        if (std.mem.eql(u8, phase, "drain_async")) {
            std.log.info("restore runtime repair drain async work path={s}", .{self.core.path});
            try self.runUntilIdle();
            try self.updateRestoreRuntimeRepairPhase(alloc, "sync_indexes", false);
            return true;
        }
        if (std.mem.eql(u8, phase, "sync_indexes")) {
            std.log.info("restore runtime repair sync indexes path={s}", .{self.core.path});
            try self.core.index_manager.syncAll(false);
            try markRestoreRuntimeRepairComplete(alloc, self.core.path);
            std.log.info("restore runtime repair marked complete path={s}", .{self.core.path});
            return true;
        }
        return error.InvalidRestoreState;
    }

    fn repairRestoreRuntimeStateIfNeeded(self: *DB, alloc: Allocator) !bool {
        var repaired = false;
        while (try self.restoreRuntimeRepairNeeded()) {
            _ = try self.repairRestoreRuntimeStateStepIfNeeded(alloc);
            repaired = true;
        }
        return repaired;
    }

    fn rebuildGraphDerivedState(self: *DB) !usize {
        lockApply(self);
        defer self.core.unlockApply();
        return try self.core.index_manager.rebuildGraphSplitDestination(
            self.getRange().start,
            self.getRange().end,
        );
    }

    pub fn clearDenseHbcCaches(self: *DB) void {
        self.core.index_manager.clearDenseHbcCaches();
    }

    fn setSchema(self: *DB, table_schema: schema_mod.TableSchema) !void {
        try validateRuntimeSchemaFeatureLevel(table_schema);
        try self.core.setSchema(table_schema);
        self.refreshSchemaRuntimeSideEffects();
    }

    fn validateRuntimeSchemaFeatureLevel(table_schema: schema_mod.TableSchema) !void {
        if (table_schema.storage_mode != .relational) return;
        for (table_schema.foreign_keys) |foreign_key| {
            if (foreign_key.validation_state == .validating or foreign_key.validation_state == .invalid) return error.InvalidSchemaUpdateRequest;
        }
    }

    fn refreshSchemaRuntimeSideEffects(self: *DB) void {
        const relational_base_rows = self.relationalColumnsForStore() != null;
        self.async_context.relational_base_rows = relational_base_rows;
        if (self.ttl_cleanup_context) |ctx| ctx.batch.relational_base_rows = relational_base_rows;
        if (self.enrichment_runtime) |runtime| runtime.setRelationalBaseRows(relational_base_rows);
        if (self.transaction_recovery_identity_context) |ctx| {
            ctx.relational_base_rows = relational_base_rows;
            ctx.relational_columns = self.relationalColumnsForStore() orelse &.{};
        }
    }

    pub const ApplyTableSchemaOptions = struct {
        persist_local_schema_json: bool = true,
        reload_algebraic_schema_configs: bool = true,
    };

    /// Apply table metadata schema JSON to the DB runtime and all schema-derived
    /// local artifacts. This is the single production entry point for table
    /// schema application so write-cache reconciliation, metadata provisioning,
    /// and crash recovery keep algebraic sidecars in the same lifecycle state.
    pub fn applyTableSchemaJson(
        self: *DB,
        alloc: Allocator,
        schema_json: []const u8,
        options: ApplyTableSchemaOptions,
    ) !void {
        if (schema_json.len == 0) return;
        if (openModeRequiresReadOnlyBackends(self.open_mode)) return error.ReadOnly;

        var parsed_schema = try schema_api_mod.parseValidatedTableSchema(alloc, schema_json);
        defer parsed_schema.deinit(alloc);

        const runtime_schema = try schema_api_mod.deriveRuntimeTableSchema(alloc, parsed_schema);
        defer schema_mod.freeSchema(alloc, runtime_schema);

        lockApply(self);
        defer self.core.unlockApply();

        try self.validateTableSchemaCompatibilityLocked(alloc, runtime_schema);
        if (options.reload_algebraic_schema_configs) {
            try self.stageAlgebraicSchemaConfigsPending(schema_json);
        }
        try self.migrateRelationalRowsForSchemaTransitionLocked(alloc, runtime_schema);
        try self.migrateRelationalConstraintsForSchemaTransitionLocked(alloc, runtime_schema);
        if (options.persist_local_schema_json) {
            try self.setSchemaWithLocalSchemaJson(runtime_schema, schema_json);
        } else {
            try self.setSchema(runtime_schema);
        }
        if (options.reload_algebraic_schema_configs) {
            try self.completePendingAlgebraicSchemaRebuilds();
        }
    }

    fn validateTableSchemaCompatibilityLocked(self: *DB, alloc: Allocator, next_schema: schema_mod.TableSchema) !void {
        if (self.core.schema) |current_schema| {
            return validateRuntimeTableSchemaTransition(current_schema, next_schema);
        }

        const durable_schema = try schema_mod.loadSchema(self.core.store, alloc);
        defer if (durable_schema) |loaded| schema_mod.freeSchema(alloc, loaded);
        if (durable_schema) |current_schema| {
            return validateRuntimeTableSchemaTransition(current_schema, next_schema);
        }

        try self.validateFirstTableSchemaApplyAgainstExistingRows(alloc, next_schema);
    }

    fn validateRuntimeTableSchemaTransition(current_schema: schema_mod.TableSchema, next_schema: schema_mod.TableSchema) !void {
        if (current_schema.storage_mode != next_schema.storage_mode) return error.InvalidSchemaUpdateRequest;
        if (next_schema.storage_mode != .relational) return;
        try validateRelationalColumnCatalogTransition(current_schema.relational_columns, next_schema.relational_columns);
        if (!schema_mod.primaryKeyCatalogsEqual(current_schema.primary_key, next_schema.primary_key)) {
            return error.InvalidSchemaUpdateRequest;
        }
        if (!schema_mod.relationalPeriodCatalogsEqual(current_schema.periods, next_schema.periods)) {
            return error.InvalidSchemaUpdateRequest;
        }
        try validateConstraintCatalogTransition(current_schema, next_schema);
    }

    fn validateRelationalColumnCatalogTransition(current_columns: []const schema_mod.RelationalColumn, next_columns: []const schema_mod.RelationalColumn) !void {
        if (current_columns.len > next_columns.len) return error.InvalidSchemaUpdateRequest;
        for (current_columns, 0..) |_, index| {
            if (!schema_mod.relationalColumnCatalogsEqual(current_columns[index .. index + 1], next_columns[index .. index + 1])) {
                return error.InvalidSchemaUpdateRequest;
            }
        }
        for (next_columns[current_columns.len..]) |column| {
            if (column.generated) |generated| {
                try validateAppendedGeneratedColumnTransition(current_columns, next_columns, generated);
                continue;
            }
            if (column.default_value) |default_value| {
                if (default_value.kind != .literal) return error.InvalidSchemaUpdateRequest;
                continue;
            }
            if (!column.nullable) return error.InvalidSchemaUpdateRequest;
        }
    }

    fn validateAppendedGeneratedColumnTransition(
        current_columns: []const schema_mod.RelationalColumn,
        next_columns: []const schema_mod.RelationalColumn,
        generated: schema_mod.RelationalGeneratedValue,
    ) !void {
        switch (generated.op) {
            .lower, .upper, .md5 => {
                const field = generated.field orelse return error.InvalidSchemaUpdateRequest;
                try validateGeneratedColumnBackfillSource(current_columns, next_columns, field);
            },
            .concat, .concat_ws => {
                if (generated.fields.len == 0) return error.InvalidSchemaUpdateRequest;
                for (generated.fields) |field| {
                    try validateGeneratedColumnBackfillSource(current_columns, next_columns, field);
                }
            },
        }
    }

    fn validateGeneratedColumnBackfillSource(
        current_columns: []const schema_mod.RelationalColumn,
        next_columns: []const schema_mod.RelationalColumn,
        field: []const u8,
    ) !void {
        const normalized = if (std.mem.startsWith(u8, field, "/")) field[1..] else field;
        for (current_columns) |column| {
            if (std.mem.eql(u8, field, column.name) or
                std.mem.eql(u8, field, column.path) or
                std.mem.eql(u8, normalized, column.name) or
                std.mem.eql(u8, normalized, column.path))
            {
                return;
            }
        }
        for (next_columns[current_columns.len..]) |column| {
            if (!(std.mem.eql(u8, field, column.name) or
                std.mem.eql(u8, field, column.path) or
                std.mem.eql(u8, normalized, column.name) or
                std.mem.eql(u8, normalized, column.path)))
            {
                continue;
            }
            if (column.generated != null) return error.InvalidSchemaUpdateRequest;
            const default_value = column.default_value orelse return error.InvalidSchemaUpdateRequest;
            if (default_value.kind != .literal) return error.InvalidSchemaUpdateRequest;
            if (jsonLiteralIsNull(default_value.value_json)) return error.InvalidSchemaUpdateRequest;
            return;
        }
        return error.InvalidSchemaUpdateRequest;
    }

    fn validateConstraintCatalogTransition(current_schema: schema_mod.TableSchema, next_schema: schema_mod.TableSchema) !void {
        for (current_schema.unique_constraints) |constraint| {
            if (findUniqueConstraintByName(next_schema.unique_constraints, constraint.name)) |next_constraint| {
                if (!uniqueConstraintsEqual(constraint, next_constraint)) return error.InvalidSchemaUpdateRequest;
            }
        }
        for (next_schema.unique_constraints) |constraint| {
            if (findUniqueConstraintByName(current_schema.unique_constraints, constraint.name)) |current_constraint| {
                if (!uniqueConstraintsEqual(current_constraint, constraint)) return error.InvalidSchemaUpdateRequest;
            }
        }
        for (current_schema.foreign_keys) |foreign_key| {
            if (findForeignKeyByName(next_schema.foreign_keys, foreign_key.name)) |next_foreign_key| {
                if (!foreignKeysSameDefinition(foreign_key, next_foreign_key)) return error.InvalidSchemaUpdateRequest;
            }
        }
        for (next_schema.foreign_keys) |foreign_key| {
            if (findForeignKeyByName(current_schema.foreign_keys, foreign_key.name)) |current_foreign_key| {
                if (!foreignKeysSameDefinition(current_foreign_key, foreign_key)) return error.InvalidSchemaUpdateRequest;
            }
        }
        for (current_schema.checks) |check| {
            if (findRelationalCheckByName(next_schema.checks, check.name)) |next_check| {
                if (!relationalChecksSameDefinition(check, next_check)) return error.InvalidSchemaUpdateRequest;
            }
        }
        for (next_schema.checks) |check| {
            if (findRelationalCheckByName(current_schema.checks, check.name)) |current_check| {
                if (!relationalChecksSameDefinition(current_check, check)) return error.InvalidSchemaUpdateRequest;
            }
        }
    }

    fn migrateRelationalRowsForSchemaTransitionLocked(self: *DB, alloc: Allocator, next_schema: schema_mod.TableSchema) !void {
        if (self.core.schema) |current_schema| {
            return try self.migrateRelationalRowsFromCurrentLocked(alloc, current_schema, next_schema);
        }

        const durable_schema = try schema_mod.loadSchema(self.core.store, alloc);
        defer if (durable_schema) |loaded| schema_mod.freeSchema(alloc, loaded);
        if (durable_schema) |current_schema| {
            return try self.migrateRelationalRowsFromCurrentLocked(alloc, current_schema, next_schema);
        }
    }

    fn migrateRelationalRowsFromCurrentLocked(
        self: *DB,
        alloc: Allocator,
        current_schema: schema_mod.TableSchema,
        next_schema: schema_mod.TableSchema,
    ) !void {
        if (current_schema.storage_mode != .relational or next_schema.storage_mode != .relational) return;
        if (next_schema.relational_columns.len <= current_schema.relational_columns.len) return;

        const appended_columns = next_schema.relational_columns[current_schema.relational_columns.len..];
        var sets = std.ArrayListUnmanaged(relational_store_mod.RowRewriteSet).empty;
        defer sets.deinit(alloc);
        var owned_rows = std.ArrayListUnmanaged([]u8).empty;
        defer {
            for (owned_rows.items) |row| alloc.free(row);
            owned_rows.deinit(alloc);
        }
        var decoded_rows = std.ArrayListUnmanaged(relational_row_codec.Row).empty;
        defer {
            for (decoded_rows.items) |*row| row.deinit(alloc);
            decoded_rows.deinit(alloc);
        }

        var generated_columns = std.ArrayListUnmanaged(schema_mod.RelationalColumn).empty;
        defer generated_columns.deinit(alloc);

        for (appended_columns) |column| {
            if (column.generated != null) {
                try generated_columns.append(alloc, column);
                continue;
            }
            const default_value = column.default_value orelse continue;
            if (default_value.kind != .literal) return error.InvalidSchemaUpdateRequest;
            if (column.nullable and jsonLiteralIsNull(default_value.value_json)) continue;
            const row_value = try relationalDefaultColumnRowValueAlloc(alloc, column, default_value.value_json);
            errdefer alloc.free(row_value);
            try owned_rows.append(alloc, row_value);
            var decoded = try relational_row_codec.deserialize(alloc, row_value);
            errdefer decoded.deinit(alloc);
            if (decoded.cells.len != 1) return error.InvalidSchemaUpdateRequest;
            try decoded_rows.append(alloc, decoded);
            const stable_decoded = &decoded_rows.items[decoded_rows.items.len - 1];
            try sets.append(alloc, .{
                .cell = stable_decoded.cells[0],
                .only_if_missing = true,
            });
        }

        const column_index_policy = relational_store_mod.ColumnIndexPolicy.fromColumns(next_schema.relational_columns);
        if (sets.items.len != 0) {
            _ = try relational_store_mod.rewriteRowsInRangeWithColumnIndexPolicy(
                alloc,
                self.core.store,
                .{ .sets = sets.items },
                self.getRange().start,
                self.getRange().end,
                column_index_policy,
            );
        }
        if (generated_columns.items.len != 0) {
            try self.backfillRelationalGeneratedColumnsLocked(alloc, generated_columns.items, column_index_policy);
        }
    }

    fn jsonLiteralIsNull(value_json: []const u8) bool {
        return std.mem.eql(u8, std.mem.trim(u8, value_json, " \t\r\n"), "null");
    }

    fn relationalDefaultColumnRowValueAlloc(
        alloc: Allocator,
        column: schema_mod.RelationalColumn,
        value_json: []const u8,
    ) ![]u8 {
        var out: std.Io.Writer.Allocating = .init(alloc);
        errdefer out.deinit();
        const writer = &out.writer;
        try writer.writeByte('{');
        try writer.print("{f}:", .{std.json.fmt(column.path, .{})});
        try writer.writeAll(value_json);
        try writer.writeByte('}');
        const json = try out.toOwnedSlice();
        defer alloc.free(json);
        const columns = [_]schema_mod.RelationalColumn{column};
        return try mapper.buildRelationalRowValueAlloc(alloc, json, columns[0..]);
    }

    fn backfillRelationalGeneratedColumnsLocked(
        self: *DB,
        alloc: Allocator,
        generated_columns: []const schema_mod.RelationalColumn,
        column_index_policy: relational_store_mod.ColumnIndexPolicy,
    ) !void {
        const rows = try relational_store_mod.scanRowsAlloc(alloc, self.core.store, self.getRange().start, self.getRange().end);
        defer relational_store_mod.freeRows(alloc, rows);

        var writes = std.ArrayListUnmanaged(docstore_mod.KVPair).empty;
        defer writes.deinit(alloc);
        var deletes = std.ArrayListUnmanaged([]const u8).empty;
        defer deletes.deinit(alloc);
        var owned_keys = std.ArrayListUnmanaged([]u8).empty;
        defer {
            for (owned_keys.items) |key| alloc.free(key);
            owned_keys.deinit(alloc);
        }
        var owned_values = std.ArrayListUnmanaged([]u8).empty;
        defer {
            for (owned_values.items) |value| alloc.free(value);
            owned_values.deinit(alloc);
        }

        for (rows) |row| {
            const row_json = mapper.materializeRelationalRowValueAlloc(alloc, row.row_value) catch return error.InvalidRowsRequest;
            defer alloc.free(row_json);
            var parsed = std.json.parseFromSlice(std.json.Value, alloc, row_json, .{}) catch return error.InvalidRowsRequest;
            defer parsed.deinit();
            if (parsed.value != .object) return error.InvalidRowsRequest;

            var row_sets = std.ArrayListUnmanaged(relational_store_mod.RowRewriteSet).empty;
            defer row_sets.deinit(alloc);
            var row_owned_values = std.ArrayListUnmanaged([]u8).empty;
            defer {
                for (row_owned_values.items) |value| alloc.free(value);
                row_owned_values.deinit(alloc);
            }
            var row_decoded = std.ArrayListUnmanaged(relational_row_codec.Row).empty;
            defer {
                for (row_decoded.items) |*decoded| decoded.deinit(alloc);
                row_decoded.deinit(alloc);
            }

            for (generated_columns) |column| {
                const generated = column.generated orelse continue;
                const value_json = relationalRowsGeneratedColumnValueJsonAlloc(alloc, parsed.value, generated) catch return error.InvalidRowsRequest;
                defer alloc.free(value_json);
                const generated_row = try relationalDefaultColumnRowValueAlloc(alloc, column, value_json);
                errdefer alloc.free(generated_row);
                try row_owned_values.append(alloc, generated_row);
                var decoded = try relational_row_codec.deserialize(alloc, generated_row);
                errdefer decoded.deinit(alloc);
                if (decoded.cells.len != 1) return error.InvalidSchemaUpdateRequest;
                try row_decoded.append(alloc, decoded);
                const stable_decoded = &row_decoded.items[row_decoded.items.len - 1];
                try row_sets.append(alloc, .{
                    .cell = stable_decoded.cells[0],
                    .only_if_missing = true,
                });
            }

            const rewritten = try relational_store_mod.rewriteRowValueWithPlanAlloc(alloc, row.row_value, .{ .sets = row_sets.items });
            if (rewritten) |new_row| {
                var new_row_owned = true;
                errdefer if (new_row_owned) alloc.free(new_row);
                try relational_store_mod.appendUpsertWithColumnIndexPolicy(alloc, self.core.store, &writes, &deletes, &owned_keys, &owned_values, row.doc_key, new_row, column_index_policy);
                try owned_values.append(alloc, new_row);
                new_row_owned = false;
            }
        }

        if (writes.items.len > 0 or deletes.items.len > 0) try self.core.store.putBatch(writes.items, deletes.items);
    }

    fn migrateRelationalConstraintsForSchemaTransitionLocked(self: *DB, alloc: Allocator, next_schema: schema_mod.TableSchema) !void {
        if (self.core.schema) |current_schema| {
            return try self.migrateRelationalConstraintsFromCurrentLocked(alloc, current_schema, next_schema);
        }

        const durable_schema = try schema_mod.loadSchema(self.core.store, alloc);
        defer if (durable_schema) |loaded| schema_mod.freeSchema(alloc, loaded);
        if (durable_schema) |current_schema| {
            return try self.migrateRelationalConstraintsFromCurrentLocked(alloc, current_schema, next_schema);
        }
    }

    fn migrateRelationalConstraintsFromCurrentLocked(
        self: *DB,
        alloc: Allocator,
        current_schema: schema_mod.TableSchema,
        next_schema: schema_mod.TableSchema,
    ) !void {
        if (current_schema.storage_mode != .relational or next_schema.storage_mode != .relational) return;

        var unique_to_build = std.ArrayListUnmanaged(schema_mod.UniqueConstraint).empty;
        defer unique_to_build.deinit(alloc);
        var unique_to_delete = std.ArrayListUnmanaged(schema_mod.UniqueConstraint).empty;
        defer unique_to_delete.deinit(alloc);
        var foreign_keys_to_build = std.ArrayListUnmanaged(schema_mod.ForeignKey).empty;
        defer foreign_keys_to_build.deinit(alloc);
        var foreign_keys_to_delete = std.ArrayListUnmanaged(schema_mod.ForeignKey).empty;
        defer foreign_keys_to_delete.deinit(alloc);
        var checks_to_validate = std.ArrayListUnmanaged(schema_mod.RelationalCheck).empty;
        defer checks_to_validate.deinit(alloc);

        for (next_schema.unique_constraints) |constraint| {
            if (findUniqueConstraintByName(current_schema.unique_constraints, constraint.name) == null) {
                try unique_to_build.append(alloc, constraint);
            }
        }
        for (current_schema.unique_constraints) |constraint| {
            if (findUniqueConstraintByName(next_schema.unique_constraints, constraint.name) == null) {
                try unique_to_delete.append(alloc, constraint);
            }
        }
        for (next_schema.foreign_keys) |foreign_key| {
            if (findForeignKeyByName(current_schema.foreign_keys, foreign_key.name)) |current_foreign_key| {
                if (current_foreign_key.validation_state != .enforced and foreign_key.validation_state == .enforced) {
                    try foreign_keys_to_build.append(alloc, foreign_key);
                }
            } else if (foreign_key.validation_state == .enforced) {
                try foreign_keys_to_build.append(alloc, foreign_key);
            }
        }
        for (current_schema.foreign_keys) |foreign_key| {
            if (findForeignKeyByName(next_schema.foreign_keys, foreign_key.name) == null) {
                try foreign_keys_to_delete.append(alloc, foreign_key);
            }
        }
        for (next_schema.checks) |check| {
            if (findRelationalCheckByName(current_schema.checks, check.name)) |current_check| {
                if (current_check.validation_state != .enforced and check.validation_state == .enforced) {
                    try checks_to_validate.append(alloc, check);
                }
            } else if (check.validation_state == .enforced) {
                try checks_to_validate.append(alloc, check);
            }
        }

        if (unique_to_build.items.len > 0) {
            try relational_store_mod.rebuildUniqueConstraintRowsInRange(
                alloc,
                self.core.store,
                next_schema.relational_columns,
                next_schema.periods,
                unique_to_build.items,
                self.getRange().start,
                self.getRange().end,
            );
        }
        if (foreign_keys_to_build.items.len > 0) {
            const validate_report = try relational_store_mod.reconcileForeignKeyRefsInRangeWithPrimaryKey(
                alloc,
                self.core.store,
                next_schema.default_type,
                next_schema.relational_columns,
                next_schema.periods,
                foreign_keys_to_build.items,
                next_schema.primary_key,
                next_schema.unique_constraints,
                self.getRange().start,
                self.getRange().end,
                .validate,
            );
            try self.recordForeignKeyIntegrityProgressLocked(alloc, .validate, null, self.getRange().start, self.getRange().end, validate_report);
            if (validate_report.missing_parent_rows != 0) return error.ForeignKeyViolation;

            const repair_report = try relational_store_mod.reconcileForeignKeyRefsInRangeWithPrimaryKey(
                alloc,
                self.core.store,
                next_schema.default_type,
                next_schema.relational_columns,
                next_schema.periods,
                foreign_keys_to_build.items,
                next_schema.primary_key,
                next_schema.unique_constraints,
                self.getRange().start,
                self.getRange().end,
                .repair,
            );
            try self.recordForeignKeyIntegrityProgressLocked(alloc, .repair, null, self.getRange().start, self.getRange().end, repair_report);
            if (repair_report.missing_parent_rows != 0) return error.ForeignKeyViolation;
        }
        if (checks_to_validate.items.len > 0) {
            try self.validateRelationalChecksInRangeLocked(
                alloc,
                checks_to_validate.items,
                self.getRange().start,
                self.getRange().end,
            );
        }
        if (foreign_keys_to_delete.items.len > 0) {
            try relational_store_mod.deleteForeignKeyRefRows(alloc, self.core.store, foreign_keys_to_delete.items);
        }
        if (unique_to_delete.items.len > 0) {
            try relational_store_mod.deleteUniqueConstraintRows(alloc, self.core.store, unique_to_delete.items);
        }
    }

    fn findUniqueConstraintByName(unique_constraints: []const schema_mod.UniqueConstraint, name: []const u8) ?schema_mod.UniqueConstraint {
        for (unique_constraints) |constraint| {
            if (std.mem.eql(u8, constraint.name, name)) return constraint;
        }
        return null;
    }

    fn uniqueOwnerConstraintsAlloc(alloc: Allocator, runtime_schema: schema_mod.TableSchema) ![]schema_mod.UniqueConstraint {
        const extra: usize = if (runtime_schema.primary_key != null) 1 else 0;
        const constraints = try alloc.alloc(schema_mod.UniqueConstraint, runtime_schema.unique_constraints.len + extra);
        var index: usize = 0;
        if (runtime_schema.primary_key) |primary_key| {
            constraints[index] = relational_store_mod.primaryKeyAsUniqueConstraint(primary_key);
            index += 1;
        }
        for (runtime_schema.unique_constraints) |constraint| {
            constraints[index] = constraint;
            index += 1;
        }
        return constraints;
    }

    fn findForeignKeyByName(foreign_keys: []const schema_mod.ForeignKey, name: []const u8) ?schema_mod.ForeignKey {
        for (foreign_keys) |foreign_key| {
            if (std.mem.eql(u8, foreign_key.name, name)) return foreign_key;
        }
        return null;
    }

    fn findRelationalCheckByName(checks: []const schema_mod.RelationalCheck, name: []const u8) ?schema_mod.RelationalCheck {
        for (checks) |check| {
            if (std.mem.eql(u8, check.name, name)) return check;
        }
        return null;
    }

    fn relationalChecksSameDefinition(a: schema_mod.RelationalCheck, b: schema_mod.RelationalCheck) bool {
        return schema_mod.relationalChecksEqual(a, b);
    }

    fn uniqueConstraintsEqual(a: schema_mod.UniqueConstraint, b: schema_mod.UniqueConstraint) bool {
        return std.mem.eql(u8, a.name, b.name) and
            stringSlicesEqual(a.columns, b.columns) and
            uniqueExpressionSlicesEqual(a.expressions, b.expressions) and
            optionalStringsEqual(a.without_overlaps_period, b.without_overlaps_period) and
            uniquePredicateSlicesEqual(a.where, b.where) and
            relationalRowsExpressionConditionSlicesEqual(a.where_expressions, b.where_expressions);
    }

    fn uniqueConstraintCanBackForeignKey(constraint: schema_mod.UniqueConstraint) bool {
        return constraint.where.len == 0 and
            constraint.where_expressions.len == 0 and
            constraint.expressions.len == 0 and
            constraint.without_overlaps_period == null;
    }

    fn uniqueExpressionSlicesEqual(a: []const schema_mod.UniqueExpression, b: []const schema_mod.UniqueExpression) bool {
        if (a.len != b.len) return false;
        for (a, b) |left, right| {
            if (left.op != right.op) return false;
            if (!std.mem.eql(u8, left.field, right.field)) return false;
        }
        return true;
    }

    fn validateRelationalChecksInRangeLocked(
        self: *DB,
        alloc: Allocator,
        checks: []const schema_mod.RelationalCheck,
        lower_doc_key: []const u8,
        upper_doc_key: []const u8,
    ) !void {
        if (checks.len == 0) return;
        const rows = try relational_store_mod.scanRowsAlloc(alloc, self.core.store, lower_doc_key, upper_doc_key);
        defer relational_store_mod.freeRows(alloc, rows);

        for (rows) |row| {
            const row_json = mapper.materializeRelationalRowValueAlloc(alloc, row.row_value) catch return error.InvalidRowsRequest;
            defer alloc.free(row_json);
            var parsed = std.json.parseFromSlice(std.json.Value, alloc, row_json, .{}) catch return error.InvalidRowsRequest;
            defer parsed.deinit();
            if (parsed.value != .object) return error.InvalidRowsRequest;
            for (checks) |check| {
                const passes = relationalCheckPassesExistingRow(alloc, parsed.value, check) catch |err| switch (err) {
                    error.InvalidQueryRequest => return error.InvalidRowsRequest,
                    else => return err,
                };
                if (!passes) {
                    return error.InvalidRowsRequest;
                }
            }
        }
    }

    fn relationalCheckPassesExistingRow(
        alloc: Allocator,
        row: std.json.Value,
        check: schema_mod.RelationalCheck,
    ) !bool {
        if (check.expression) |condition| return try relationalRowsExpressionConditionMatches(alloc, row, condition);
        return try relationalRowsQueryPredicatePasses(alloc, row, check);
    }

    fn uniquePredicateSlicesEqual(a: []const schema_mod.UniquePredicate, b: []const schema_mod.UniquePredicate) bool {
        if (a.len != b.len) return false;
        for (a, b) |left, right| {
            if (left.op != right.op) return false;
            if (!std.mem.eql(u8, left.field, right.field)) return false;
            if (!optionalStringsEqual(left.value_json, right.value_json)) return false;
        }
        return true;
    }

    fn relationalRowsExpressionConditionSlicesEqual(
        a: []const types.RelationalRowsExpressionCondition,
        b: []const types.RelationalRowsExpressionCondition,
    ) bool {
        if (a.len != b.len) return false;
        for (a, b) |left, right| {
            if (!relationalRowsExpressionConditionEqual(left, right)) return false;
        }
        return true;
    }

    fn optionalStringsEqual(a: ?[]const u8, b: ?[]const u8) bool {
        if (a == null and b == null) return true;
        if (a == null or b == null) return false;
        return std.mem.eql(u8, a.?, b.?);
    }

    fn foreignKeysSameDefinition(a: schema_mod.ForeignKey, b: schema_mod.ForeignKey) bool {
        return std.mem.eql(u8, a.name, b.name) and
            stringSlicesEqual(a.child_columns, b.child_columns) and
            optionalStringsEqual(a.child_period, b.child_period) and
            std.mem.eql(u8, a.parent_table, b.parent_table) and
            stringSlicesEqual(a.parent_columns, b.parent_columns) and
            optionalStringsEqual(a.parent_period, b.parent_period) and
            a.on_delete == b.on_delete and
            a.on_update == b.on_update and
            a.timing == b.timing and
            a.deferrable == b.deferrable and
            a.match == b.match;
    }

    fn stringSlicesEqual(a: []const []const u8, b: []const []const u8) bool {
        if (a.len != b.len) return false;
        for (a, b) |left, right| {
            if (!std.mem.eql(u8, left, right)) return false;
        }
        return true;
    }

    const ExistingPhysicalStorageMode = enum {
        empty,
        document,
        relational,
        mixed,
    };

    fn validateFirstTableSchemaApplyAgainstExistingRows(self: *DB, alloc: Allocator, next_schema: schema_mod.TableSchema) !void {
        const existing_mode = try self.detectExistingPhysicalStorageMode(alloc);
        switch (existing_mode) {
            .empty => return,
            .document => if (next_schema.storage_mode != .document) return error.InvalidSchemaUpdateRequest,
            .relational => if (next_schema.storage_mode != .relational) return error.InvalidSchemaUpdateRequest,
            .mixed => return error.InvalidSchemaUpdateRequest,
        }
    }

    fn detectExistingPhysicalStorageMode(self: *DB, alloc: Allocator) !ExistingPhysicalStorageMode {
        const lower = [_]u8{internal_keys.user_namespace};
        const upper = [_]u8{internal_keys.user_namespace + 1};
        const rows = try self.core.store.scanRange(alloc, lower[0..], upper[0..]);
        defer docstore_mod.DocStore.freeResults(alloc, rows);

        var saw_document = false;
        var saw_relational = false;
        for (rows) |entry| {
            if (internal_keys.isPrimaryDocumentKey(entry.key)) {
                saw_document = true;
            } else if (internal_keys.isRelationalRowKey(entry.key)) {
                saw_relational = true;
            }
            if (saw_document and saw_relational) return .mixed;
        }

        if (saw_document) return .document;
        if (saw_relational) return .relational;
        return .empty;
    }

    /// Returns the relational column catalog when the table is in relational
    /// storage mode (so document writes store a dedicated relational base row),
    /// or null for document-mode tables (which keep the JSON blob).
    fn relationalColumnsForStore(self: *DB) ?[]const schema_mod.RelationalColumn {
        const schema = self.core.schema orelse return null;
        if (schema.storage_mode != .relational) return null;
        return schema.relational_columns;
    }

    fn relationalColumnIndexPolicyForStore(self: *DB) relational_store_mod.ColumnIndexPolicy {
        const columns = self.relationalColumnsForStore() orelse return relational_store_mod.ColumnIndexPolicy.all();
        return relational_store_mod.ColumnIndexPolicy.fromColumns(columns);
    }

    pub fn rebuildRelationalSecondaryIndexInRange(
        self: *DB,
        index_name: []const u8,
        index_generation: u64,
        lower_doc_key: []const u8,
        upper_doc_key: []const u8,
    ) !relational_store_mod.SecondaryIndexRebuildReport {
        lockApply(self);
        defer self.core.unlockApply();
        return try relational_store_mod.rebuildColumnIndexFromRowsInSpanWithColumnIndexPolicy(
            self.alloc,
            self.core.store,
            index_name,
            index_generation,
            lower_doc_key,
            upper_doc_key,
            self.relationalColumnIndexPolicyForStore(),
        );
    }

