    fn reconcileForeignKeyRefOwnerRangeLocked(
        self: *DB,
        constraint_name: []const u8,
        parent_table: []const u8,
        start_parent_key: []const u8,
        end_parent_key: []const u8,
        mode: relational_store_mod.ForeignKeyIntegrityMode,
