    fn validateUniqueConstraintMutations(
        self: *DB,
        unique_writes: []const types.UniqueConstraintMutation,
        unique_deletes: []const types.UniqueConstraintMutation,
    ) !void {
        if (unique_writes.len == 0 and unique_deletes.len == 0) return;
        const runtime_schema = self.core.schema orelse return error.UniqueConstraintViolation;
        if (runtime_schema.storage_mode != .relational) return error.UniqueConstraintViolation;
        const owner_constraints = try uniqueOwnerConstraintsAlloc(self.alloc, runtime_schema);
        defer self.alloc.free(owner_constraints);
        for (unique_writes) |mutation| {
            const constraint = try self.validateUniqueConstraintMutation(owner_constraints, mutation);
            if (mutationIsTemporal(mutation)) {
                if (findTemporalUniqueConstraintMutationConflict(unique_writes, mutation)) |existing| {
                    if (!std.mem.eql(u8, existing.owner_key, mutation.owner_key)) {
                        return error.UniqueConstraintViolation;
                    }
                }
                const committed_owner = relational_store_mod.lookupTemporalUniqueOverlapOwnerAlloc(
                    self.alloc,
                    self.core.store,
                    mutation.constraint_name,
                    mutation.encoded_value,
                    mutation.temporal_start.?,
                    mutation.temporal_end.?,
                ) catch |err| switch (err) {
                    error.NotFound => continue,
                    else => return err,
                };
                if (committed_owner) |owner| {
                    defer self.alloc.free(owner);
                    if (std.mem.eql(u8, owner, mutation.owner_key)) continue;
                    if (findTemporalUniqueConstraintMutationConflict(unique_deletes, mutation)) |delete_mutation| {
                        if (std.mem.eql(u8, delete_mutation.owner_key, owner)) continue;
                    }
                    return error.UniqueConstraintViolation;
                }
                _ = constraint;
                continue;
            }
            const key = try internal_keys.relationalUniqueKeyAlloc(self.alloc, mutation.constraint_name, mutation.encoded_value);
            defer self.alloc.free(key);
            if (findUniqueConstraintMutation(unique_writes, mutation.constraint_name, mutation.encoded_value)) |existing| {
                if (!std.mem.eql(u8, existing.owner_key, mutation.owner_key)) {
                    return error.UniqueConstraintViolation;
                }
            }
            const committed_owner = self.core.store.get(self.alloc, key) catch |err| switch (err) {
                error.NotFound => continue,
                else => return err,
            };
            defer self.alloc.free(committed_owner);
            if (std.mem.eql(u8, committed_owner, mutation.owner_key)) continue;
            if (findUniqueConstraintMutation(unique_deletes, mutation.constraint_name, mutation.encoded_value)) |delete_mutation| {
                if (std.mem.eql(u8, delete_mutation.owner_key, committed_owner)) continue;
            }
            return error.UniqueConstraintViolation;
        }
        for (unique_deletes) |mutation| {
            _ = try self.validateUniqueConstraintMutation(owner_constraints, mutation);
            if (mutationIsTemporal(mutation)) {
                const committed_owner = relational_store_mod.lookupTemporalUniqueOverlapOwnerAlloc(
                    self.alloc,
                    self.core.store,
                    mutation.constraint_name,
                    mutation.encoded_value,
                    mutation.temporal_start.?,
                    mutation.temporal_end.?,
                ) catch |err| switch (err) {
                    error.NotFound => continue,
                    else => return err,
                };
                if (committed_owner) |owner| {
                    defer self.alloc.free(owner);
                    if (std.mem.eql(u8, owner, mutation.owner_key)) continue;
                    if (findTemporalUniqueConstraintMutationConflict(unique_writes, mutation)) |write_mutation| {
                        if (std.mem.eql(u8, write_mutation.owner_key, owner)) continue;
                    }
                    return error.UniqueConstraintViolation;
                }
                continue;
            }
            const key = try internal_keys.relationalUniqueKeyAlloc(self.alloc, mutation.constraint_name, mutation.encoded_value);
            defer self.alloc.free(key);
            const committed_owner = self.core.store.get(self.alloc, key) catch |err| switch (err) {
                error.NotFound => continue,
                else => return err,
            };
            defer self.alloc.free(committed_owner);
            if (std.mem.eql(u8, committed_owner, mutation.owner_key)) continue;
            if (findUniqueConstraintMutation(unique_writes, mutation.constraint_name, mutation.encoded_value)) |write_mutation| {
                if (std.mem.eql(u8, write_mutation.owner_key, committed_owner)) continue;
            }
            return error.UniqueConstraintViolation;
        }
    }

    fn validateUniqueConstraintMutation(
        self: *DB,
        constraints: []const schema_mod.UniqueConstraint,
        mutation: types.UniqueConstraintMutation,
    ) !schema_mod.UniqueConstraint {
        _ = self;
        if (mutation.constraint_name.len == 0 or mutation.encoded_value.len == 0 or mutation.owner_key.len == 0) {
            return error.UniqueConstraintViolation;
        }
        if (!isForeignKeyExternalDocKey(mutation.owner_key)) {
            return error.UniqueConstraintViolation;
        }
        const constraint = findUniqueConstraintByName(constraints, mutation.constraint_name) orelse return error.UniqueConstraintViolation;
        const has_start = mutation.temporal_start != null;
        const has_end = mutation.temporal_end != null;
        if (has_start != has_end) return error.UniqueConstraintViolation;
        if (has_start) {
            if (constraint.without_overlaps_period == null) return error.UniqueConstraintViolation;
            if (!(relational_store_mod.temporalPeriodSpanBytesValid(mutation.temporal_start.?, mutation.temporal_end.?) catch return error.UniqueConstraintViolation)) {
                return error.UniqueConstraintViolation;
            }
        } else if (constraint.without_overlaps_period != null) {
            return error.UniqueConstraintViolation;
        }
        return constraint;
    }

    fn findUniqueConstraintMutation(
        mutations: []const types.UniqueConstraintMutation,
        constraint_name: []const u8,
        encoded_value: []const u8,
    ) ?types.UniqueConstraintMutation {
        for (mutations) |mutation| {
            if (std.mem.eql(u8, mutation.constraint_name, constraint_name) and std.mem.eql(u8, mutation.encoded_value, encoded_value)) return mutation;
        }
        return null;
    }

    fn mutationIsTemporal(mutation: types.UniqueConstraintMutation) bool {
        return mutation.temporal_start != null and mutation.temporal_end != null;
    }

    fn findTemporalUniqueConstraintMutationConflict(
        mutations: []const types.UniqueConstraintMutation,
        needle: types.UniqueConstraintMutation,
    ) ?types.UniqueConstraintMutation {
        if (!mutationIsTemporal(needle)) return null;
        for (mutations) |mutation| {
            if (!mutationIsTemporal(mutation)) continue;
            if (!std.mem.eql(u8, mutation.constraint_name, needle.constraint_name)) continue;
            if (!std.mem.eql(u8, mutation.encoded_value, needle.encoded_value)) continue;
            const overlaps = relational_store_mod.temporalPeriodSpanBytesOverlap(
                mutation.temporal_start.?,
                mutation.temporal_end.?,
                needle.temporal_start.?,
                needle.temporal_end.?,
            ) catch return mutation;
            if (overlaps) return mutation;
        }
        return null;
    }

    fn appendUniqueConstraintMutationIntents(
        self: *DB,
        intents: *std.ArrayListUnmanaged(transactions_mod.WriteIntent),
        owned_keys: *std.ArrayListUnmanaged([]u8),
        owned_values: *std.ArrayListUnmanaged([]u8),
        unique_writes: []const types.UniqueConstraintMutation,
        unique_deletes: []const types.UniqueConstraintMutation,
    ) !void {
        for (unique_deletes) |mutation| {
            const key = if (mutationIsTemporal(mutation))
                try internal_keys.relationalTemporalUniqueKeyAlloc(self.alloc, mutation.constraint_name, mutation.encoded_value, mutation.temporal_start.?, mutation.temporal_end.?, mutation.owner_key)
            else
                try internal_keys.relationalUniqueKeyAlloc(self.alloc, mutation.constraint_name, mutation.encoded_value);
            errdefer self.alloc.free(key);
            try owned_keys.append(self.alloc, key);
            try intents.append(self.alloc, .{ .key = key, .value = null });
        }
        for (unique_writes) |mutation| {
            const key = if (mutationIsTemporal(mutation))
                try internal_keys.relationalTemporalUniqueKeyAlloc(self.alloc, mutation.constraint_name, mutation.encoded_value, mutation.temporal_start.?, mutation.temporal_end.?, mutation.owner_key)
            else
                try internal_keys.relationalUniqueKeyAlloc(self.alloc, mutation.constraint_name, mutation.encoded_value);
            errdefer self.alloc.free(key);
            const owner = try self.alloc.dupe(u8, mutation.owner_key);
            errdefer self.alloc.free(owner);
            try owned_keys.append(self.alloc, key);
            try owned_values.append(self.alloc, owner);
            try intents.append(self.alloc, .{ .key = key, .value = owner });
        }
    }

    fn appendForeignKeyRefMutationIntents(
        self: *DB,
        intents: *std.ArrayListUnmanaged(transactions_mod.WriteIntent),
        owned_keys: *std.ArrayListUnmanaged([]u8),
        ref_writes: []const types.ForeignKeyRefMutation,
        ref_deletes: []const types.ForeignKeyRefMutation,
    ) !void {
        for (ref_writes) |mutation| {
            const key = try internal_keys.relationalForeignKeyRefKeyAlloc(self.alloc, mutation.constraint_name, mutation.parent_table, mutation.parent_key, mutation.child_table, mutation.child_key);
            errdefer self.alloc.free(key);
            try owned_keys.append(self.alloc, key);
            try intents.append(self.alloc, .{ .key = key, .value = "" });
        }
        for (ref_deletes) |mutation| {
            const key = try internal_keys.relationalForeignKeyRefKeyAlloc(self.alloc, mutation.constraint_name, mutation.parent_table, mutation.parent_key, mutation.child_table, mutation.child_key);
            errdefer self.alloc.free(key);
            try owned_keys.append(self.alloc, key);
            try intents.append(self.alloc, .{ .key = key, .value = null });
        }
    }

    fn applyForeignKeyParentDeleteActions(
        self: *DB,
        intents: *std.ArrayListUnmanaged(transactions_mod.WriteIntent),
        owned_keys: *std.ArrayListUnmanaged([]u8),
        owned_values: *std.ArrayListUnmanaged([]u8),
        checks: []const types.ForeignKeyParentDeleteCheck,
    ) !void {
        if (checks.len == 0) return;
        const runtime_schema = self.core.schema orelse return error.ForeignKeyViolation;
        if (runtime_schema.storage_mode != .relational) return error.ForeignKeyViolation;

        var action_writes = std.ArrayListUnmanaged(docstore_mod.KVPair).empty;
        defer action_writes.deinit(self.alloc);
        var action_deletes = std.ArrayListUnmanaged([]const u8).empty;
        defer action_deletes.deinit(self.alloc);
        var participant = relational_store_mod.WriteParticipant.initWithColumnIndexPolicy(
            self.alloc,
            self.core.store,
            &action_writes,
            &action_deletes,
            owned_keys,
            owned_values,
            self.relationalColumnIndexPolicyForStore(),
        );
        participant.configureForeignKeys(runtime_schema.default_type, runtime_schema.foreign_keys, &.{});
        participant.configurePrimaryKey(runtime_schema.primary_key);
        participant.configureUniqueConstraints(runtime_schema.unique_constraints);
        participant.configurePeriods(runtime_schema.periods, runtime_schema.relational_columns);
        var prepared = false;
        var closed = false;
        defer if (prepared and !closed) participant.abort(null);

        for (checks) |check| {
            if (check.operation != .delete) continue;
            const foreign_key = findRuntimeForeignKeyByName(runtime_schema.foreign_keys, check.constraint_name) orelse return error.ForeignKeyViolation;
            if (foreign_key.on_delete != .set_null) continue;
            if (check.constraint_name.len == 0 or check.parent_table.len == 0 or check.parent_key.len == 0) return error.ForeignKeyViolation;
            if (!isForeignKeyExternalDocKey(check.parent_key)) return error.ForeignKeyViolation;
            try participant.prepareSetNullForeignKeyParentDelete(check.constraint_name, check.parent_table, check.parent_key);
            prepared = true;
        }
        if (!prepared) return;
        try participant.commit(null, 0);
        closed = true;

        for (action_writes.items) |write| {
            try intents.append(self.alloc, .{ .key = write.key, .value = write.value });
        }
        for (action_deletes.items) |key| {
            try intents.append(self.alloc, .{ .key = key, .value = null });
        }
    }

    fn applyForeignKeySetNullChildActions(
        self: *DB,
        intents: *std.ArrayListUnmanaged(transactions_mod.WriteIntent),
        owned_keys: *std.ArrayListUnmanaged([]u8),
        owned_values: *std.ArrayListUnmanaged([]u8),
        actions: []const types.ForeignKeySetNullChildAction,
    ) !void {
        if (actions.len == 0) return;
        const runtime_schema = self.core.schema orelse return error.ForeignKeyViolation;
        if (runtime_schema.storage_mode != .relational) return error.ForeignKeyViolation;

        var action_writes = std.ArrayListUnmanaged(docstore_mod.KVPair).empty;
        defer action_writes.deinit(self.alloc);
        var action_deletes = std.ArrayListUnmanaged([]const u8).empty;
        defer action_deletes.deinit(self.alloc);
        var participant = relational_store_mod.WriteParticipant.initWithColumnIndexPolicy(
            self.alloc,
            self.core.store,
            &action_writes,
            &action_deletes,
            owned_keys,
            owned_values,
            self.relationalColumnIndexPolicyForStore(),
        );
        participant.configureForeignKeys(runtime_schema.default_type, runtime_schema.foreign_keys, &.{});
        participant.configurePrimaryKey(runtime_schema.primary_key);
        participant.configureUniqueConstraints(runtime_schema.unique_constraints);
        participant.configurePeriods(runtime_schema.periods, runtime_schema.relational_columns);
        var prepared = false;
        var closed = false;
        defer if (prepared and !closed) participant.abort(null);

        for (actions) |action| {
            if (action.constraint_name.len == 0 or action.parent_table.len == 0 or action.parent_key.len == 0 or action.child_key.len == 0) return error.ForeignKeyViolation;
            if (!isForeignKeyExternalDocKey(action.child_key)) return error.ForeignKeyViolation;
            const foreign_key = findRuntimeForeignKeyByName(runtime_schema.foreign_keys, action.constraint_name) orelse return error.ForeignKeyViolation;
            if (foreignKeyReferencesPrimaryKey(foreign_key) and !isForeignKeyExternalDocKey(action.parent_key)) return error.ForeignKeyViolation;
            switch (action.operation) {
                .delete => try participant.prepareSetNullForeignKeyChildAction(action.constraint_name, action.parent_table, action.parent_key, action.child_key),
                .update => try participant.prepareSetNullForeignKeyUpdateChildAction(action.constraint_name, action.parent_table, action.parent_key, action.child_key),
            }
            prepared = true;
        }
        if (!prepared) return;
        try participant.commit(null, 0);
        closed = true;

        for (action_writes.items) |write| {
            try intents.append(self.alloc, .{ .key = write.key, .value = write.value });
        }
        for (action_deletes.items) |key| {
            try intents.append(self.alloc, .{ .key = key, .value = null });
        }
    }

    fn applyForeignKeyCascadeChildActions(
        self: *DB,
        intents: *std.ArrayListUnmanaged(transactions_mod.WriteIntent),
        owned_keys: *std.ArrayListUnmanaged([]u8),
        owned_values: *std.ArrayListUnmanaged([]u8),
        actions: []const types.ForeignKeyCascadeChildAction,
    ) !void {
        if (actions.len == 0) return;
        const runtime_schema = self.core.schema orelse return error.ForeignKeyViolation;
        if (runtime_schema.storage_mode != .relational) return error.ForeignKeyViolation;

        var action_writes = std.ArrayListUnmanaged(docstore_mod.KVPair).empty;
        defer action_writes.deinit(self.alloc);
        var action_deletes = std.ArrayListUnmanaged([]const u8).empty;
        defer action_deletes.deinit(self.alloc);
        var participant = relational_store_mod.WriteParticipant.initWithColumnIndexPolicy(
            self.alloc,
            self.core.store,
            &action_writes,
            &action_deletes,
            owned_keys,
            owned_values,
            self.relationalColumnIndexPolicyForStore(),
        );
        participant.configureForeignKeys(runtime_schema.default_type, runtime_schema.foreign_keys, &.{});
        participant.configurePrimaryKey(runtime_schema.primary_key);
        participant.configureUniqueConstraints(runtime_schema.unique_constraints);
        participant.configurePeriods(runtime_schema.periods, runtime_schema.relational_columns);
        var prepared = false;
        var closed = false;
        defer if (prepared and !closed) participant.abort(null);

        for (actions) |action| {
            if (action.constraint_name.len == 0 or action.parent_table.len == 0 or action.parent_key.len == 0 or action.child_key.len == 0) return error.ForeignKeyViolation;
            if (!isForeignKeyExternalDocKey(action.child_key)) return error.ForeignKeyViolation;
            const foreign_key = findRuntimeForeignKeyByName(runtime_schema.foreign_keys, action.constraint_name) orelse return error.ForeignKeyViolation;
            if (foreignKeyReferencesPrimaryKey(foreign_key) and !isForeignKeyExternalDocKey(action.parent_key)) return error.ForeignKeyViolation;
            switch (action.operation) {
                .delete => try participant.prepareCascadeForeignKeyChildAction(action.constraint_name, action.parent_table, action.parent_key, action.child_key),
                .update => {
                    const updated_parent_key = action.updated_parent_key orelse return error.ForeignKeyViolation;
                    if (foreignKeyReferencesPrimaryKey(foreign_key) and !isForeignKeyExternalDocKey(updated_parent_key)) return error.ForeignKeyViolation;
                    try participant.prepareCascadeForeignKeyUpdateChildAction(action.constraint_name, action.parent_table, action.parent_key, updated_parent_key, action.child_key);
                },
            }
            prepared = true;
        }
        if (!prepared) return;
        try participant.commit(null, 0);
        closed = true;

        for (action_writes.items) |write| {
            try intents.append(self.alloc, .{ .key = write.key, .value = write.value });
        }
        for (action_deletes.items) |key| {
            try intents.append(self.alloc, .{ .key = key, .value = null });
        }
    }

    fn appendForeignKeyConflictIntents(
        self: *DB,
        intents: *std.ArrayListUnmanaged(transactions_mod.WriteIntent),
        owned_keys: *std.ArrayListUnmanaged([]u8),
        writes: []const types.TransactionWrite,
        parent_delete_checks: []const types.ForeignKeyParentDeleteCheck,
        conflict_checks: []const types.ForeignKeyConflictCheck,
        ref_writes: []const types.ForeignKeyRefMutation,
    ) !void {
        if (writes.len == 0 and parent_delete_checks.len == 0 and conflict_checks.len == 0 and ref_writes.len == 0) return;
        if (self.core.schema) |runtime_schema| {
            for (writes) |write| {
                if (isMetadataKey(write.key) or internal_keys.isInternalPhysicalTableDataKey(write.key)) continue;
                for (runtime_schema.foreign_keys) |foreign_key| {
                    if (!foreignKeyNeedsRestrictConflictKey(foreign_key)) continue;
                    const parent_key = (try foreignKeyParentKeyFromJsonAlloc(self.alloc, runtime_schema.relational_columns, foreign_key, write.value)) orelse continue;
                    defer self.alloc.free(parent_key);
                    try appendForeignKeyConflictIntent(self.alloc, intents, owned_keys, foreign_key.name, foreign_key.parent_table, parent_key);
                }
            }
        }
        for (ref_writes) |mutation| {
            try appendForeignKeyConflictIntent(self.alloc, intents, owned_keys, mutation.constraint_name, mutation.parent_table, mutation.parent_key);
        }
        for (parent_delete_checks) |check| {
            try appendForeignKeyConflictIntent(self.alloc, intents, owned_keys, check.constraint_name, check.parent_table, check.parent_key);
        }
        for (conflict_checks) |check| {
            try appendForeignKeyConflictIntent(self.alloc, intents, owned_keys, check.constraint_name, check.parent_table, check.parent_key);
        }
    }

    fn appendForeignKeyConflictIntent(
        alloc: Allocator,
        intents: *std.ArrayListUnmanaged(transactions_mod.WriteIntent),
        owned_keys: *std.ArrayListUnmanaged([]u8),
        constraint_name: []const u8,
        parent_table: []const u8,
        parent_key: []const u8,
    ) !void {
        const key = try internal_keys.relationalForeignKeyConflictKeyAlloc(alloc, constraint_name, parent_table, parent_key);
        errdefer alloc.free(key);
        if (containsString(owned_keys.items, key)) {
            alloc.free(key);
            return;
        }
        try owned_keys.append(alloc, key);
        try intents.append(alloc, .{ .key = key, .value = null });
    }

    fn foreignKeyNeedsRestrictConflictKey(foreign_key: schema_mod.ForeignKey) bool {
        return foreign_key.validation_state == .enforced and
            foreignKeyDeleteActionRestricts(foreign_key) and
            foreign_key.parent_columns.len == 1 and
            std.mem.eql(u8, foreign_key.parent_columns[0], "_id");
    }

    fn validateForeignKeyParentChecks(
        self: *DB,
        checks: []const types.ForeignKeyParentCheck,
        writes: []const types.TransactionWrite,
        deletes: []const []const u8,
        unique_writes: []const types.UniqueConstraintMutation,
        unique_deletes: []const types.UniqueConstraintMutation,
    ) !void {
        if (checks.len == 0) return;
        const runtime_schema = self.core.schema orelse return error.ForeignKeyViolation;
        if (runtime_schema.storage_mode != .relational) return error.ForeignKeyViolation;
        for (checks) |check| {
            if (check.parent_key.len == 0 or check.parent_table.len == 0 or check.constraint_name.len == 0 or check.child_table.len == 0 or check.child_key.len == 0) return error.ForeignKeyViolation;
            if (!isForeignKeyExternalDocKey(check.child_key)) return error.ForeignKeyViolation;
            if (!std.mem.eql(u8, runtime_schema.default_type, check.parent_table)) return error.ForeignKeyViolation;
            const has_temporal_payload = check.child_period_start_json != null and check.child_period_end_json != null;
            if ((check.child_period_start_json == null) != (check.child_period_end_json == null)) return error.ForeignKeyViolation;
            if (has_temporal_payload) {
                try self.validateTemporalForeignKeyParentCheck(runtime_schema, check, deletes);
                continue;
            }
            if (check.parent_constraint_name) |constraint_name| {
                if (findUniqueConstraintByName(runtime_schema.unique_constraints, constraint_name) == null) return error.ForeignKeyViolation;
                if (findUniqueConstraintMutation(unique_deletes, constraint_name, check.parent_key) != null and
                    findUniqueConstraintMutation(unique_writes, constraint_name, check.parent_key) == null) return error.ForeignKeyViolation;
                if (findUniqueConstraintMutation(unique_writes, constraint_name, check.parent_key) != null) continue;
                const unique_key = try internal_keys.relationalUniqueKeyAlloc(self.alloc, constraint_name, check.parent_key);
                defer self.alloc.free(unique_key);
                const owner = self.core.store.get(self.alloc, unique_key) catch |err| switch (err) {
                    error.NotFound => return error.ForeignKeyViolation,
                    else => return err,
                };
                self.alloc.free(owner);
                continue;
            }
            if (!isForeignKeyExternalDocKey(check.parent_key)) return error.ForeignKeyViolation;
            if (containsString(deletes, check.parent_key)) return error.ForeignKeyViolation;
            if (containsTransactionWrite(writes, check.parent_key)) continue;
            const existing = try self.get(self.alloc, check.parent_key);
            defer if (existing) |body| self.alloc.free(body);
            if (existing == null) return error.ForeignKeyViolation;
        }
    }

    fn validateForeignKeyReferenceShapes(
        self: *DB,
        writes: []const types.TransactionWrite,
    ) !void {
        if (writes.len == 0) return;
        const runtime_schema = self.core.schema orelse return;
        if (runtime_schema.storage_mode != .relational or runtime_schema.foreign_keys.len == 0) return;
        for (writes) |write| {
            if (isMetadataKey(write.key) or internal_keys.isInternalPhysicalTableDataKey(write.key)) continue;
            for (runtime_schema.foreign_keys) |foreign_key| {
                if (foreign_key.validation_state != .enforced) continue;
                const parent_key = try foreignKeyParentKeyFromJsonAlloc(self.alloc, runtime_schema.relational_columns, foreign_key, write.value);
                defer if (parent_key) |value| self.alloc.free(value);
            }
        }
    }

    fn validateTemporalForeignKeyParentCheck(
        self: *DB,
        runtime_schema: schema_mod.TableSchema,
        check: types.ForeignKeyParentCheck,
        deletes: []const []const u8,
    ) !void {
        const start_json = check.child_period_start_json orelse return error.ForeignKeyViolation;
        const end_json = check.child_period_end_json orelse return error.ForeignKeyViolation;
        const parent_constraint = temporalForeignKeyParentConstraint(runtime_schema, check) orelse return error.ForeignKeyViolation;
        const parent_period_name = parent_constraint.without_overlaps_period orelse return error.ForeignKeyViolation;
        const parent_period = findRelationalRowsPeriod(runtime_schema.periods, parent_period_name) orelse return error.ForeignKeyViolation;
        const start_column = findRelationalRowsColumn(runtime_schema.relational_columns, parent_period.start_column) orelse return error.ForeignKeyViolation;
        const end_column = findRelationalRowsColumn(runtime_schema.relational_columns, parent_period.end_column) orelse return error.ForeignKeyViolation;
        const child_span = try relationalTemporalSpanFromBoundJsonAlloc(self.alloc, start_json, end_json, start_column, end_column);
        try self.requireTemporalForeignKeyParentCoverage(parent_constraint, check.parent_key, child_span, deletes);
    }

    fn temporalForeignKeyParentConstraint(
        runtime_schema: schema_mod.TableSchema,
        check: types.ForeignKeyParentCheck,
    ) ?schema_mod.UniqueConstraint {
        const name = check.parent_constraint_name orelse return null;
        if (runtime_schema.primary_key) |primary_key| {
            if (std.mem.eql(u8, name, relational_store_mod.primary_key_constraint_name)) {
                return relational_store_mod.primaryKeyAsUniqueConstraint(primary_key);
            }
        }
        return findUniqueConstraintByName(runtime_schema.unique_constraints, name);
    }

    fn relationalTemporalSpanFromBoundJsonAlloc(
        alloc: Allocator,
        start_json: []const u8,
        end_json: []const u8,
        start_column: schema_mod.RelationalColumn,
        end_column: schema_mod.RelationalColumn,
    ) !RelationalTemporalSpan {
        const start = try relationalRowsTemporalStartBoundFromJsonAlloc(alloc, start_json, start_column);
        const end = try relationalRowsTemporalEndBoundFromJsonAlloc(alloc, end_json, end_column);
        const span: RelationalTemporalSpan = .{ .start = start, .end = end };
        if (!relationalTemporalSpanValid(span)) return error.ForeignKeyViolation;
        return span;
    }

    fn requireTemporalForeignKeyParentCoverage(
        self: *DB,
        parent_constraint: schema_mod.UniqueConstraint,
        parent_key: []const u8,
        child_span: RelationalTemporalSpan,
        deletes: []const []const u8,
    ) !void {
        var covered_end = child_span.start;
        var matched_any = false;
        while (relationalTemporalBoundLessThan(covered_end, child_span.end)) {
            const next = try self.findTemporalForeignKeyParentCoverageEnd(parent_constraint, parent_key, covered_end, child_span.end, deletes);
            if (next == null) return error.ForeignKeyViolation;
            if (!relationalTemporalBoundLessThan(covered_end, next.?)) return error.ForeignKeyViolation;
            covered_end = next.?;
            matched_any = true;
        }
        if (!matched_any or !relationalTemporalBoundEqual(covered_end, child_span.end)) return error.ForeignKeyViolation;
    }

    fn findTemporalForeignKeyParentCoverageEnd(
        self: *DB,
        parent_constraint: schema_mod.UniqueConstraint,
        parent_key: []const u8,
        needed_start: RelationalTemporalBound,
        child_end: RelationalTemporalBound,
        deletes: []const []const u8,
    ) !?RelationalTemporalBound {
        const prefix = try internal_keys.relationalTemporalUniquePrefixAlloc(self.alloc, parent_constraint.name, parent_key);
        defer self.alloc.free(prefix);
        const upper = try internal_keys.relationalTemporalUniquePrefixUpperAlloc(self.alloc, parent_constraint.name, parent_key);
        defer if (upper) |buf| self.alloc.free(buf);
        const scanned = try self.core.store.scanRange(self.alloc, prefix, if (upper) |buf| buf else "");
        defer docstore_mod.DocStore.freeResults(self.alloc, scanned);
        var best: ?RelationalTemporalBound = null;
        for (scanned) |entry| {
            if (containsString(deletes, entry.value)) continue;
            const span = try decodeTemporalForeignKeyOwnerSpanFromKeyAlloc(self.alloc, entry.key, prefix);
            best = temporalForeignKeyCoverageCandidateEnd(best, needed_start, child_end, span);
        }
        return best;
    }

    fn temporalForeignKeyCoverageCandidateEnd(
        current_best: ?RelationalTemporalBound,
        needed_start: RelationalTemporalBound,
        child_end: RelationalTemporalBound,
        parent_span: RelationalTemporalSpan,
    ) ?RelationalTemporalBound {
        if (relationalTemporalBoundLessThan(needed_start, parent_span.start)) return current_best;
        if (!relationalTemporalBoundLessThan(needed_start, parent_span.end)) return current_best;
        const candidate = if (relationalTemporalBoundLessThan(child_end, parent_span.end)) child_end else parent_span.end;
        if (current_best) |best| {
            return if (relationalTemporalBoundLessThan(best, candidate)) candidate else best;
        }
        return candidate;
    }

    fn decodeTemporalForeignKeyOwnerSpanFromKeyAlloc(
        alloc: Allocator,
        key: []const u8,
        prefix: []const u8,
    ) !RelationalTemporalSpan {
        if (!std.mem.startsWith(u8, key, prefix)) return error.ForeignKeyViolation;
        var pos: usize = prefix.len;
        const start_term = internal_keys.findComponentTerminator(key, pos) orelse return error.ForeignKeyViolation;
        const start = try internal_keys.decodeBodyAlloc(alloc, key[pos..start_term]);
        defer alloc.free(start);
        pos = start_term + 2;
        const end_term = internal_keys.findComponentTerminator(key, pos) orelse return error.ForeignKeyViolation;
        const end = try internal_keys.decodeBodyAlloc(alloc, key[pos..end_term]);
        defer alloc.free(end);
        return .{
            .start = try relationalTemporalBoundFromOwnerBytes(start),
            .end = try relationalTemporalBoundFromOwnerBytes(end),
        };
    }

    fn relationalTemporalBoundFromOwnerBytes(bytes: []const u8) !RelationalTemporalBound {
        if (bytes.len == 1 and bytes[0] == temporal_bound_neg_infinity_tag) return .neg_infinity;
        if (bytes.len == 1 and bytes[0] == temporal_bound_pos_infinity_tag) return .pos_infinity;
        if (bytes.len != 9) return error.ForeignKeyViolation;
        const raw = std.mem.readInt(u64, bytes[1..9], .big);
        if (bytes[0] == @intFromEnum(temporal_typed_dv.ValueType.f64_val)) return .{ .number = @bitCast(raw) };
        if (bytes[0] == @intFromEnum(temporal_typed_dv.ValueType.u64_val)) return .{ .datetime_ns = @bitCast(raw) };
        return error.ForeignKeyViolation;
    }

    fn validateExternalizedForeignKeyParentChecks(
        self: *DB,
        checks: []const types.ForeignKeyParentCheck,
        constraint_timing_overrides: []const types.ForeignKeyConstraintTimingOverride,
        writes: []const types.TransactionWrite,
    ) !void {
        const runtime_schema = self.core.schema orelse {
            if (checks.len > 0) return error.ForeignKeyViolation;
            return;
        };
        if (runtime_schema.storage_mode != .relational or runtime_schema.foreign_keys.len == 0) {
            if (checks.len > 0) return error.ForeignKeyViolation;
            return;
        }
        for (checks) |check| {
            if (check.constraint_name.len == 0 or check.child_table.len == 0 or check.child_key.len == 0 or check.parent_table.len == 0 or check.parent_key.len == 0) return error.ForeignKeyViolation;
            const foreign_key = findRuntimeForeignKeyByName(runtime_schema.foreign_keys, check.constraint_name) orelse return error.ForeignKeyViolation;
            if (foreign_key.validation_state != .enforced) return error.ForeignKeyViolation;
            if (check.timing != effectiveForeignKeyParentCheckTiming(foreign_key, constraint_timing_overrides)) return error.ForeignKeyViolation;
            const has_temporal_payload = check.child_period_start_json != null and check.child_period_end_json != null;
            if ((check.child_period_start_json == null) != (check.child_period_end_json == null)) return error.ForeignKeyViolation;
            if ((foreign_key.child_period != null or foreign_key.parent_period != null) != has_temporal_payload) return error.ForeignKeyViolation;
            if (!std.mem.eql(u8, check.child_table, runtime_schema.default_type)) return error.ForeignKeyViolation;
            if (!std.mem.eql(u8, check.parent_table, foreign_key.parent_table)) return error.ForeignKeyViolation;
            if (!isForeignKeyExternalDocKey(check.child_key)) return error.ForeignKeyViolation;
            if (foreignKeyReferencesPrimaryKey(foreign_key)) {
                if (!isForeignKeyExternalDocKey(check.parent_key)) return error.ForeignKeyViolation;
                if (check.parent_constraint_name != null) return error.ForeignKeyViolation;
            } else {
                const parent_constraint_name = check.parent_constraint_name orelse return error.ForeignKeyViolation;
                if (parent_constraint_name.len == 0) return error.ForeignKeyViolation;
                if (std.mem.eql(u8, foreign_key.parent_table, runtime_schema.default_type)) {
                    if (foreign_key.parent_period) |parent_period| {
                        const parent_constraint = temporalForeignKeyParentConstraint(runtime_schema, check) orelse return error.ForeignKeyViolation;
                        if (!stringSlicesEqual(parent_constraint.columns, foreign_key.parent_columns)) return error.ForeignKeyViolation;
                        if (parent_constraint.without_overlaps_period == null or
                            !std.mem.eql(u8, parent_constraint.without_overlaps_period.?, parent_period))
                        {
                            return error.ForeignKeyViolation;
                        }
                    } else {
                        const parent_constraint = findUniqueConstraintByName(runtime_schema.unique_constraints, parent_constraint_name) orelse return error.ForeignKeyViolation;
                        if (!uniqueConstraintCanBackForeignKey(parent_constraint)) return error.ForeignKeyViolation;
                        if (!stringSlicesEqual(parent_constraint.columns, foreign_key.parent_columns)) return error.ForeignKeyViolation;
                    }
                }
            }
        }
        if (writes.len == 0) return;
        for (runtime_schema.foreign_keys) |foreign_key| {
            if (foreign_key.validation_state != .enforced or effectiveForeignKeyParentCheckTiming(foreign_key, constraint_timing_overrides) != .deferred) continue;
            for (writes) |write| {
                if (isMetadataKey(write.key) or internal_keys.isInternalPhysicalTableDataKey(write.key)) continue;
                const parent_key = (try foreignKeyParentKeyFromJsonAlloc(self.alloc, runtime_schema.relational_columns, foreign_key, write.value)) orelse continue;
                defer self.alloc.free(parent_key);
                var child_period_bounds = try foreignKeyChildPeriodBoundsFromJsonAlloc(self.alloc, runtime_schema, foreign_key, write.value);
                defer child_period_bounds.deinit(self.alloc);
                if (!containsExternalizedForeignKeyParentCheck(checks, foreign_key, runtime_schema.default_type, write.key, parent_key, child_period_bounds.start_json, child_period_bounds.end_json)) return error.ForeignKeyViolation;
            }
        }
    }

    fn containsExternalizedForeignKeyParentCheck(
        checks: []const types.ForeignKeyParentCheck,
        foreign_key: schema_mod.ForeignKey,
        child_table: []const u8,
        child_key: []const u8,
        parent_key: []const u8,
        child_period_start_json: ?[]const u8,
        child_period_end_json: ?[]const u8,
    ) bool {
        for (checks) |check| {
            if (check.timing != .deferred) continue;
            if (!std.mem.eql(u8, check.constraint_name, foreign_key.name)) continue;
            if (!std.mem.eql(u8, check.child_table, child_table)) continue;
            if (!std.mem.eql(u8, check.child_key, child_key)) continue;
            if (!std.mem.eql(u8, check.parent_table, foreign_key.parent_table)) continue;
            if (!std.mem.eql(u8, check.parent_key, parent_key)) continue;
            if (!optionalStringsEqual(check.child_period_start_json, child_period_start_json)) continue;
            if (!optionalStringsEqual(check.child_period_end_json, child_period_end_json)) continue;
            return true;
        }
        return false;
    }

    fn validateForeignKeyConstraintTimingOverrides(
        self: *DB,
        overrides: []const types.ForeignKeyConstraintTimingOverride,
    ) !void {
        if (overrides.len == 0) return;
        const runtime_schema = self.core.schema orelse return error.ForeignKeyViolation;
        if (runtime_schema.storage_mode != .relational) return error.ForeignKeyViolation;
        for (overrides, 0..) |override, i| {
            if (override.constraint_name.len == 0) return error.ForeignKeyViolation;
            if (override.timing != .immediate and override.timing != .deferred) return error.ForeignKeyViolation;
            for (overrides[0..i]) |previous| {
                if (std.mem.eql(u8, previous.constraint_name, override.constraint_name)) return error.ForeignKeyViolation;
            }
            const foreign_key = findRuntimeForeignKeyByName(runtime_schema.foreign_keys, override.constraint_name) orelse return error.ForeignKeyViolation;
            if (foreign_key.validation_state != .enforced) return error.ForeignKeyViolation;
            if (!foreign_key.deferrable) return error.ForeignKeyViolation;
        }
    }

    fn effectiveForeignKeyParentCheckTiming(
        foreign_key: schema_mod.ForeignKey,
        overrides: []const types.ForeignKeyConstraintTimingOverride,
    ) types.ForeignKeyParentCheck.Timing {
        for (overrides) |override| {
            if (std.mem.eql(u8, override.constraint_name, foreign_key.name)) return override.timing;
        }
        return foreignKeyParentCheckTiming(foreign_key);
    }

    fn foreignKeyParentCheckTiming(foreign_key: schema_mod.ForeignKey) types.ForeignKeyParentCheck.Timing {
        return switch (foreign_key.timing) {
            .immediate => .immediate,
            .deferred => .deferred,
        };
    }

    fn foreignKeyDeleteActionRestricts(foreign_key: schema_mod.ForeignKey) bool {
        return foreign_key.on_delete == .restrict or foreign_key.on_delete == .no_action;
    }

    fn foreignKeyUpdateActionRestricts(foreign_key: schema_mod.ForeignKey) bool {
        return foreign_key.on_update == .restrict or foreign_key.on_update == .no_action;
    }

    fn containsTransactionWrite(writes: []const types.TransactionWrite, key: []const u8) bool {
        for (writes) |write| {
            if (std.mem.eql(u8, write.key, key)) return true;
        }
        return false;
    }

    fn containsString(values: []const []const u8, key: []const u8) bool {
        for (values) |value| {
            if (std.mem.eql(u8, value, key)) return true;
        }
        return false;
    }

    fn validateForeignKeyParentDeleteChecks(
        self: *DB,
        checks: []const types.ForeignKeyParentDeleteCheck,
        constraint_timing_overrides: []const types.ForeignKeyConstraintTimingOverride,
        writes: []const types.TransactionWrite,
        deletes: []const []const u8,
        ref_writes: []const types.ForeignKeyRefMutation,
        ref_deletes: []const types.ForeignKeyRefMutation,
    ) !void {
        if (checks.len == 0) return;
        const runtime_schema = self.core.schema orelse return error.ForeignKeyViolation;
        if (runtime_schema.storage_mode != .relational) return error.ForeignKeyViolation;
        for (checks) |check| {
            if (check.constraint_name.len == 0 or check.parent_table.len == 0 or check.parent_key.len == 0) return error.ForeignKeyViolation;
            const foreign_key = findRuntimeForeignKeyByName(runtime_schema.foreign_keys, check.constraint_name) orelse return error.ForeignKeyViolation;
            if (foreign_key.validation_state != .enforced) return error.ForeignKeyViolation;
            if (check.timing != effectiveForeignKeyParentCheckTiming(foreign_key, constraint_timing_overrides)) return error.ForeignKeyViolation;
            switch (check.operation) {
                .delete => if (!foreignKeyDeleteActionRestricts(foreign_key)) continue,
                .update => if (!foreignKeyUpdateActionRestricts(foreign_key)) continue,
            }
            if (foreignKeyReferencesPrimaryKey(foreign_key) and !isForeignKeyExternalDocKey(check.parent_key)) return error.ForeignKeyViolation;
            if (!std.mem.eql(u8, foreign_key.parent_table, check.parent_table)) return error.ForeignKeyViolation;

            for (writes) |write| {
                if (isMetadataKey(write.key) or internal_keys.isInternalPhysicalTableDataKey(write.key)) continue;
                if (try foreignKeyWriteReferencesParent(self.alloc, runtime_schema.relational_columns, foreign_key, write.value, check.parent_key)) return error.ForeignKeyViolation;
            }
            for (ref_writes) |mutation| {
                if (foreignKeyRefMutationMatchesParentDeleteCheck(mutation, check)) return error.ForeignKeyViolation;
            }

            const prefix = try internal_keys.relationalForeignKeyRefParentPrefixAlloc(self.alloc, foreign_key.name, foreign_key.parent_table, check.parent_key);
            defer self.alloc.free(prefix);
            const upper = try internal_keys.relationalForeignKeyRefParentPrefixUpperAlloc(self.alloc, foreign_key.name, foreign_key.parent_table, check.parent_key);
            defer if (upper) |buf| self.alloc.free(buf);
            const scanned = try self.core.store.scanRange(self.alloc, prefix, if (upper) |buf| buf else "");
            defer docstore_mod.DocStore.freeResults(self.alloc, scanned);
            for (scanned) |entry| {
                var decoded = (try internal_keys.decodeRelationalForeignKeyRefKeyAlloc(self.alloc, entry.key)) orelse continue;
                defer decoded.deinit(self.alloc);
                if (!std.mem.eql(u8, decoded.child_table, runtime_schema.default_type)) continue;
                if (containsString(deletes, decoded.child_key)) continue;
                if (containsForeignKeyRefDelete(ref_deletes, decoded, check)) continue;
                if (findTransactionWrite(writes, decoded.child_key)) |write| {
                    if (!try foreignKeyWriteReferencesParent(self.alloc, runtime_schema.relational_columns, foreign_key, write.value, check.parent_key)) continue;
                }
                return error.ForeignKeyViolation;
            }
        }
    }

    fn validateForeignKeyRefMutations(self: *DB, mutations: []const types.ForeignKeyRefMutation) !void {
        if (mutations.len == 0) return;
        const runtime_schema = self.core.schema orelse return error.ForeignKeyViolation;
        if (runtime_schema.storage_mode != .relational) return error.ForeignKeyViolation;
        for (mutations) |mutation| {
            if (mutation.constraint_name.len == 0 or mutation.parent_table.len == 0 or mutation.parent_key.len == 0 or mutation.child_table.len == 0 or mutation.child_key.len == 0) return error.ForeignKeyViolation;
            if (!isForeignKeyExternalDocKey(mutation.child_key)) return error.ForeignKeyViolation;
            if (!std.mem.eql(u8, mutation.child_table, runtime_schema.default_type)) return error.ForeignKeyViolation;
            const foreign_key = findRuntimeForeignKeyByName(runtime_schema.foreign_keys, mutation.constraint_name) orelse return error.ForeignKeyViolation;
            if (foreign_key.validation_state != .enforced) return error.ForeignKeyViolation;
            if (!std.mem.eql(u8, foreign_key.parent_table, mutation.parent_table)) return error.ForeignKeyViolation;
            if (foreignKeyReferencesPrimaryKey(foreign_key)) {
                if (!isForeignKeyExternalDocKey(mutation.parent_key)) return error.ForeignKeyViolation;
            }
        }
    }

    fn foreignKeyRefMutationMatchesParentDeleteCheck(mutation: types.ForeignKeyRefMutation, check: types.ForeignKeyParentDeleteCheck) bool {
        return std.mem.eql(u8, mutation.constraint_name, check.constraint_name) and
            std.mem.eql(u8, mutation.parent_table, check.parent_table) and
            std.mem.eql(u8, mutation.parent_key, check.parent_key);
    }

    fn containsForeignKeyRefDelete(
        ref_deletes: []const types.ForeignKeyRefMutation,
        decoded: internal_keys.RelationalForeignKeyRefKey,
        check: types.ForeignKeyParentDeleteCheck,
    ) bool {
        for (ref_deletes) |mutation| {
            if (!foreignKeyRefMutationMatchesParentDeleteCheck(mutation, check)) continue;
            if (!std.mem.eql(u8, mutation.child_table, decoded.child_table)) continue;
            if (!std.mem.eql(u8, mutation.child_key, decoded.child_key)) continue;
            return true;
        }
        return false;
    }

    fn isForeignKeyExternalDocKey(key: []const u8) bool {
        return !isMetadataKey(key) and !internal_keys.isInternalPhysicalTableDataKey(key);
    }

    fn findRuntimeForeignKeyByName(foreign_keys: []const schema_mod.ForeignKey, name: []const u8) ?schema_mod.ForeignKey {
        for (foreign_keys) |foreign_key| {
            if (std.mem.eql(u8, foreign_key.name, name)) return foreign_key;
        }
        return null;
    }

    fn foreignKeyReferencesPrimaryKey(foreign_key: schema_mod.ForeignKey) bool {
        return foreign_key.parent_columns.len == 1 and std.mem.eql(u8, foreign_key.parent_columns[0], "_id");
    }

    fn findTransactionWrite(writes: []const types.TransactionWrite, key: []const u8) ?types.TransactionWrite {
        for (writes) |write| {
            if (std.mem.eql(u8, write.key, key)) return write;
        }
        return null;
    }

    fn foreignKeyWriteReferencesParent(
        alloc: Allocator,
        relational_columns: []const schema_mod.RelationalColumn,
        foreign_key: schema_mod.ForeignKey,
        value: []const u8,
        parent_key: []const u8,
    ) !bool {
        const actual_parent_key = (try foreignKeyParentKeyFromJsonAlloc(alloc, relational_columns, foreign_key, value)) orelse return false;
        defer alloc.free(actual_parent_key);
        return std.mem.eql(u8, actual_parent_key, parent_key);
    }

    fn foreignKeyParentKeyFromJsonAlloc(
        alloc: Allocator,
        relational_columns: []const schema_mod.RelationalColumn,
        foreign_key: schema_mod.ForeignKey,
        value: []const u8,
    ) !?[]u8 {
        const row = try mapper.buildRelationalRowValueAlloc(alloc, value, relational_columns);
        defer alloc.free(row);
        return try relational_store_mod.foreignKeyReferenceValueAlloc(alloc, row, foreign_key);
    }

    const ForeignKeyChildPeriodJsonBounds = struct {
        start_json: ?[]const u8 = null,
        end_json: ?[]const u8 = null,

        fn deinit(self: *@This(), alloc: Allocator) void {
            if (self.start_json) |json| alloc.free(@constCast(json));
            if (self.end_json) |json| alloc.free(@constCast(json));
            self.* = .{};
        }
    };

    fn foreignKeyChildPeriodBoundsFromJsonAlloc(
        alloc: Allocator,
        runtime_schema: schema_mod.TableSchema,
        foreign_key: schema_mod.ForeignKey,
        value: []const u8,
    ) !ForeignKeyChildPeriodJsonBounds {
        const period_name = foreign_key.child_period orelse return .{};
        const period = findRelationalRowsPeriod(runtime_schema.periods, period_name) orelse return error.ForeignKeyViolation;
        var parsed = std.json.parseFromSlice(std.json.Value, alloc, value, .{}) catch return error.ForeignKeyViolation;
        defer parsed.deinit();
        const obj = switch (parsed.value) {
            .object => |object| object,
            else => return error.ForeignKeyViolation,
        };
        const start_value = obj.get(period.start_column) orelse return error.ForeignKeyViolation;
        const end_value = obj.get(period.end_column) orelse return error.ForeignKeyViolation;
        const start_json = try std.json.Stringify.valueAlloc(alloc, start_value, .{ .emit_null_optional_fields = false });
        errdefer alloc.free(start_json);
        const end_json = try std.json.Stringify.valueAlloc(alloc, end_value, .{ .emit_null_optional_fields = false });
        errdefer alloc.free(end_json);
        return .{ .start_json = start_json, .end_json = end_json };
    }

    // resolveTransactionTransforms, removePendingTransactionWrite, and freeTransactionWritesOwned
    // request coalescing is consolidated into coalesceKeyValueRequest above

    pub fn commitTransaction(self: *DB, txn_id: transactions_mod.TxnId, timestamp_ns: u64) !void {
        try self.resolveTransactionIntents(txn_id, .committed, timestamp_ns);
    }

    pub fn resolveTransactionIntents(self: *DB, txn_id: transactions_mod.TxnId, status: transactions_mod.TxnStatus, commit_version: u64) !void {
        lockApply(self);
        defer self.core.unlockApply();

        var raw_identity_upserts = std.ArrayListUnmanaged([]const u8).empty;
        defer {
            for (raw_identity_upserts.items) |key| self.alloc.free(@constCast(key));
            raw_identity_upserts.deinit(self.alloc);
        }
        var raw_identity_deletes = std.ArrayListUnmanaged([]const u8).empty;
        defer {
            for (raw_identity_deletes.items) |key| self.alloc.free(@constCast(key));
            raw_identity_deletes.deinit(self.alloc);
        }
        var identity_upserts = std.ArrayListUnmanaged([]const u8).empty;
        defer identity_upserts.deinit(self.alloc);
        var identity_deletes = std.ArrayListUnmanaged([]const u8).empty;
        defer identity_deletes.deinit(self.alloc);
        var identity_writes = std.ArrayListUnmanaged(docstore_mod.KVPair).empty;
        defer {
            for (identity_writes.items) |item| {
                self.alloc.free(@constCast(item.key));
                self.alloc.free(@constCast(item.value));
            }
            identity_writes.deinit(self.alloc);
        }
        var relational_extra_writes = std.ArrayListUnmanaged(docstore_mod.KVPair).empty;
        defer {
            for (relational_extra_writes.items) |item| {
                self.alloc.free(@constCast(item.key));
                self.alloc.free(@constCast(item.value));
            }
            relational_extra_writes.deinit(self.alloc);
        }
        var relational_extra_deletes = std.ArrayListUnmanaged([]const u8).empty;
        defer {
            for (relational_extra_deletes.items) |key| self.alloc.free(@constCast(key));
            relational_extra_deletes.deinit(self.alloc);
        }
        var relational_skip_intent_keys = std.ArrayListUnmanaged([]const u8).empty;
        defer {
            for (relational_skip_intent_keys.items) |key| self.alloc.free(@constCast(key));
            relational_skip_intent_keys.deinit(self.alloc);
        }

        if (status == .committed) {
            try self.core.collectTransactionIntentDocumentKeys(self.alloc, txn_id, &raw_identity_upserts, &raw_identity_deletes);
            for (raw_identity_upserts.items) |key| {
                if (!isMetadataKey(key) and !internal_keys.isInternalPhysicalTableDataKey(key)) try identity_upserts.append(self.alloc, key);
            }
            for (raw_identity_deletes.items) |key| {
                if (!isMetadataKey(key) and !internal_keys.isInternalPhysicalTableDataKey(key)) try identity_deletes.append(self.alloc, key);
            }
            const metadata_mutations = try self.core.collectTransactionIntentMutations(self.alloc, txn_id);
            defer {
                for (metadata_mutations) |*mutation| mutation.deinit(self.alloc);
                if (metadata_mutations.len > 0) self.alloc.free(metadata_mutations);
            }
            for (metadata_mutations) |mutation| {
                if (!isRowClaimIntentMetadataKey(mutation.key) and !isForeignKeyActionScheduleMetadataKey(mutation.key)) continue;
                const skip_key = try self.alloc.dupe(u8, mutation.key);
                var skip_key_owned = true;
                errdefer if (skip_key_owned) self.alloc.free(skip_key);
                if (isRowClaimIntentMetadataKey(mutation.key)) {
                    try relational_skip_intent_keys.append(self.alloc, skip_key);
                    skip_key_owned = false;
                    continue;
                }
                try relational_skip_intent_keys.append(self.alloc, skip_key);
                skip_key_owned = false;

                const metadata_key = try self.alloc.dupe(u8, mutation.key);
                var metadata_key_owned = true;
                errdefer if (metadata_key_owned) self.alloc.free(metadata_key);
                if (mutation.value) |value| {
                    const metadata_value = try self.alloc.dupe(u8, value);
                    var metadata_value_owned = true;
                    errdefer if (metadata_value_owned) self.alloc.free(metadata_value);
                    try relational_extra_writes.append(self.alloc, .{ .key = metadata_key, .value = metadata_value });
                    metadata_key_owned = false;
                    metadata_value_owned = false;
                } else {
                    try relational_extra_deletes.append(self.alloc, metadata_key);
                    metadata_key_owned = false;
                }
            }
            try doc_identity.appendBatchIdentityMetadataForNamespaceAlloc(
                self.alloc,
                self.core.store,
                self.core.identity_namespace,
                self.core.nextDerivedSequence(),
                &identity_writes,
                identity_upserts.items,
                identity_deletes.items,
            );
            if (self.relationalColumnsForStore() != null) {
                const mutations = try self.core.collectTransactionIntentMutations(self.alloc, txn_id);
                defer {
                    for (mutations) |*mutation| mutation.deinit(self.alloc);
                    if (mutations.len > 0) self.alloc.free(mutations);
                }
                std.mem.sort(transactions_mod.OwnedIntentMutation, mutations, {}, struct {
                    fn lessThan(_: void, lhs: transactions_mod.OwnedIntentMutation, rhs: transactions_mod.OwnedIntentMutation) bool {
                        const lhs_is_write = lhs.value != null;
                        const rhs_is_write = rhs.value != null;
                        if (lhs_is_write != rhs_is_write) return lhs_is_write;
                        return std.mem.lessThan(u8, lhs.key, rhs.key);
                    }
                }.lessThan);
                const externalized_fk_parent_checks = try collectTransactionExternalizedForeignKeyParentChecksAlloc(
                    self.alloc,
                    mutations,
                    &relational_skip_intent_keys,
                );
                defer freeExternalizedForeignKeyParentChecks(self.alloc, externalized_fk_parent_checks);
                const fk_constraint_timing_overrides = try collectTransactionForeignKeyConstraintTimingOverridesAlloc(
                    self.alloc,
                    mutations,
                    &relational_skip_intent_keys,
                );
                defer freeRelationalForeignKeyConstraintTimingOverrides(self.alloc, fk_constraint_timing_overrides);
                const relational_identity_rewrites = try collectTransactionRelationalIdentityRewritesAlloc(
                    self.alloc,
                    mutations,
                    &relational_skip_intent_keys,
                );
                defer freeRelationalIdentityRewrites(self.alloc, relational_identity_rewrites);
                var relational_intent_delete_keys = std.ArrayListUnmanaged([]const u8).empty;
                defer relational_intent_delete_keys.deinit(self.alloc);
                for (mutations) |mutation| {
                    if (isMetadataKey(mutation.key) or internal_keys.isInternalPhysicalTableDataKey(mutation.key)) continue;
                    if (isRelationalIdentityRewriteEndpoint(relational_identity_rewrites, mutation.key)) continue;
                    if (mutation.value == null) try relational_intent_delete_keys.append(self.alloc, mutation.key);
                }
                var relational_extra_owned_keys = std.ArrayListUnmanaged([]u8).empty;
                defer {
                    for (relational_extra_owned_keys.items) |key| self.alloc.free(key);
                    relational_extra_owned_keys.deinit(self.alloc);
                }
                var relational_extra_owned_values = std.ArrayListUnmanaged([]u8).empty;
                defer {
                    for (relational_extra_owned_values.items) |value| self.alloc.free(value);
                    relational_extra_owned_values.deinit(self.alloc);
                }
                var relational_participant = relational_store_mod.WriteParticipant.initWithColumnIndexPolicy(
                    self.alloc,
                    self.core.store,
                    &relational_extra_writes,
                    &relational_extra_deletes,
                    &relational_extra_owned_keys,
                    &relational_extra_owned_values,
                    self.relationalColumnIndexPolicyForStore(),
                );
                var relational_table_name: []const u8 = "";
                if (self.core.schema) |runtime_schema| {
                    relational_table_name = runtime_schema.default_type;
                    relational_participant.configureForeignKeys(runtime_schema.default_type, runtime_schema.foreign_keys, relational_intent_delete_keys.items);
                    relational_participant.configureExternalizedForeignKeyParentChecks(externalized_fk_parent_checks);
                    relational_participant.configureForeignKeyConstraintTimingOverrides(fk_constraint_timing_overrides);
                    relational_participant.configurePrimaryKey(runtime_schema.primary_key);
                    relational_participant.configureUniqueConstraints(runtime_schema.unique_constraints);
                    relational_participant.configurePeriods(runtime_schema.periods, runtime_schema.relational_columns);
                }
                var relational_participant_prepared = false;
                var relational_participant_closed = false;
                defer if (relational_participant_prepared and !relational_participant_closed)
                    relational_participant.abort(null);
                for (relational_identity_rewrites) |rewrite| {
                    const skip_old_key = try self.alloc.dupe(u8, rewrite.old_key);
                    var skip_old_key_owned = true;
                    errdefer if (skip_old_key_owned) self.alloc.free(skip_old_key);
                    try relational_skip_intent_keys.append(self.alloc, skip_old_key);
                    skip_old_key_owned = false;
                    const skip_new_key = try self.alloc.dupe(u8, rewrite.new_key);
                    var skip_new_key_owned = true;
                    errdefer if (skip_new_key_owned) self.alloc.free(skip_new_key);
                    try relational_skip_intent_keys.append(self.alloc, skip_new_key);
                    skip_new_key_owned = false;

                    const relational_columns = self.relationalColumnsForStore() orelse return error.UnsupportedOperation;
                    const row_value = try relationalStoreRowValueAlloc(self.alloc, rewrite.value, relational_columns, &relational_extra_owned_values);
                    relational_participant_prepared = true;
                    relational_participant.prepareIdentityRewrite(
                        relational_table_name,
                        rewrite.old_key,
                        rewrite.new_key,
                        row_value,
                        txn_id,
                    ) catch |err| {
                        if (err == error.ForeignKeyViolation) self.recordForeignKeyParentDeleteReject();
                        return err;
                    };
                    const old_document_key = try internal_keys.documentKeyAlloc(self.alloc, rewrite.old_key);
                    var old_document_key_owned = true;
                    errdefer if (old_document_key_owned) self.alloc.free(old_document_key);
                    try relational_extra_owned_keys.append(self.alloc, old_document_key);
                    old_document_key_owned = false;
                    try relational_extra_deletes.append(self.alloc, old_document_key);
                    const new_document_key = try internal_keys.documentKeyAlloc(self.alloc, rewrite.new_key);
                    var new_document_key_owned = true;
                    errdefer if (new_document_key_owned) self.alloc.free(new_document_key);
                    try relational_extra_owned_keys.append(self.alloc, new_document_key);
                    new_document_key_owned = false;
                    try relational_extra_deletes.append(self.alloc, new_document_key);
                    if (shouldWriteTimestamp(rewrite.old_key)) {
                        const old_timestamp_key = try makeTimestampKey(self.alloc, rewrite.old_key);
                        var old_timestamp_key_owned = true;
                        errdefer if (old_timestamp_key_owned) self.alloc.free(old_timestamp_key);
                        try relational_extra_owned_keys.append(self.alloc, old_timestamp_key);
                        old_timestamp_key_owned = false;
                        try relational_extra_deletes.append(self.alloc, old_timestamp_key);
                    }
                    if (shouldWriteTimestamp(rewrite.new_key)) {
                        const new_timestamp_key = try makeTimestampKey(self.alloc, rewrite.new_key);
                        var new_timestamp_key_owned = true;
                        errdefer if (new_timestamp_key_owned) self.alloc.free(new_timestamp_key);
                        const timestamp_value = try encodeTimestampValue(self.alloc, commit_version);
                        var timestamp_value_owned = true;
                        errdefer if (timestamp_value_owned) self.alloc.free(timestamp_value);
                        try relational_extra_owned_keys.append(self.alloc, new_timestamp_key);
                        new_timestamp_key_owned = false;
                        try relational_extra_owned_values.append(self.alloc, timestamp_value);
                        timestamp_value_owned = false;
                        try relational_extra_writes.append(self.alloc, .{ .key = new_timestamp_key, .value = timestamp_value });
                    }
                }
                for (mutations) |mutation| {
                    if (isMetadataKey(mutation.key) or internal_keys.isInternalPhysicalTableDataKey(mutation.key)) continue;
                    if (isRelationalIdentityRewriteEndpoint(relational_identity_rewrites, mutation.key)) continue;
                    const skip_key = try self.alloc.dupe(u8, mutation.key);
                    var skip_key_owned = true;
                    errdefer if (skip_key_owned) self.alloc.free(skip_key);
                    try relational_skip_intent_keys.append(self.alloc, skip_key);
                    skip_key_owned = false;

                    if (mutation.value) |value| {
                        const row_value = try self.alloc.dupe(u8, value);
                        var row_value_owned = true;
                        errdefer if (row_value_owned) self.alloc.free(row_value);
                        relational_participant_prepared = true;
                        relational_participant.prepareUpsert(
                            relational_table_name,
                            mutation.key,
                            row_value,
                            txn_id,
                        ) catch |err| {
                            if (err == error.ForeignKeyViolation) self.recordForeignKeyChildWriteReject();
                            return err;
                        };
                        try relational_extra_owned_values.append(self.alloc, row_value);
                        row_value_owned = false;
                        if (shouldWriteTimestamp(mutation.key)) {
                            const timestamp_key = try makeTimestampKey(self.alloc, mutation.key);
                            var timestamp_key_owned = true;
                            errdefer if (timestamp_key_owned) self.alloc.free(timestamp_key);
                            const timestamp_value = try encodeTimestampValue(self.alloc, commit_version);
                            var timestamp_value_owned = true;
                            errdefer if (timestamp_value_owned) self.alloc.free(timestamp_value);
                            try relational_extra_owned_keys.append(self.alloc, timestamp_key);
                            timestamp_key_owned = false;
                            try relational_extra_owned_values.append(self.alloc, timestamp_value);
                            timestamp_value_owned = false;
                            try relational_extra_writes.append(self.alloc, .{ .key = timestamp_key, .value = timestamp_value });
                        }
                    } else {
                        relational_participant_prepared = true;
                        relational_participant.prepareDelete(
                            relational_table_name,
                            mutation.key,
                            txn_id,
                        ) catch |err| {
                            if (err == error.ForeignKeyViolation) self.recordForeignKeyParentDeleteReject();
                            return err;
                        };
                        if (shouldWriteTimestamp(mutation.key)) {
                            const timestamp_key = try makeTimestampKey(self.alloc, mutation.key);
                            var timestamp_key_owned = true;
                            errdefer if (timestamp_key_owned) self.alloc.free(timestamp_key);
                            try relational_extra_owned_keys.append(self.alloc, timestamp_key);
                            timestamp_key_owned = false;
                            try relational_extra_deletes.append(self.alloc, timestamp_key);
                        }
                    }

                    const primary_key = try internal_keys.documentKeyAlloc(self.alloc, mutation.key);
                    var primary_key_owned = true;
                    errdefer if (primary_key_owned) self.alloc.free(primary_key);
                    try relational_extra_owned_keys.append(self.alloc, primary_key);
                    primary_key_owned = false;
                    try relational_extra_deletes.append(self.alloc, primary_key);
                }
                relational_participant.commit(txn_id, commit_version) catch |err| {
                    if (err == error.ForeignKeyViolation) self.recordForeignKeyChildWriteReject();
                    return err;
                };
                relational_participant_closed = true;
                relational_extra_owned_keys.clearRetainingCapacity();
                relational_extra_owned_values.clearRetainingCapacity();
            }
        }

        const pending_identity_visibility_summary = try doc_identity.visibilitySummaryFromWrites(identity_writes.items);
        try identity_writes.appendSlice(self.alloc, relational_extra_writes.items);
        relational_extra_writes.clearRetainingCapacity();
        try self.core.resolveTransactionIntentsWithExtraBatch(txn_id, status, commit_version, .{
            .writes = identity_writes.items,
            .deletes = relational_extra_deletes.items,
            .skip_intent_keys = relational_skip_intent_keys.items,
        });
        if (pending_identity_visibility_summary) |summary| {
            self.identity_visibility_summary_cache = summary;
        }
    }

    pub fn abortTransaction(self: *DB, txn_id: transactions_mod.TxnId, timestamp_ns: u64) !void {
        try self.resolveTransactionIntents(txn_id, .aborted, timestamp_ns);
    }

    pub fn getTransactionStatus(self: *DB, txn_id: transactions_mod.TxnId) !transactions_mod.TxnStatus {
        return try self.core.getTransactionStatus(txn_id);
    }

    pub fn getCommitVersion(self: *DB, txn_id: transactions_mod.TxnId) !u64 {
        return try self.core.getCommitVersion(txn_id);
    }

    pub fn markTransactionParticipantResolved(self: *DB, txn_id: transactions_mod.TxnId, participant: []const u8) !void {
        lockApply(self);
        defer self.core.unlockApply();
        try self.core.markTransactionParticipantResolved(txn_id, participant);
    }

    pub fn getTransactionParticipants(self: *DB, alloc: Allocator, txn_id: transactions_mod.TxnId) ![][]u8 {
        return try self.core.getTransactionParticipants(alloc, txn_id);
    }

    pub fn getUnresolvedTransactionParticipants(self: *DB, alloc: Allocator, txn_id: transactions_mod.TxnId) ![][]u8 {
        return try self.core.getUnresolvedTransactionParticipants(alloc, txn_id);
    }

    pub fn recoverTransactions(self: *DB, cutoff_timestamp: u64, resolution_timestamp: u64) !transactions_mod.RecoveryStats {
        lockApply(self);
        defer self.core.unlockApply();
        return try self.core.recoverTransactions(cutoff_timestamp, resolution_timestamp);
    }

    pub fn getEdges(
        self: *DB,
        alloc: Allocator,
        index_name: []const u8,
        key: []const u8,
        edge_type: []const u8,
        direction: graph_mod.EdgeDirection,
    ) ![]graph_mod.Edge {
        if (key.len == 0) return try alloc.alloc(graph_mod.Edge, 0);
        return try self.core.graphGetEdges(alloc, index_name, key, edge_type, direction);
    }

    pub fn traverseEdges(
        self: *DB,
        alloc: Allocator,
        index_name: []const u8,
        start_key: []const u8,
        rules: traversal_mod.TraversalRules,
    ) ![]traversal_mod.TraversalResult {
        if (start_key.len == 0) return try alloc.alloc(traversal_mod.TraversalResult, 0);
        return try self.core.graphTraverseEdges(alloc, index_name, start_key, rules);
    }

    pub fn getNeighbors(
        self: *DB,
        alloc: Allocator,
        index_name: []const u8,
        key: []const u8,
        edge_type: []const u8,
        direction: graph_mod.EdgeDirection,
    ) ![]traversal_mod.TraversalResult {
        var edge_types_storage: [1][]const u8 = undefined;
        const edge_types = if (edge_type.len > 0) blk: {
            edge_types_storage[0] = edge_type;
            break :blk edge_types_storage[0..1];
        } else &.{};
        return try self.traverseEdges(alloc, index_name, key, .{
            .edge_types = edge_types,
            .direction = direction,
            .max_depth = 1,
        });
    }

    pub fn findShortestPath(
        self: *DB,
        alloc: Allocator,
        index_name: []const u8,
        source: []const u8,
        target: []const u8,
        edge_types: []const []const u8,
        direction: graph_mod.EdgeDirection,
        weight_mode: paths_mod.PathWeightMode,
        max_depth: u32,
        min_weight: f64,
        max_weight: f64,
    ) !?paths_mod.Path {
        if (source.len == 0 or target.len == 0) return null;
        if (try self.findAlgebraicShortestPath(alloc, index_name, source, target, edge_types, direction, weight_mode, max_depth, min_weight, max_weight)) |path| {
            return path;
        }
        return try self.core.graphFindShortestPath(
            alloc,
            index_name,
            source,
            target,
            edge_types,
            direction,
            weight_mode,
            max_depth,
            min_weight,
            max_weight,
        );
    }

    pub fn findKShortestPaths(
        self: *DB,
        alloc: Allocator,
        index_name: []const u8,
        source: []const u8,
        target: []const u8,
        k: u32,
        edge_types: []const []const u8,
        direction: graph_mod.EdgeDirection,
        weight_mode: paths_mod.PathWeightMode,
        max_depth: u32,
        min_weight: f64,
        max_weight: f64,
    ) ![]paths_mod.Path {
        if (source.len == 0 or target.len == 0 or k == 0) return try alloc.alloc(paths_mod.Path, 0);
        if (k == 1) {
            if (try self.findShortestPath(alloc, index_name, source, target, edge_types, direction, weight_mode, max_depth, min_weight, max_weight)) |path| {
                const paths = try alloc.alloc(paths_mod.Path, 1);
                paths[0] = path;
                return paths;
            }
            return try alloc.alloc(paths_mod.Path, 0);
        }
        return try self.core.graphFindKShortestPaths(
            alloc,
            index_name,
            source,
            target,
            k,
            edge_types,
            direction,
            weight_mode,
            max_depth,
            min_weight,
            max_weight,
        );
    }

    fn findAlgebraicShortestPath(
        self: *DB,
        alloc: Allocator,
        index_name: []const u8,
        source: []const u8,
        target: []const u8,
        edge_types: []const []const u8,
        direction: graph_mod.EdgeDirection,
        weight_mode: paths_mod.PathWeightMode,
        max_depth: u32,
        min_weight: f64,
        max_weight: f64,
    ) !?paths_mod.Path {
        const entry = self.core.index_manager.graphIndex(index_name) orelse return error.IndexNotFound;
        const params = graph_query_mod.QueryParams{
            .edge_types = edge_types,
            .direction = direction,
            .max_depth = max_depth,
            .max_results = 0,
            .min_weight = min_weight,
            .max_weight = max_weight,
            .deduplicate = true,
            .include_paths = false,
            .weight_mode = weight_mode,
        };
        if (!(graph_query_mod.algebraicTraversalProof(&entry.index, params).safe())) return null;
        try self.proveGraphTraversalProgram(index_name, true);

        var graph_engine = graph_query_mod.GraphQueryEngine{ .alloc = alloc };
        var result = try graph_engine.execute(&entry.index, .{
            .query_type = .shortest_path,
            .index_name = index_name,
            .start_nodes = .{ .keys = &.{source} },
            .target_nodes = .{ .keys = &.{target} },
            .params = params,
        }, &.{source});
        defer result.deinit(alloc);
        if (result.nodes.len == 0) return null;
        return try graphResultNodePathAlloc(alloc, result.nodes[0]);
    }

    fn graphResultNodePathAlloc(alloc: Allocator, node: graph_query_mod.GraphResultNode) !?paths_mod.Path {
        const node_path = node.path orelse return null;
        const edge_path = node.path_edges orelse return null;
        const nodes = try alloc.alloc([]const u8, node_path.len);
        var initialized_nodes: usize = 0;
        errdefer {
            for (nodes[0..initialized_nodes]) |item| alloc.free(item);
            alloc.free(nodes);
        }
        for (node_path, 0..) |item, i| {
            nodes[i] = try alloc.dupe(u8, item);
            initialized_nodes += 1;
        }

        const edges = try alloc.alloc(paths_mod.PathEdge, edge_path.len);
        var initialized_edges: usize = 0;
        errdefer {
            for (edges[0..initialized_edges]) |edge| {
                alloc.free(edge.source);
                alloc.free(edge.target);
                alloc.free(edge.edge_type);
            }
            alloc.free(edges);
        }
        var total_weight: f64 = 0;
        for (edge_path, 0..) |item, i| {
            edges[i] = .{
                .source = try alloc.dupe(u8, item.source),
                .target = try alloc.dupe(u8, item.target),
                .edge_type = try alloc.dupe(u8, item.edge_type),
                .weight = item.weight,
            };
            initialized_edges += 1;
            total_weight += item.weight;
        }

        return .{
            .nodes = nodes,
            .edges = edges,
            .total_weight = total_weight,
            .length = @intCast(edges.len),
        };
    }

    pub fn matchPattern(
        self: *DB,
        alloc: Allocator,
        index_name: []const u8,
        start_keys: []const []const u8,
        pattern: []const graph_pattern_mod.PatternStep,
        max_results: u32,
        return_aliases: []const []const u8,
    ) ![]graph_pattern_mod.PatternMatch {
        if (start_keys.len == 0) return try alloc.alloc(graph_pattern_mod.PatternMatch, 0);
        return try self.core.graphMatchPattern(alloc, index_name, start_keys, pattern, .{
            .max_results = max_results,
            .return_aliases = return_aliases,
            .evaluator = .{
                .ctx = self,
                .func = patternNodeFilterEvaluator,
            },
        });
    }

    fn graphInputSetHitsAlloc(
        self: *DB,
        alloc: Allocator,
        hit_ids: []const []const u8,
        generation: ?u64,
    ) ![]types.SearchHit {
        const hits = try alloc.alloc(types.SearchHit, hit_ids.len);
        var initialized: usize = 0;
        errdefer {
            for (hits[0..initialized]) |*hit| hit.deinit(alloc);
            if (hits.len > 0) alloc.free(hits);
        }
        for (hit_ids, 0..) |hit_id, j| {
            hits[j] = .{
                .id = try alloc.dupe(u8, hit_id),
                .doc_ordinal = try self.lookupLiveDocOrdinalNoLock(alloc, hit_id, generation),
                .score = null,
                .stored_data = null,
                .chunk_hits = &.{},
            };
            initialized += 1;
        }
        return hits;
    }

    pub fn executeNamedGraphQueries(
        self: *DB,
        alloc: Allocator,
        req: types.SearchRequest,
        graph_queries: []const types.NamedGraphQuery,
        input_sets: []const types.NamedGraphInputSet,
    ) ![]types.GraphSearchResult {
        lockApplyShared(self);
        defer self.core.unlockApplyShared();
        if (req.identity_read_generation == null) {
            for (input_sets) |input_set| {
                if (input_set.hit_ids.len > 0) return error.UnsupportedQueryRequest;
            }
        }
        const snapshot_req = try self.searchRequestAtCurrentIdentityGeneration(req);

        var named_sets = try alloc.alloc(NamedResultSet, input_sets.len);
        defer alloc.free(named_sets);
        var temp_hits = try alloc.alloc([]types.SearchHit, input_sets.len);
        defer alloc.free(temp_hits);
        var resolved_sets = try alloc.alloc(?doc_set.ResolvedDocSet, input_sets.len);
        defer {
            for (resolved_sets) |*maybe_set| {
                if (maybe_set.*) |*set| set.deinit(alloc);
            }
            if (resolved_sets.len > 0) alloc.free(resolved_sets);
        }
        @memset(resolved_sets, null);
        var initialized_sets: usize = 0;

        for (input_sets, 0..) |input_set, i| {
            resolved_sets[i] = try self.resolveDocSetForIdsNoLockAtGenerationAlloc(alloc, input_set.hit_ids, snapshot_req.identity_read_generation);
            temp_hits[i] = try self.graphInputSetHitsAlloc(alloc, input_set.hit_ids, snapshot_req.identity_read_generation);
            const resolved_doc_set = if (resolved_sets[i]) |*set| set else null;
            named_sets[i] = .{
                .name = input_set.name,
                .hits = temp_hits[i],
                .total_hits = if (input_set.total_hits > 0) input_set.total_hits else @intCast(input_set.hit_ids.len),
                .resolved_doc_set = resolved_doc_set,
                .resolved_doc_set_complete = input_set.total_hits == 0 or @as(u64, input_set.total_hits) <= input_set.hit_ids.len,
            };
            initialized_sets += 1;
        }
        defer {
            for (temp_hits[0..initialized_sets]) |hits| {
                for (hits) |*hit| hit.deinit(alloc);
                if (hits.len > 0) alloc.free(hits);
            }
        }

        return try self.executeGraphQueriesWithSets(alloc, snapshot_req, graph_queries, named_sets);
    }

    pub fn addIndex(self: *DB, cfg: types.IndexConfig) !void {
        lockApply(self);
        var apply_locked = true;
        errdefer if (apply_locked) self.core.unlockApply();
        const applied = try self.core.addIndex(cfg);
        try saveIndexStatusSnapshots(self.alloc, self.core.store, self.core.index_manager, &[_]apply_state.AppliedSequenceUpdate{.{
            .index_name = cfg.name,
            .sequence = applied,
        }});
        if (cfg.kind == .algebraic) {
            self.hydrateAlgebraicObservationStatusForIndexBestEffort(cfg.name);
        }
        const needs_enrichment_replay = try self.core.indexRequiresEnrichmentReplay(cfg.name);
        self.core.unlockApply();
        apply_locked = false;
        if (self.start_index_workers) {
            try self.executor.addWorker(cfg.name, .{ .name = cfg.name, .kind = cfg.kind }, applied);
        }
        if (needs_enrichment_replay) {
            if (self.enrichment_runtime != null) {
                const refs = try self.replayGeneratedEnrichmentsFromStoredDocs(self.alloc);
                if (refs == 0) try self.core.saveAppliedSequence(cfg.name, self.core.nextDerivedSequence());
            }
        }
    }

    pub fn addEnrichment(self: *DB, cfg: types.EnrichmentConfig) !void {
        lockApply(self);
        defer self.core.unlockApply();
        try self.core.addEnrichment(cfg);
    }

    pub fn addResolver(self: *DB, cfg: index_manager_mod.ResolverConfig) !void {
        {
            lockApply(self);
            defer self.core.unlockApply();
            try self.core.addResolver(cfg);
        }
        try self.startResolverReplayRuntimes();
        try self.backfillResolverCorpus();
    }

    pub const ResolverUpsertOptions = struct {
        /// When false, persist the catalog mutation and mark the resolver backlog
        /// dirty, but leave the actual re-resolution drain to the caller. Managed
        /// table opens use this so DB runtime hooks are installed before
        /// cross-shard candidate blocking or promotion can run.
        drain_backfill: bool = true,
    };

    /// Add or replace a resolver. Inserts and material config changes re-resolve
    /// the existing corpus so the new resolver/scorer behavior applies to
    /// documents already ingested (the extraction artifacts did not change, so
    /// the incremental hint would not fire on its own).
    pub fn upsertResolverWithResultOptions(
        self: *DB,
        cfg: index_manager_mod.ResolverConfig,
        options: ResolverUpsertOptions,
    ) !index_manager_mod.IndexManager.ResolverUpsertResult {
        const upsert_result = blk: {
            lockApply(self);
            defer self.core.unlockApply();
            break :blk try self.core.upsertResolver(cfg);
        };
        switch (upsert_result) {
            .inserted, .updated_backfill_required => {
                try self.startResolverReplayRuntimes();
                if (options.drain_backfill) {
                    try self.backfillResolverCorpus();
                } else if (self.resolution_runtime) |runtime| {
                    try runtime.requestReresolveBacklog();
                }
            },
            .updated_no_backfill => {
                try self.startResolverReplayRuntimesIfConfigured();
                if (options.drain_backfill and self.resolution_runtime != null) {
                    const runtime = self.resolution_runtime.?;
                    if (try runtime.hasReresolveBacklog()) {
                        try self.backfillResolverCorpus();
                    }
                }
            },
        }
        return upsert_result;
    }

    pub fn upsertResolverWithResult(self: *DB, cfg: index_manager_mod.ResolverConfig) !index_manager_mod.IndexManager.ResolverUpsertResult {
        return try self.upsertResolverWithResultOptions(cfg, .{});
    }

    pub fn upsertResolver(self: *DB, cfg: index_manager_mod.ResolverConfig) !void {
        _ = try self.upsertResolverWithResult(cfg);
    }

    pub fn drainResolverBackfill(self: *DB) !void {
        try self.startResolverReplayRuntimesIfConfigured();
        try self.backfillResolverCorpus();
    }

    fn backfillResolverCorpus(self: *DB) !void {
        if (!self.hasConfiguredResolvers()) return;
        if (self.resolution_runtime) |runtime| {
            try runtime.requestReresolveBacklog();
            while (true) {
                var tick = try runtime.runReresolveBacklogWindow();
                const queued = tick.queued;
                const complete = tick.complete;
                tick.deinit(self.runtime_alloc);
                // Drive the enqueued extraction artifacts through resolution,
                // promotion, and graph materialization before queuing more.
                if (queued > 0) try self.runUntilIdle();
                if (complete) break;
            }
        }
    }

    pub fn removeResolver(self: *DB, name: []const u8) !bool {
        try self.retireResolverReplayBeforeCatalogRemoval();

        const retirement_sequence = blk: {
            lockApply(self);
            defer self.core.unlockApply();

            const cfg = (try self.resolverConfigByNameAlloc(name)) orelse return false;
            defer {
                var owned = cfg;
                owned.deinit(self.alloc);
            }

            break :blk try self.retireResolverArtifactsLocked(cfg);
        };

        if (retirement_sequence) |sequence| {
            self.executor.notifySequence(sequence);
            self.notifyResolverReplayRuntimesForced(sequence);
            try self.runUntilIdle();
        }

        {
            lockApply(self);
            defer self.core.unlockApply();
            if (!try self.core.removeResolver(name)) return false;
        }

        self.stopResolverReplayRuntimesIfUnconfigured();
        return true;
    }

    fn resolverConfigByNameAlloc(self: *DB, name: []const u8) !?index_manager_mod.ResolverConfig {
        const resolvers = try self.core.listResolvers(self.alloc);
        defer {
            for (resolvers) |*cfg| cfg.deinit(self.alloc);
            if (resolvers.len > 0) self.alloc.free(resolvers);
        }
        for (resolvers) |cfg| {
            if (std.mem.eql(u8, cfg.name, name)) {
                return try index_manager_mod.ResolverConfig.clone(self.alloc, cfg);
            }
        }
        return null;
    }

    fn retireResolverArtifactsLocked(self: *DB, cfg: index_manager_mod.ResolverConfig) !?u64 {
        var deletes = std.ArrayListUnmanaged([]const u8).empty;
        defer {
            for (deletes.items) |key| self.alloc.free(@constCast(key));
            deletes.deinit(self.alloc);
        }
        var changed = std.ArrayListUnmanaged([]u8).empty;
        defer {
            for (changed.items) |key| self.alloc.free(key);
            changed.deinit(self.alloc);
        }

        const marker_prefix = try internal_keys.assetArtifactSourceIndexPrefixAlloc(self.alloc, cfg.source_artifact);
        defer self.alloc.free(marker_prefix);
        const markers = try self.core.store.scanPrefix(self.alloc, marker_prefix);
        defer docstore_mod.DocStore.freeResults(self.alloc, markers);

        for (markers) |marker| {
            const parsed = (try internal_keys.parseAssetArtifactKeyAlloc(self.alloc, marker.value)) orelse continue;
            defer {
                self.alloc.free(parsed.doc_key);
                self.alloc.free(parsed.artifact_name);
            }
            if (!std.mem.eql(u8, parsed.artifact_name, cfg.source_artifact)) continue;

            const resolution_key = try internal_keys.resolutionArtifactKeyAlloc(self.alloc, parsed.doc_key, cfg.resolution_artifact);
            var resolution_key_owned = true;
            errdefer if (resolution_key_owned) self.alloc.free(resolution_key);
            if (!containsDeleteKey(deletes.items, resolution_key)) {
                try deletes.append(self.alloc, resolution_key);
                resolution_key_owned = false;
                try appendUniqueOwnedKey(self.alloc, &changed, resolution_key);
            } else {
                self.alloc.free(resolution_key);
                resolution_key_owned = false;
            }

            try self.collectResolverMentionArtifactsForDocLocked(cfg, parsed.doc_key, &deletes, &changed);
        }

        if (deletes.items.len == 0 and changed.items.len == 0) return null;

        const sequence = self.core.reserveDerivedAppendSequence();
        const replay_payload = try encodeChangeRecordPayload(&self.batchContext(), .{
            .sequence = sequence,
            .changed_artifact_keys = changed.items,
        }, sequence);
        defer self.alloc.free(replay_payload);

        try self.core.store.putBatchWithReplay(self.backend_runtime.io(), &.{}, deletes.items, .{
            .sequence = sequence,
            .payload = replay_payload,
        });
        self.executor.trackBacklogBytes(sequence, @intCast(replay_payload.len)) catch {};
        return sequence;
    }

    fn collectResolverMentionArtifactsForDocLocked(
        self: *DB,
        cfg: index_manager_mod.ResolverConfig,
        doc_key: []const u8,
        deletes: *std.ArrayListUnmanaged([]const u8),
        changed: *std.ArrayListUnmanaged([]u8),
    ) !void {
        for (self.core.graphIndexes()) |graph_entry| {
            const source = graph_entry.artifact_source orelse continue;
            if (source.mention_edge_type.len == 0) continue;
            if (!std.mem.eql(u8, source.artifact_name, cfg.source_artifact)) continue;

            const state_name = try mentionGraphStateNameAlloc(self.alloc, cfg.source_artifact, cfg.resolution_artifact);
            defer self.alloc.free(state_name);
            const state_key = try graphAssetStateKeyAlloc(self.alloc, doc_key, graph_entry.config.name, state_name);
            var state_key_owned = true;
            errdefer if (state_key_owned) self.alloc.free(state_key);

            if (try loadGraphAssetStateKeysAlloc(self.alloc, self.core.store, state_key)) |previous_keys| {
                defer freeOwnedConstKeySlice(self.alloc, previous_keys);
                for (previous_keys) |previous_key| {
                    if (containsDeleteKey(deletes.items, previous_key)) continue;
                    const owned_key = try self.alloc.dupe(u8, previous_key);
                    try deletes.append(self.alloc, owned_key);
                    try appendUniqueOwnedKey(self.alloc, changed, previous_key);
                }
            }

            if (!containsDeleteKey(deletes.items, state_key)) {
                try deletes.append(self.alloc, state_key);
                state_key_owned = false;
            } else {
                self.alloc.free(state_key);
                state_key_owned = false;
            }
        }
    }

    fn retireResolverReplayBeforeCatalogRemoval(self: *DB) !void {
        try self.runUntilIdle();
        const resolution_stats = self.resolutionStageStats();
        if (resolution_stats.catch_up_required or resolution_stats.blocked) return error.ResolverReplayPending;
        const promotion_stats = self.promotionStageStats();
        if (promotion_stats.catch_up_required or promotion_stats.blocked) return error.ResolverReplayPending;
    }

    /// The review queue: review-band mentions awaiting human curation. Empty
    /// when no resolution runtime is active. Caller owns the result
    /// (`resolution_runtime_mod.freePendingReviews`).
    pub fn listPendingReviews(self: *DB, alloc: Allocator) ![]resolution_runtime_mod.PendingReview {
        const runtime = self.resolution_runtime orelse return try alloc.alloc(resolution_runtime_mod.PendingReview, 0);
        return try runtime.pendingReviews(alloc);
    }

    /// Persist a human curation decision for one review-band mention and enqueue
    /// the document for ordinary replay-driven resolution/promotion.
    pub fn recordReviewDecision(
        self: *DB,
        doc_key: []const u8,
        source_artifact: []const u8,
        resolution_artifact: []const u8,
        local_id: []const u8,
        decision: resolver_lib.Decision,
        table: []const u8,
        key: []const u8,
    ) !u64 {
        if (openModeRequiresReadOnlyBackends(self.open_mode)) return error.ReadOnly;
        try self.executor.failIfUnhealthy();

        lockApply(self);
        var apply_mutex_held = true;
        errdefer if (apply_mutex_held) self.core.unlockApply();

        const resolvers = try self.core.listResolvers(self.alloc);
        defer {
            for (resolvers) |*cfg| cfg.deinit(self.alloc);
            if (resolvers.len > 0) self.alloc.free(resolvers);
        }
        for (resolvers) |cfg| {
            if (std.mem.eql(u8, cfg.source_artifact, source_artifact) and
                std.mem.eql(u8, cfg.resolution_artifact, resolution_artifact))
            {
                break;
            }
        } else return error.ResolverNotFound;

        const override_key = try resolution_runtime_mod.reviewOverrideArtifactKeyAlloc(self.alloc, doc_key, source_artifact, resolution_artifact);
        defer self.alloc.free(override_key);
        const existing = self.core.store.get(self.alloc, override_key) catch |err| switch (err) {
            error.NotFound => null,
            else => return err,
        };
        defer if (existing) |raw| self.alloc.free(raw);
        const override_bytes = try resolution_runtime_mod.buildReviewDecisionBytesAlloc(self.alloc, existing, local_id, decision, table, key);
        defer self.alloc.free(override_bytes);

        const source_key = try internal_keys.artifactNamedPrefixAlloc(self.alloc, doc_key, "asset", source_artifact);
        defer self.alloc.free(source_key);
        const sequence = self.core.reserveDerivedAppendSequence();
        const changed_artifact_keys = [_][]const u8{source_key};
        const replay_payload = try encodeChangeRecordPayload(&self.batchContext(), .{
            .sequence = sequence,
            .changed_artifact_keys = changed_artifact_keys[0..],
        }, sequence);
        defer self.alloc.free(replay_payload);

        const writes = [_]docstore_mod.KVPair{.{
            .key = override_key,
            .value = override_bytes,
        }};
        try self.core.store.putBatchWithReplay(self.backend_runtime.io(), writes[0..], &.{}, .{
            .sequence = sequence,
            .payload = replay_payload,
        });
        self.executor.trackBacklogBytes(sequence, @intCast(replay_payload.len)) catch {};
        self.core.unlockApply();
        apply_mutex_held = false;

        if (self.executor.hasWorkers()) {
            self.executor.forceSequence(sequence);
        } else {
            self.executor.notifySequence(sequence);
        }
        self.notifyResolverReplayRuntimes(sequence);
        return sequence;
    }

    /// Eager edge rewrite for an entity merge: repoint every inbound edge of
    /// `old_key` (the merged-away entity) at `new_key` (the survivor) in the
    /// given graph index, preserving edge type, weight, and metadata. Already
    /// materialized provenance mention edges do not follow `merged_into` on their
    /// own; this brings the graph in line with a merge.
    /// Returns the number of edges rewritten.
    pub fn rewriteEntityEdges(
        self: *DB,
        alloc: Allocator,
        index_name: []const u8,
        old_key: []const u8,
        new_key: []const u8,
    ) !usize {
        if (std.mem.eql(u8, old_key, new_key)) return 0;
        const inbound = try self.getEdges(alloc, index_name, old_key, "", .in);
        defer graph_mod.GraphIndex.freeEdges(alloc, inbound);
        if (inbound.len == 0) return 0;

        var writes = try alloc.alloc(types.GraphEdgeWrite, inbound.len);
        defer alloc.free(writes);
        var deletes = try alloc.alloc(types.GraphEdgeDelete, inbound.len);
        defer alloc.free(deletes);
        for (inbound, 0..) |edge, i| {
            deletes[i] = .{ .index_name = index_name, .source = edge.source, .target = old_key, .edge_type = edge.edge_type };
            writes[i] = .{
                .index_name = index_name,
                .source = edge.source,
                .target = new_key,
                .edge_type = edge.edge_type,
                .weight = edge.weight,
                .created_at = edge.created_at,
                .updated_at = edge.updated_at,
                .metadata_json = edge.metadata,
            };
        }
        try self.batch(.{ .graph_writes = writes, .graph_deletes = deletes, .sync_level = .write });
        return inbound.len;
    }

    pub fn hasIndex(self: *DB, name: []const u8) bool {
