    fn relationalRowsDocKeyInQueryRange(req: types.RelationalRowsQueryRequest, doc_key: []const u8) bool {
        const range = req.doc_key_range orelse return true;
        if (range.start.len > 0 and std.mem.order(u8, doc_key, range.start) == .lt) return false;
        if (range.end.len > 0 and std.mem.order(u8, doc_key, range.end) != .lt) return false;
        return true;
    }

    fn relationalRowsQueryJsonMatchesRequest(
        alloc: Allocator,
        row_json: []const u8,
        req: types.RelationalRowsQueryRequest,
    ) !bool {
        if (req.predicates.len == 0 and req.array_any.len == 0 and req.array_contains.len == 0 and req.array_eq.len == 0 and req.in_predicates.len == 0 and req.json_contains.len == 0 and req.json_path_eq.len == 0 and req.json_path_exists.len == 0 and req.text_patterns.len == 0 and req.or_predicates.len == 0 and req.not_predicates.len == 0 and req.access_or_predicates.len == 0 and req.access_not_predicates.len == 0 and req.expression_predicates.len == 0 and req.expression_or_predicates.len == 0 and req.expression_not_predicates.len == 0 and req.expression_array_contains.len == 0) return true;
        var parsed = std.json.parseFromSlice(std.json.Value, alloc, row_json, .{}) catch return error.InvalidQueryRequest;
        defer parsed.deinit();
        if (parsed.value != .object) return error.InvalidQueryRequest;
        for (req.predicates) |predicate| {
            if (!(try relationalRowsQueryPredicatePasses(alloc, parsed.value, predicate))) return false;
        }
        if (!(try relationalRowsQueryOrPredicateGroupsPass(alloc, parsed.value, req.or_predicates))) return false;
        if (!(try relationalRowsQueryNotPredicateGroupsPass(alloc, parsed.value, req.not_predicates))) return false;
        if (!(try relationalRowsQueryAccessOrPredicateGroupsPass(alloc, parsed.value, req.access_or_predicates))) return false;
        if (!(try relationalRowsQueryAccessNotPredicateGroupsPass(alloc, parsed.value, req.access_not_predicates))) return false;
        for (req.expression_predicates) |condition| {
            if (!(try relationalRowsExpressionConditionMatches(alloc, parsed.value, condition))) return false;
        }
        if (!(try relationalRowsQueryExpressionOrPredicateGroupsPass(alloc, parsed.value, req.expression_or_predicates))) return false;
        if (!(try relationalRowsQueryExpressionNotPredicateGroupsPass(alloc, parsed.value, req.expression_not_predicates))) return false;
        for (req.expression_array_contains) |predicate| {
            if (!(try relationalRowsQueryExpressionArrayContainsPredicatePasses(alloc, parsed.value, predicate))) return false;
        }
        for (req.array_any) |predicate| {
            if (!(try relationalRowsQueryArrayAnyPredicatePasses(alloc, parsed.value, predicate))) return false;
        }
        for (req.array_contains) |predicate| {
            if (!(try relationalRowsQueryArrayContainsPredicatePasses(alloc, parsed.value, predicate))) return false;
        }
        for (req.array_eq) |predicate| {
            if (!(try relationalRowsQueryArrayEqPredicatePasses(alloc, parsed.value, predicate))) return false;
        }
        for (req.in_predicates) |predicate| {
            if (!(try relationalRowsQueryInPredicatePasses(alloc, parsed.value, predicate))) return false;
        }
        for (req.json_contains) |predicate| {
            if (!(try relationalRowsQueryJsonContainsPredicatePasses(alloc, parsed.value, predicate))) return false;
        }
        for (req.json_path_eq) |predicate| {
            if (!(try relationalRowsQueryJsonPathEqPredicatePasses(alloc, parsed.value, predicate))) return false;
        }
        for (req.json_path_exists) |predicate| {
            if (!relationalRowsQueryJsonPathExistsPredicatePasses(parsed.value, predicate)) return false;
        }
        for (req.text_patterns) |predicate| {
            if (!relationalRowsQueryTextPatternPredicatePasses(parsed.value, predicate)) return false;
        }
        return true;
    }

    fn relationalRowsQueryTextPatternPredicatePasses(
        row: std.json.Value,
        predicate: types.RelationalRowsTextPatternPredicate,
    ) bool {
        const actual = relationalRowsJsonValueAtPath(row, predicate.field) orelse return predicate.negated;
        if (actual.* != .string) return predicate.negated;
        const matched = relationalRowsSqlLikePatternMatches(actual.string, predicate.pattern, predicate.case_insensitive);
        return if (predicate.negated) !matched else matched;
    }

    fn relationalRowsSqlLikePatternMatches(text: []const u8, pattern: []const u8, case_insensitive: bool) bool {
        return relationalRowsSqlLikePatternMatchesFrom(text, pattern, case_insensitive, 0, 0);
    }

    fn relationalRowsSqlLikePatternMatchesFrom(
        text: []const u8,
        pattern: []const u8,
        case_insensitive: bool,
        text_index: usize,
        pattern_index: usize,
    ) bool {
        var ti = text_index;
        var pi = pattern_index;
        while (pi < pattern.len) {
            const token = pattern[pi];
            if (token == '%') {
                while (pi < pattern.len and pattern[pi] == '%') pi += 1;
                if (pi == pattern.len) return true;
                var next_ti = ti;
                while (next_ti <= text.len) : (next_ti += 1) {
                    if (relationalRowsSqlLikePatternMatchesFrom(text, pattern, case_insensitive, next_ti, pi)) return true;
                }
                return false;
            }
            if (ti >= text.len) return false;
            if (token == '_') {
                ti += 1;
                pi += 1;
                continue;
            }
            if (token == '\\' and pi + 1 < pattern.len) {
                pi += 1;
            }
            if (!relationalRowsSqlLikeBytesEqual(text[ti], pattern[pi], case_insensitive)) return false;
            ti += 1;
            pi += 1;
        }
        return ti == text.len;
    }

    fn relationalRowsSqlLikeBytesEqual(lhs: u8, rhs: u8, case_insensitive: bool) bool {
        if (!case_insensitive) return lhs == rhs;
        return std.ascii.toLower(lhs) == std.ascii.toLower(rhs);
    }

    fn relationalRowsQueryPredicatePasses(
        alloc: Allocator,
        row: std.json.Value,
        predicate: schema_mod.RelationalCheck,
    ) !bool {
        const value = relationalRowsJsonValueAtPath(row, predicate.field);
        return switch (predicate.op) {
            .is_null => value == null or value.?.* == .null,
            .is_not_null => value != null and value.?.* != .null,
            .is_distinct, .is_not_distinct => blk: {
                const expected_json = predicate.value_json orelse return error.InvalidQueryRequest;
                var expected = std.json.parseFromSlice(std.json.Value, alloc, expected_json, .{}) catch return error.InvalidQueryRequest;
                defer expected.deinit();
                const actual: std.json.Value = if (value) |selected| selected.* else .null;
                const not_distinct = relationalRowsJsonValuesNotDistinct(actual, expected.value) orelse return error.InvalidQueryRequest;
                break :blk if (predicate.op == .is_not_distinct) not_distinct else !not_distinct;
            },
            .eq, .ne, .gt, .gte, .lt, .lte => blk: {
                const expected_json = predicate.value_json orelse return error.InvalidQueryRequest;
                var expected = std.json.parseFromSlice(std.json.Value, alloc, expected_json, .{}) catch return error.InvalidQueryRequest;
                defer expected.deinit();
                const actual = value orelse break :blk false;
                const comparison = compareRelationalRowsJsonScalars(actual.*, expected.value) orelse return error.InvalidQueryRequest;
                break :blk switch (predicate.op) {
                    .eq => comparison == .eq,
                    .ne => comparison != .eq,
                    .gt => comparison == .gt,
                    .gte => comparison == .gt or comparison == .eq,
                    .lt => comparison == .lt,
                    .lte => comparison == .lt or comparison == .eq,
                    else => unreachable,
                };
            },
        };
    }

    fn relationalRowsQueryOrPredicateGroupsPass(
        alloc: Allocator,
        row: std.json.Value,
        groups: []const types.RelationalRowsPredicateGroup,
    ) !bool {
        if (groups.len == 0) return true;
        for (groups) |group| {
            var group_passes = true;
            for (group.predicates) |predicate| {
                if (!(try relationalRowsQueryPredicatePasses(alloc, row, predicate))) {
                    group_passes = false;
                    break;
                }
            }
            if (group_passes) return true;
        }
        return false;
    }

    fn relationalRowsQueryNotPredicateGroupsPass(
        alloc: Allocator,
        row: std.json.Value,
        groups: []const types.RelationalRowsPredicateGroup,
    ) !bool {
        for (groups) |group| {
            var group_passes = true;
            for (group.predicates) |predicate| {
                if (!(try relationalRowsQueryPredicatePasses(alloc, row, predicate))) {
                    group_passes = false;
                    break;
                }
            }
            if (group_passes) return false;
        }
        return true;
    }

    fn relationalRowsQueryAccessPredicateGroupPasses(
        alloc: Allocator,
        row: std.json.Value,
        group: types.RelationalRowsAccessPredicateGroup,
    ) !bool {
        for (group.predicates) |predicate| {
            if (!(try relationalRowsQueryPredicatePasses(alloc, row, predicate))) return false;
        }
        for (group.array_any) |predicate| {
            if (!(try relationalRowsQueryArrayAnyPredicatePasses(alloc, row, predicate))) return false;
        }
        for (group.array_contains) |predicate| {
            if (!(try relationalRowsQueryArrayContainsPredicatePasses(alloc, row, predicate))) return false;
        }
        for (group.array_eq) |predicate| {
            if (!(try relationalRowsQueryArrayEqPredicatePasses(alloc, row, predicate))) return false;
        }
        for (group.in_predicates) |predicate| {
            if (!(try relationalRowsQueryInPredicatePasses(alloc, row, predicate))) return false;
        }
        for (group.json_contains) |predicate| {
            if (!(try relationalRowsQueryJsonContainsPredicatePasses(alloc, row, predicate))) return false;
        }
        for (group.json_path_eq) |predicate| {
            if (!(try relationalRowsQueryJsonPathEqPredicatePasses(alloc, row, predicate))) return false;
        }
        for (group.json_path_exists) |predicate| {
            if (!relationalRowsQueryJsonPathExistsPredicatePasses(row, predicate)) return false;
        }
        for (group.text_patterns) |predicate| {
            if (!relationalRowsQueryTextPatternPredicatePasses(row, predicate)) return false;
        }
        return true;
    }

    fn relationalRowsQueryAccessOrPredicateGroupsPass(
        alloc: Allocator,
        row: std.json.Value,
        groups: []const types.RelationalRowsAccessPredicateGroup,
    ) !bool {
        if (groups.len == 0) return true;
        for (groups) |group| {
            if (try relationalRowsQueryAccessPredicateGroupPasses(alloc, row, group)) return true;
        }
        return false;
