    fn relationalRowsQueryExpressionArrayContainsPredicatePassesWithSources(
        alloc: Allocator,
        row: std.json.Value,
        proposed_row: ?std.json.Value,
        source_row: ?std.json.Value,
        predicate: types.RelationalRowsExpressionArrayContainsPredicate,
