    }

    fn sortRelationalRowsOutputRowsAlloc(
        alloc: Allocator,
        rows: [][]const u8,
        order_by: []const types.RelationalRowsQueryOrder,
    ) !void {
        if (order_by.len == 0 or rows.len <= 1) return;

        const candidates = try alloc.alloc(RelationalRowsOutputRowOrderCandidate, rows.len);
        var initialized: usize = 0;
        defer {
            for (candidates[0..initialized]) |*candidate| candidate.deinit(alloc);
            alloc.free(candidates);
        }
        for (rows, 0..) |row_json, i| {
            var parsed = std.json.parseFromSlice(std.json.Value, alloc, row_json, .{}) catch return error.InvalidQueryRequest;
            defer parsed.deinit();
            if (parsed.value != .object) return error.InvalidQueryRequest;
            candidates[i] = .{
                .index = i,
                .order_keys = try relationalRowsQueryOrderKeysAlloc(alloc, parsed.value, order_by),
                .ordinal = i,
            };
            initialized += 1;
        }
        std.sort.pdq(RelationalRowsOutputRowOrderCandidate, candidates, RelationalRowsQuerySortContext{ .order_by = order_by }, relationalRowsOutputRowOrderCandidateLessThan);

        const ordered = try alloc.alloc([]const u8, rows.len);
        defer alloc.free(ordered);
        for (candidates, 0..) |candidate, i| ordered[i] = rows[candidate.index];
        @memcpy(rows, ordered);
    }

    fn relationalRowsOutputRowOrderCandidateLessThan(ctx: RelationalRowsQuerySortContext, lhs: RelationalRowsOutputRowOrderCandidate, rhs: RelationalRowsOutputRowOrderCandidate) bool {
        for (ctx.order_by, 0..) |order, i| {
            const comparison = compareRelationalRowsQueryOrderKeys(lhs.order_keys[i], rhs.order_keys[i]);
            if (comparison == .eq) continue;
            return switch (order.direction) {
                .asc => comparison == .lt,
                .desc => comparison == .gt,
            };
        }
        return lhs.ordinal < rhs.ordinal;
    }

    fn relationalRowsQueryCandidateLessThan(ctx: RelationalRowsQuerySortContext, lhs: RelationalRowsQueryCandidate, rhs: RelationalRowsQueryCandidate) bool {
        return relationalRowsQueryOrderedCandidatesLessThan(ctx.order_by, lhs.order_keys, lhs.ordinal, rhs.order_keys, rhs.ordinal);
    }

    fn relationalRowsQueryOrderedCandidatesLessThan(
        order_by: []const types.RelationalRowsQueryOrder,
        lhs_order_keys: []const RelationalRowsQueryOrderKey,
        lhs_ordinal: usize,
        rhs_order_keys: []const RelationalRowsQueryOrderKey,
        rhs_ordinal: usize,
    ) bool {
        for (order_by, 0..) |order, i| {
            const comparison = compareRelationalRowsQueryOrderKeys(lhs_order_keys[i], rhs_order_keys[i]);
            if (comparison == .eq) continue;
            return switch (order.direction) {
                .asc => comparison == .lt,
                .desc => comparison == .gt,
            };
        }
        return lhs_ordinal < rhs_ordinal;
    }

    fn compareRelationalRowsQueryOrderKeys(lhs: RelationalRowsQueryOrderKey, rhs: RelationalRowsQueryOrderKey) RelationalRowsScalarComparison {
        const left_rank = relationalRowsQueryOrderKeyRank(lhs);
        const right_rank = relationalRowsQueryOrderKeyRank(rhs);
        if (left_rank != right_rank) return if (left_rank < right_rank) .lt else .gt;
        return switch (lhs) {
            .missing, .null => .eq,
            .bool => |left| blk: {
                const right = rhs.bool;
                if (left == right) break :blk .eq;
                break :blk if (!left and right) .lt else .gt;
            },
            .number => |left| blk: {
                const right = rhs.number;
                if (left < right) break :blk .lt;
                if (left > right) break :blk .gt;
                break :blk .eq;
            },
            .string => |left| switch (std.mem.order(u8, left, rhs.string)) {
                .lt => .lt,
                .eq => .eq,
                .gt => .gt,
            },
        };
    }

    fn relationalRowsQueryOrderKeysEqual(lhs: []const RelationalRowsQueryOrderKey, rhs: []const RelationalRowsQueryOrderKey) bool {
        if (lhs.len != rhs.len) return false;
        for (lhs, rhs) |left, right| {
            if (compareRelationalRowsQueryOrderKeys(left, right) != .eq) return false;
        }
        return true;
    }

    fn relationalRowsQueryOrderKeyRank(key: RelationalRowsQueryOrderKey) u8 {
        return switch (key) {
            .bool => 0,
            .number => 1,
            .string => 2,
            .null => 3,
            .missing => 4,
        };
    }

    const RelationalRowsScalarComparison = enum { lt, eq, gt };

    fn relationalRowsJsonValuesNotDistinct(actual: std.json.Value, expected: std.json.Value) ?bool {
        const comparison = compareRelationalRowsJsonScalars(actual, expected) orelse return null;
        return comparison == .eq;
    }

    fn compareRelationalRowsJsonScalars(actual: std.json.Value, expected: std.json.Value) ?RelationalRowsScalarComparison {
        if (jsonNumberAsF64(actual)) |left| {
            const right = jsonNumberAsF64(expected) orelse return null;
            if (left < right) return .lt;
            if (left > right) return .gt;
            return .eq;
        }
        if (actual == .string and expected == .string) {
            return switch (std.mem.order(u8, actual.string, expected.string)) {
                .lt => .lt,
                .eq => .eq,
                .gt => .gt,
            };
        }
        if (actual == .bool and expected == .bool) {
            if (actual.bool == expected.bool) return .eq;
            return if (!actual.bool and expected.bool) .lt else .gt;
        }
        if (actual == .null and expected == .null) return .eq;
        return null;
    }

    fn jsonNumberAsF64(value: std.json.Value) ?f64 {
        return switch (value) {
            .integer => |integer| @floatFromInt(integer),
            .float => |float| float,
            .number_string => |text| std.fmt.parseFloat(f64, text) catch null,
            else => null,
        };
    }

    fn jsonNumberAsU64(value: std.json.Value) ?u64 {
        return switch (value) {
            .integer => |integer| if (integer >= 0) @intCast(integer) else null,
            else => null,
        };
    }

    fn jsonNumberAsI64(value: std.json.Value) ?i64 {
        return switch (value) {
            .integer => |integer| integer,
            .number_string => |text| std.fmt.parseInt(i64, text, 10) catch null,
            else => null,
        };
    }

    fn relationalRowsJsonValueAtPath(root: std.json.Value, path: []const u8) ?*const std.json.Value {
        if (root != .object) return null;
        var current: *const std.json.Value = &root;
        var parts = std.mem.splitScalar(u8, path, '.');
        while (parts.next()) |part| {
            if (part.len == 0 or current.* != .object) return null;
            current = current.object.getPtr(part) orelse return null;
        }
        return current;
    }

    fn freeRelationalRowsQueryOrderKeys(alloc: Allocator, keys: []const RelationalRowsQueryOrderKey) void {
        for (keys) |key| switch (key) {
            .string => |text| alloc.free(text),
            else => {},
        };
    }

    fn freeRelationalRowsQueryOrderKeySlice(alloc: Allocator, keys: []const RelationalRowsQueryOrderKey) void {
        freeRelationalRowsQueryOrderKeys(alloc, keys);
        if (keys.len > 0) alloc.free(keys);
    }

    pub fn search(self: *DB, alloc: Allocator, req: types.SearchRequest) !types.SearchResult {
        return try self.searchWithExecutionContext(alloc, req, .{});
    }

    pub fn searchWithExecutionContext(
        self: *DB,
        alloc: Allocator,
        req: types.SearchRequest,
        exec_ctx: types.ExecutionContext,
    ) !types.SearchResult {
        if (req.row_claim != null) {
            return try self.searchWithRowClaim(alloc, req, exec_ctx);
        }
        const bench_profile = benchQueryProfileEnabled();
        const total_start_ns = if (bench_profile) platform_time.monotonicNs() else 0;
        var generation_ns: u64 = 0;
        var lock_wait_ns: u64 = 0;
        var locked_search_ns: u64 = 0;
        if (self.canUsePublishedDenseSearch(req)) {
            const generation_start_ns = if (bench_profile) platform_time.monotonicNs() else 0;
            const snapshot_req = try self.searchRequestAtCurrentIdentityGeneration(req);
            if (bench_profile) generation_ns = platform_time.monotonicNs() - generation_start_ns;
            const search_start_ns = if (bench_profile) platform_time.monotonicNs() else 0;
            const result = try self.searchLockedWithExecutionContext(alloc, snapshot_req, exec_ctx);
            if (bench_profile) {
                locked_search_ns = platform_time.monotonicNs() - search_start_ns;
                std.log.info(
                    "antfly_bench_db_search_wrapper total_us={d} generation_us={d} lock_wait_us={d} locked_search_us={d} published_dense={}",
                    .{ (platform_time.monotonicNs() - total_start_ns) / 1000, generation_ns / 1000, lock_wait_ns / 1000, locked_search_ns / 1000, true },
                );
            }
            return result;
        }
        const lock_start_ns = if (bench_profile) platform_time.monotonicNs() else 0;
        lockApplyShared(self);
        if (bench_profile) lock_wait_ns = platform_time.monotonicNs() - lock_start_ns;
        defer self.core.unlockApplyShared();
        const generation_start_ns = if (bench_profile) platform_time.monotonicNs() else 0;
        const snapshot_req = try self.searchRequestAtCurrentIdentityGeneration(req);
        if (bench_profile) generation_ns = platform_time.monotonicNs() - generation_start_ns;
        const search_start_ns = if (bench_profile) platform_time.monotonicNs() else 0;
        const result = try self.searchLockedWithExecutionContext(alloc, snapshot_req, exec_ctx);
        if (bench_profile) {
            locked_search_ns = platform_time.monotonicNs() - search_start_ns;
            std.log.info(
                "antfly_bench_db_search_wrapper total_us={d} generation_us={d} lock_wait_us={d} locked_search_us={d} published_dense={}",
                .{ (platform_time.monotonicNs() - total_start_ns) / 1000, generation_ns / 1000, lock_wait_ns / 1000, locked_search_ns / 1000, false },
            );
        }
        return result;
    }

    fn searchWithRowClaim(
        self: *DB,
        alloc: Allocator,
        req: types.SearchRequest,
        exec_ctx: types.ExecutionContext,
    ) anyerror!types.SearchResult {
        const claim = req.row_claim orelse return error.InvalidQueryRequest;
        const txn_id = claim.txn_id orelse return error.InvalidQueryRequest;
        if (!claim.mode.isExclusiveWriteClaim()) return error.InvalidQueryRequest;
        if (req.count_only) return error.UnsupportedQueryRequest;
        if (req.return_mode != .parent) return error.UnsupportedQueryRequest;
        if (req.graph_queries.len > 0) return error.UnsupportedQueryRequest;
        if (req.graph_metric_queries.len > 0) return error.UnsupportedQueryRequest;

        var search_req = req;
        search_req.row_claim = null;
        var result = try self.searchWithExecutionContext(alloc, search_req, exec_ctx);
        errdefer result.deinit();
        try self.applyRowClaimToSearchResult(&result, txn_id, claim);
        return result;
    }

    fn applyRowClaimToSearchResult(
        self: *DB,
        result: *types.SearchResult,
        txn_id: types.TxnId,
        claim: types.RowClaimRequest,
    ) !void {
        if (result.graph_results.len > 0) return error.UnsupportedQueryRequest;
        if (!claim.effectiveSkipLocked()) {
            var row_keys = std.ArrayListUnmanaged([]const u8).empty;
            defer row_keys.deinit(self.alloc);
            for (result.hits) |hit| try row_keys.append(self.alloc, hit.id);
            try self.claimRowsForTransaction(txn_id, row_keys.items, claim);
            return;
        }

        var kept = std.ArrayListUnmanaged(types.SearchHit).empty;
        errdefer {
            for (kept.items) |*hit| hit.deinit(result.alloc);
            kept.deinit(result.alloc);
        }
        for (result.hits) |hit| {
            if (try self.tryClaimRowForTransaction(txn_id, hit.id, claim)) {
                try kept.append(result.alloc, try hit.clone(result.alloc));
            }
        }
        const old_hits = result.hits;
        result.hits = &.{};
        result.total_hits = 0;
        for (old_hits) |*hit| hit.deinit(result.alloc);
        if (old_hits.len > 0) result.alloc.free(old_hits);
        result.hits = try kept.toOwnedSlice(result.alloc);
        result.total_hits = @intCast(result.hits.len);
        result.total_hits_relation = .exact;
    }

    fn searchLocked(self: *DB, alloc: Allocator, req: types.SearchRequest) !types.SearchResult {
        return try self.searchLockedWithExecutionContext(alloc, try self.searchRequestAtCurrentIdentityGeneration(req), .{});
    }

    pub fn searchRequestAtCurrentIdentityGeneration(self: *DB, req: types.SearchRequest) !types.SearchRequest {
        var snapshot_req = req;
        snapshot_req.identity_read_generation = try self.currentIdentityReadGenerationForRequest(snapshot_req.identity_read_generation);
        try self.validateResolvedDocFilterWireContext(snapshot_req);
        return snapshot_req;
    }

    fn validateResolvedDocFilterWireContext(self: *DB, req: types.SearchRequest) !void {
        const ctx = req.resolved_doc_filter_wire_context orelse return;
        if (req.resolved_doc_filter == null) return error.InvalidQueryRequest;
        if (!ctx.namespace.eql(self.core.identity_namespace)) return error.DocIdentityNamespaceMismatch;
        if (req.identity_read_generation == null or req.identity_read_generation.? != ctx.identity_read_generation) {
            self.doc_set_planning_stats.recordStaleIdentityGenerationRejection();
            return error.UnsupportedQueryRequest;
        }
    }

    fn searchLockedWithExecutionContext(
        self: *DB,
        alloc: Allocator,
        req: types.SearchRequest,
        exec_ctx: types.ExecutionContext,
    ) !types.SearchResult {
        const execution_req = directSingleVectorRequest(req) orelse req;
        if (execution_req.full_text_queries.len > 0 or execution_req.dense_queries.len > 0 or execution_req.sparse_queries.len > 0 or execution_req.merge_config != null) {
            var composed = try self.searchComposed(alloc, execution_req, exec_ctx);
            errdefer composed.deinit();
            try self.applyGraphMetricRerank(&composed, execution_req);
            try externalizeSearchResultArtifactIds(alloc, &composed);
            return composed;
        }

        const has_primary = execution_req.full_text != null or execution_req.dense != null or execution_req.sparse != null or !db_query_search.isDefaultMatchAll(execution_req.query) or (execution_req.graph_queries.len == 0 and execution_req.graph_metric_queries.len == 0);

        var base = if (!has_primary and (execution_req.graph_queries.len > 0 or execution_req.graph_metric_queries.len > 0))
            try db_query_search.emptySearchResult(alloc)
        else if (execution_req.full_text) |text|
            try self.searchTextQuery(alloc, execution_req, text)
        else if (execution_req.dense) |dense|
            try self.searchDense(alloc, execution_req, dense)
        else if (execution_req.sparse) |sparse|
            try self.searchSparse(alloc, execution_req, sparse)
        else switch (execution_req.query) {
            .match_none,
            .match_all,
            .phrase,
            .multi_phrase,
            .term,
            .fuzzy,
            .numeric_range,
            .date_range,
            .doc_id,
            .bool_field,
            .geo_distance,
            .geo_bbox,
            .term_range,
            .ip_range,
            .geo_shape,
            .match,
            .match_phrase,
            .prefix,
            .wildcard,
            .regexp,
            => try self.searchText(alloc, execution_req),
            .dense_knn => |dense| try self.searchDense(alloc, execution_req, dense),
            .sparse_knn => |sparse| try self.searchSparse(alloc, execution_req, sparse),
            .graph => |graph| try self.searchGraph(alloc, execution_req, graph, null),
        };
        errdefer base.deinit();

        if (execution_req.graph_metric_queries.len > 0) {
            base.graph_metric_results = try self.executeGraphMetricQueries(alloc, execution_req.graph_metric_queries);
        }

        try self.applyGraphMetricRerank(&base, execution_req);

        if (execution_req.graph_queries.len == 0) {
            try externalizeSearchResultArtifactIds(alloc, &base);
            return base;
        }

        base.graph_results = try self.executeGraphQueries(alloc, execution_req, execution_req.graph_queries, base.hits, base.total_hits);
        try self.applyGraphExpandStrategy(alloc, &base, execution_req.expand_strategy);
        try externalizeSearchResultArtifactIds(alloc, &base);
        return base;
    }

    fn executeGraphMetricQueries(
        self: *DB,
        alloc: Allocator,
        queries: []const types.NamedGraphMetricQuery,
    ) ![]types.GraphMetricResult {
        if (queries.len == 0) return &.{};
        const results = try alloc.alloc(types.GraphMetricResult, queries.len);
        var initialized: usize = 0;
        errdefer {
            for (results[0..initialized]) |*result| result.deinit(alloc);
            alloc.free(results);
        }

        for (queries, 0..) |named, i| {
            results[i] = try self.executeGraphMetricQuery(alloc, named);
            initialized += 1;
        }
        return results;
    }

    fn applyGraphMetricRerank(
        self: *DB,
        result: *types.SearchResult,
        req: types.SearchRequest,
    ) !void {
        const rerank = req.graph_metric_rerank orelse return;
        if (req.count_only) return error.UnsupportedQueryRequest;

        const entry = self.core.graphIndex(rerank.index_name) orelse return error.IndexNotFound;
        var status = try entry.index.graphMetricStatus(rerank.metric_name);
        defer status.deinit(entry.index.alloc);

        if (status.published_generation == 0) return error.MetricNotReady;
        if (rerank.freshness == .fresh and status.state != .fresh) return error.MetricStale;

        var result_status = try cloneGraphMetricStatusFromGraph(result.alloc, status);
        var result_status_moved = false;
        errdefer if (!result_status_moved) result_status.deinit(result.alloc);

        for (result.hits) |*hit| {
            const metric_score_opt = try entry.index.graphMetricScore(rerank.metric_name, hit.id);
            const metric_score = metric_score_opt orelse rerank.missing_score;
            const base_score: f64 = if (hit.score) |score| @floatCast(score) else 0.0;
            const final_score = rerank.base_weight * base_score + rerank.weight * metric_score;
            const clamped_final_score = clampF64ToF32(final_score);
            const detail_index_name = try result.alloc.dupe(u8, rerank.index_name);
            errdefer result.alloc.free(detail_index_name);
            const detail_metric_name = try result.alloc.dupe(u8, rerank.metric_name);
            errdefer result.alloc.free(detail_metric_name);
            var score_details = types.GraphMetricRerankScoreDetails{
                .index_name = detail_index_name,
                .metric_name = detail_metric_name,
                .base_score = base_score,
                .base_weight = rerank.base_weight,
                .metric_score = metric_score_opt,
                .metric_score_used = metric_score,
                .metric_weight = rerank.weight,
                .missing_score_used = metric_score_opt == null,
                .final_score = clamped_final_score,
                .published_generation = status.published_generation,
            };
            var score_details_moved = false;
            errdefer if (!score_details_moved) score_details.deinit(result.alloc);

            if (hit.score_details) |*old_details| old_details.deinit(result.alloc);
            hit.score_details = score_details;
            score_details_moved = true;
            hit.score = clamped_final_score;
        }

        std.mem.sort(types.SearchHit, result.hits, {}, struct {
            fn lessThan(_: void, a: types.SearchHit, b: types.SearchHit) bool {
                const a_score = a.score orelse 0.0;
                const b_score = b.score orelse 0.0;
                if (a_score == b_score) return std.mem.lessThan(u8, a.id, b.id);
                return a_score > b_score;
            }
        }.lessThan);

        if (result.graph_metric_rerank_status) |*old_status| old_status.deinit(result.alloc);
        result.graph_metric_rerank_status = result_status;
        result_status_moved = true;
    }

    fn clampF64ToF32(value: f64) f32 {
        const max = std.math.floatMax(f32);
        if (value > max) return max;
        if (value < -max) return -max;
        return @floatCast(value);
    }

    fn executeGraphMetricQuery(
        self: *DB,
        alloc: Allocator,
        named: types.NamedGraphMetricQuery,
    ) !types.GraphMetricResult {
        const entry = self.core.graphIndex(named.query.index_name) orelse return error.IndexNotFound;
        var status = try entry.index.graphMetricStatus(named.query.metric_name);
        defer status.deinit(entry.index.alloc);

        if (status.published_generation == 0) return error.MetricNotReady;
        if (named.query.freshness == .fresh and status.state != .fresh) return error.MetricStale;

        const raw_scores = try entry.index.graphMetricTopK(named.query.metric_name, named.query.top_k);
        defer {
            for (raw_scores) |*score| score.deinit(entry.index.alloc);
            if (raw_scores.len > 0) entry.index.alloc.free(raw_scores);
        }

        const scores = try alloc.alloc(types.GraphMetricScore, raw_scores.len);
        var initialized_scores: usize = 0;
        errdefer {
            for (scores[0..initialized_scores]) |*score| score.deinit(alloc);
            alloc.free(scores);
        }
        for (raw_scores, 0..) |score, i| {
            scores[i] = .{
                .node = try alloc.dupe(u8, score.node),
                .score = score.score,
            };
            initialized_scores += 1;
        }

        const status_name = try alloc.dupe(u8, status.name);
        var status_name_moved = false;
        errdefer if (!status_name_moved) alloc.free(status_name);
        var status_edge_filter = try status.edge_filter.cloneAlloc(alloc);
        var status_edge_filter_moved = false;
        errdefer if (!status_edge_filter_moved) status_edge_filter.deinit(alloc);
        const status_recent_events = if (status.recent_events.len > 0)
            try alloc.dupe(graph_mod.GraphIndex.GraphMetricEvent, status.recent_events)
        else
            @constCast((&[_]graph_mod.GraphIndex.GraphMetricEvent{})[0..]);
        var status_recent_events_moved = false;
        errdefer if (!status_recent_events_moved and status_recent_events.len > 0) alloc.free(status_recent_events);
        const status_last_error = if (status.last_error.len > 0) try alloc.dupe(u8, status.last_error) else "";
        var status_last_error_moved = false;
        errdefer if (!status_last_error_moved and status_last_error.len > 0) alloc.free(status_last_error);
        const status_build_worker_id = if (status.build_worker_id.len > 0) try alloc.dupe(u8, status.build_worker_id) else "";
        var status_build_worker_id_moved = false;
        errdefer if (!status_build_worker_id_moved and status_build_worker_id.len > 0) alloc.free(status_build_worker_id);
        const status_build_cursor = if (status.build_cursor.len > 0) try alloc.dupe(u8, status.build_cursor) else "";
        var status_build_cursor_moved = false;
        errdefer if (!status_build_cursor_moved and status_build_cursor.len > 0) alloc.free(status_build_cursor);
        var result_status = types.GraphMetricStatus{
            .name = status_name,
            .state = status.state,
            .phase = status.phase,
            .edge_filter = status_edge_filter,
            .metadata_version = status.metadata_version,
            .maintenance_paused = status.maintenance_paused,
            .build_queued = status.build_queued,
            .published_generation = status.published_generation,
            .edge_generation = status.edge_generation,
            .target_edge_generation = status.target_edge_generation,
            .queued_generation = status.queued_generation,
            .building_generation = status.building_generation,
            .build_job_id = status.build_job_id,
            .build_started_at_ms = status.build_started_at_ms,
            .build_iteration = status.build_iteration,
            .build_lease_expires_at_ms = status.build_lease_expires_at_ms,
            .build_worker_id = status_build_worker_id,
            .build_cursor = status_build_cursor,
            .build_completed_units = status.build_completed_units,
            .build_total_units = status.build_total_units,
            .retry_count = status.retry_count,
            .last_error = status_last_error,
            .progress = status.progress,
            .converged = status.converged,
            .iterations_completed = status.iterations_completed,
            .delta = status.delta,
            .computed_at_ms = status.computed_at_ms,
            .last_event = status.last_event,
            .recent_events = status_recent_events,
        };
        status_name_moved = true;
        status_edge_filter_moved = true;
        status_recent_events_moved = true;
        status_last_error_moved = true;
        status_build_worker_id_moved = true;
        status_build_cursor_moved = true;
        errdefer result_status.deinit(alloc);

        return .{
            .name = try alloc.dupe(u8, named.name),
            .index_name = try alloc.dupe(u8, named.query.index_name),
            .metric_name = try alloc.dupe(u8, named.query.metric_name),
            .scores = scores,
            .status = result_status,
        };
    }

    fn directSingleVectorRequest(req: types.SearchRequest) ?types.SearchRequest {
        if (req.merge_config != null or req.reranker != null or req.pruner != null) return null;
        if (req.full_text_queries.len != 0) return null;
        if (req.full_text) |text| switch (text) {
            .match_all => {},
            else => return null,
        };
        if (!db_query_search.isDefaultMatchAll(req.query)) return null;
        if (req.graph_queries.len != 0 or req.graph_metric_queries.len != 0 or req.expand_strategy != null) return null;
        if (req.dense != null or req.sparse != null) return null;
        if (req.dense_queries.len == 1 and req.sparse_queries.len == 0) {
            var next = req;
            next.index_name = req.dense_queries[0].index_name;
            next.full_text = null;
            next.dense = req.dense_queries[0].query;
            next.dense_queries = &.{};
            return next;
        }
        if (req.sparse_queries.len == 1 and req.dense_queries.len == 0) {
            var next = req;
            next.index_name = req.sparse_queries[0].index_name;
            next.full_text = null;
            next.sparse = req.sparse_queries[0].query;
            next.sparse_queries = &.{};
            return next;
        }
        return null;
    }

    fn searchComposed(
        self: *DB,
        alloc: Allocator,
        req: types.SearchRequest,
        exec_ctx: types.ExecutionContext,
    ) !types.SearchResult {
        _ = exec_ctx;
        return try db_query_search.searchComposed(alloc, req, .{
            .ctx = self,
            .resolve_structured_doc_filter = resolveStructuredDocFilterForComposedCallback,
            .resolve_structured_text_doc_filter = resolveStructuredTextDocFilterForComposedCallback,
            .search_text_query = searchTextQueryCallback,
            .search_text = searchTextComposedCallback,
            .search_dense = searchDenseComposedCallback,
            .search_sparse = searchSparseComposedCallback,
            .clone_named_set = cloneNamedSetCallback,
            .fuse_named_sets = fuseNamedSetsCallback,
            .resolve_hits_to_doc_set = resolveSearchHitsToDocSetCallback,
            .attach_graph_results = attachGraphResultsCallback,
        });
    }

    fn resolveStructuredDocFilterForComposedCallback(
        ctx: ?*anyopaque,
        alloc: Allocator,
        req: types.SearchRequest,
    ) anyerror!?doc_set.ResolvedDocFilter {
        const self: *DB = @ptrCast(@alignCast(ctx orelse return error.InvalidArgument));
        return try db_query_search.resolveStructuredDocFilterForComposedAlloc(alloc, req, .{
            .ctx = self,
            .text_index_entry = textIndexEntryCallback,
            .resolve_doc_set_doc_ids = resolveDocSetDocIdsCallback,
            .resolve_doc_ids_to_doc_set = resolveDocIdsToDocSetCallback,
            .resolve_relational_filter_doc_set = resolveRelationalFilterDocSetCallback,
            .live_filter_doc_set = liveFilterDocSetCallback,
            .project_ordinals_to_doc_ids = false,
            .identity_read_generation = req.identity_read_generation,
        });
    }

    fn resolveStructuredTextDocFilterForComposedCallback(
        ctx: ?*anyopaque,
        alloc: Allocator,
        req: types.SearchRequest,
    ) anyerror!?db_query_search.ResolvedTextDocNumFilter {
        const self: *DB = @ptrCast(@alignCast(ctx orelse return error.InvalidArgument));
        return try db_query_search.resolveStructuredTextDocNumFilterForComposedAlloc(alloc, req, .{
            .ctx = self,
            .text_index_entry = textIndexEntryCallback,
            .resolve_doc_set_doc_ids = resolveDocSetDocIdsCallback,
            .resolve_doc_ids_to_doc_set = resolveDocIdsToDocSetCallback,
            .resolve_relational_filter_doc_set = resolveRelationalFilterDocSetCallback,
            .live_filter_doc_set = liveFilterDocSetCallback,
            .all_docs_visible = allDocsVisibleCallback,
            .project_ordinals_to_doc_ids = false,
            .identity_read_generation = req.identity_read_generation,
        });
    }

    fn searchText(self: *DB, alloc: Allocator, req: types.SearchRequest) !types.SearchResult {
        return try db_query_search.searchText(alloc, req, .{
            .ctx = self,
            .func = searchTextQueryCallback,
        });
    }

    fn searchTextQuery(self: *DB, alloc: Allocator, req: types.SearchRequest, text_query: types.TextQuery) !types.SearchResult {
        const needs_algebraic_doc_filter = req.doc_filter_bindings.len > 0 or req.require_algebraic_filter_resolution;
        var algebraic_filter = if (needs_algebraic_doc_filter)
            try self.searchRequestWithAlgebraicDocFilterAlloc(req)
        else
            AlgebraicDocFilterRequest{ .req = req };
        defer algebraic_filter.deinit();
        try self.proveTextQueryAccessPaths(algebraic_filter.req.index_name, text_query);
        const metric_name = self.textQueryMetricIndexName(algebraic_filter.req);
        const start_ns = platform_time.monotonicNs();
        defer db_query_metrics.observe(metric_name, .search, platform_time.monotonicNs() -| start_ns);
        return try db_query_search.searchTextQuery(alloc, algebraic_filter.req, text_query, .{
            .ctx = self,
            .text_index_entry = textIndexEntryCallback,
            .text_index_is_chunk_backed = textIndexIsChunkBackedCallback,
            .search_match_all = searchMatchAllCallback,
            .project_stored_search = projectStoredBytesForSearchCallback,
            .load_projected_document = loadProjectedSearchDocumentCallback,
            .resolve_doc_set_doc_ids = resolveDocSetDocIdsCallback,
            .resolve_doc_ids_to_doc_set = resolveDocIdsToDocSetCallback,
            .resolve_relational_filter_doc_set = resolveRelationalFilterDocSetCallback,
            .live_filter_doc_set = liveFilterDocSetCallback,
            .postprocess = postprocessTextSearchResultCallback,
        });
    }

    fn proveTextQueryAccessPaths(self: *DB, index_name: ?[]const u8, text_query: types.TextQuery) !void {
        switch (text_query) {
            .term => |term| try self.proveTextFieldAccessPath(index_name, term.field, null, .slice),
            .match => |match| try self.proveTextFieldAccessPath(index_name, match.field, match.analyzer, .slice),
            .multi_match_bool_prefix => |multi_match| {
                for (multi_match.fields) |field| try self.proveMultiMatchBoolPrefixAccessPaths(index_name, field.field);
            },
            .prefix => |prefix| try self.proveTextFieldAccessPath(index_name, prefix.field, null, .automaton_select),
            .wildcard => |wildcard| try self.proveTextFieldAccessPath(index_name, wildcard.field, null, .automaton_select),
            .regexp => |regexp| try self.proveTextFieldAccessPath(index_name, regexp.field, null, .automaton_select),
            .fuzzy => |fuzzy| try self.proveTextFieldAccessPath(index_name, fuzzy.field, null, .automaton_select),
            .bool_query => |bool_query| {
                for (bool_query.must) |child| try self.proveTextQueryAccessPaths(index_name, child);
                for (bool_query.should) |child| try self.proveTextQueryAccessPaths(index_name, child);
                for (bool_query.must_not) |child| try self.proveTextQueryAccessPaths(index_name, child);
            },
            else => {},
        }
    }

    fn proveTextFieldAccessPath(self: *DB, index_name: ?[]const u8, field: []const u8, analyzer: ?[]const u8, fragment: algebraic_mod.ir.TensorFragment) !void {
        _ = try self.core.index_manager.planFullTextLexicalAccessPathAlloc(self.alloc, index_name, field, analyzer, fragment) orelse return error.IndexNotFound;
    }

    fn proveOptionalTextFieldAccessPath(self: *DB, index_name: ?[]const u8, field: []const u8, fragment: algebraic_mod.ir.TensorFragment) !bool {
        const plan = try self.core.index_manager.planFullTextLexicalAccessPathAlloc(self.alloc, index_name, field, null, fragment);
        return plan != null;
    }

    fn proveMultiMatchBoolPrefixAccessPaths(self: *DB, index_name: ?[]const u8, field: []const u8) !void {
        if (std.mem.endsWith(u8, field, "._index_prefix")) {
            try self.proveTextFieldAccessPath(index_name, field, null, .slice);
            return;
        }

        try self.proveTextFieldAccessPath(index_name, field, null, .slice);
        try self.proveTextFieldAccessPath(index_name, field, null, .automaton_select);
        if (isSearchAsYouTypeGeneratedFieldName(field)) return;

        const two_gram = try std.fmt.allocPrint(self.alloc, "{s}._2gram", .{field});
        defer self.alloc.free(two_gram);
        const has_two_gram = try self.proveOptionalTextFieldAccessPath(index_name, two_gram, .slice);
        if (has_two_gram) _ = try self.proveOptionalTextFieldAccessPath(index_name, two_gram, .automaton_select);

        const three_gram = try std.fmt.allocPrint(self.alloc, "{s}._3gram", .{field});
        defer self.alloc.free(three_gram);
        const has_three_gram = try self.proveOptionalTextFieldAccessPath(index_name, three_gram, .slice);
        if (has_three_gram) _ = try self.proveOptionalTextFieldAccessPath(index_name, three_gram, .automaton_select);

        const index_prefix = try std.fmt.allocPrint(self.alloc, "{s}._index_prefix", .{field});
        defer self.alloc.free(index_prefix);
        _ = try self.proveOptionalTextFieldAccessPath(index_name, index_prefix, .slice);
    }

    fn isSearchAsYouTypeGeneratedFieldName(field: []const u8) bool {
        return std.mem.endsWith(u8, field, "._2gram") or
            std.mem.endsWith(u8, field, "._3gram") or
            std.mem.endsWith(u8, field, "._index_prefix");
    }

    fn textQueryMetricIndexName(self: *DB, req: types.SearchRequest) ?[]const u8 {
        if (req.index_name) |name| return name;
        const entry = self.core.textIndexEntry(null) orelse return null;
        return entry.config.name;
    }

