fn currentTimeNs() u64 {
    return platform_clock.Clock.real().nowRealtimeNs();
}

fn makeTxnId(self: *DB) transactions_mod.TxnId {
    var txn_id: transactions_mod.TxnId = undefined;
    const now = currentTimeNs();
    const seq = self.core.nextDerivedAppendSequence();
    std.mem.writeInt(u64, txn_id[0..8], now, .little);
    std.mem.writeInt(u64, txn_id[8..16], seq, .little);
    return txn_id;
}

fn relationalIdentityRewriteIntentKeyAlloc(alloc: Allocator, txn_id: transactions_mod.TxnId, rewrite: types.RelationalIdentityRewrite) ![]u8 {
    var out = std.ArrayListUnmanaged(u8).empty;
    defer out.deinit(alloc);
    try out.appendSlice(alloc, relational_identity_rewrite_intent_key_prefix);
    try appendHexBytes(alloc, &out, txn_id[0..]);
    try appendHexField(alloc, &out, rewrite.old_key);
    try appendHexField(alloc, &out, rewrite.new_key);
    return try out.toOwnedSlice(alloc);
}

fn foreignKeyExternalizedParentCheckIntentKeyAlloc(alloc: Allocator, txn_id: transactions_mod.TxnId, check: types.ForeignKeyParentCheck) ![]u8 {
    var out = std.ArrayListUnmanaged(u8).empty;
    defer out.deinit(alloc);
    try out.appendSlice(alloc, foreign_key_externalized_parent_check_intent_key_prefix);
    try appendHexBytes(alloc, &out, txn_id[0..]);
    try appendHexField(alloc, &out, check.constraint_name);
    try appendHexField(alloc, &out, check.child_table);
    try appendHexField(alloc, &out, check.child_key);
    try appendHexField(alloc, &out, check.parent_table);
    try appendHexField(alloc, &out, check.parent_key);
    return try out.toOwnedSlice(alloc);
}

fn foreignKeyConstraintTimingOverrideIntentKeyAlloc(alloc: Allocator, txn_id: transactions_mod.TxnId, override: types.ForeignKeyConstraintTimingOverride) ![]u8 {
    var out = std.ArrayListUnmanaged(u8).empty;
    defer out.deinit(alloc);
    try out.appendSlice(alloc, foreign_key_constraint_timing_override_intent_key_prefix);
    try appendHexBytes(alloc, &out, txn_id[0..]);
    try appendHexField(alloc, &out, override.constraint_name);
    return try out.toOwnedSlice(alloc);
}

fn appendHexField(alloc: Allocator, out: *std.ArrayListUnmanaged(u8), value: []const u8) !void {
    try out.append(alloc, ':');
    try appendHexBytes(alloc, out, value);
}

fn appendHexBytes(alloc: Allocator, out: *std.ArrayListUnmanaged(u8), value: []const u8) !void {
    const hex = "0123456789abcdef";
    try out.ensureUnusedCapacity(alloc, value.len * 2);
    for (value) |byte| {
        out.appendAssumeCapacity(hex[byte >> 4]);
        out.appendAssumeCapacity(hex[byte & 0x0f]);
    }
}

fn isForeignKeyExternalizedParentCheckIntentKey(key: []const u8) bool {
    return std.mem.startsWith(u8, key, foreign_key_externalized_parent_check_intent_key_prefix);
}

fn isForeignKeyConstraintTimingOverrideIntentKey(key: []const u8) bool {
    return std.mem.startsWith(u8, key, foreign_key_constraint_timing_override_intent_key_prefix);
}

fn isRelationalIdentityRewriteIntentKey(key: []const u8) bool {
    return std.mem.startsWith(u8, key, relational_identity_rewrite_intent_key_prefix);
}

fn encodeRelationalIdentityRewriteIntentValueAlloc(alloc: Allocator, rewrite: types.RelationalIdentityRewrite) ![]u8 {
    return try std.fmt.allocPrint(
        alloc,
        "{{\"old_key\":{f},\"new_key\":{f},\"value\":{f}}}",
        .{
            std.json.fmt(rewrite.old_key, .{}),
            std.json.fmt(rewrite.new_key, .{}),
            std.json.fmt(rewrite.value, .{}),
        },
    );
}

fn encodeForeignKeyExternalizedParentCheckIntentValueAlloc(alloc: Allocator, check: types.ForeignKeyParentCheck) ![]u8 {
    const timing = switch (check.timing) {
        .immediate => "immediate",
        .deferred => "deferred",
    };
    var out = std.ArrayListUnmanaged(u8).empty;
    defer out.deinit(alloc);
    const prefix = try std.fmt.allocPrint(
        alloc,
        "{{\"constraint_name\":{f},\"child_table\":{f},\"child_key\":{f},\"parent_table\":{f},\"parent_key\":{f},\"timing\":{f}",
        .{
            std.json.fmt(check.constraint_name, .{}),
            std.json.fmt(check.child_table, .{}),
            std.json.fmt(check.child_key, .{}),
            std.json.fmt(check.parent_table, .{}),
            std.json.fmt(check.parent_key, .{}),
            std.json.fmt(timing, .{}),
        },
    );
    defer alloc.free(prefix);
    try out.appendSlice(alloc, prefix);
    if (check.parent_constraint_name) |name| {
        const encoded = try std.fmt.allocPrint(alloc, ",\"parent_constraint_name\":{f}", .{std.json.fmt(name, .{})});
        defer alloc.free(encoded);
        try out.appendSlice(alloc, encoded);
    }
    if (check.child_period_start_json) |json| {
        const encoded = try std.fmt.allocPrint(alloc, ",\"child_period_start\":{s}", .{json});
        defer alloc.free(encoded);
        try out.appendSlice(alloc, encoded);
    }
    if (check.child_period_end_json) |json| {
        const encoded = try std.fmt.allocPrint(alloc, ",\"child_period_end\":{s}", .{json});
        defer alloc.free(encoded);
        try out.appendSlice(alloc, encoded);
    }
    try out.append(alloc, '}');
    return try out.toOwnedSlice(alloc);
}

fn encodeForeignKeyConstraintTimingOverrideIntentValueAlloc(alloc: Allocator, override: types.ForeignKeyConstraintTimingOverride) ![]u8 {
    const timing = switch (override.timing) {
        .immediate => "immediate",
        .deferred => "deferred",
    };
    return try std.fmt.allocPrint(
        alloc,
        "{{\"constraint_name\":{f},\"timing\":{f}}}",
        .{
            std.json.fmt(override.constraint_name, .{}),
            std.json.fmt(timing, .{}),
        },
    );
}

fn collectTransactionRelationalIdentityRewritesAlloc(
    alloc: Allocator,
    mutations: []const transactions_mod.OwnedIntentMutation,
    skip_keys: *std.ArrayListUnmanaged([]const u8),
) ![]types.RelationalIdentityRewrite {
    var out = std.ArrayListUnmanaged(types.RelationalIdentityRewrite).empty;
    errdefer {
        for (out.items) |*rewrite| freeRelationalIdentityRewrite(alloc, rewrite);
        out.deinit(alloc);
    }
    for (mutations) |mutation| {
        if (!isRelationalIdentityRewriteIntentKey(mutation.key)) continue;
        const raw = mutation.value orelse continue;
        const rewrite = try parseRelationalIdentityRewriteIntentValueAlloc(alloc, raw);
        var rewrite_owned = true;
        errdefer if (rewrite_owned) {
            var owned = rewrite;
            freeRelationalIdentityRewrite(alloc, &owned);
        };
        const skip_key = try alloc.dupe(u8, mutation.key);
        var skip_key_owned = true;
        errdefer if (skip_key_owned) alloc.free(skip_key);
        try skip_keys.append(alloc, skip_key);
        skip_key_owned = false;
        try out.append(alloc, rewrite);
        rewrite_owned = false;
    }
    return try out.toOwnedSlice(alloc);
}

fn collectTransactionExternalizedForeignKeyParentChecksAlloc(
    alloc: Allocator,
    mutations: []const transactions_mod.OwnedIntentMutation,
    skip_keys: *std.ArrayListUnmanaged([]const u8),
) ![]relational_store_mod.ExternalizedForeignKeyParentCheck {
    var out = std.ArrayListUnmanaged(relational_store_mod.ExternalizedForeignKeyParentCheck).empty;
    errdefer {
        for (out.items) |*check| freeExternalizedForeignKeyParentCheck(alloc, check);
        out.deinit(alloc);
    }
    for (mutations) |mutation| {
        if (!isForeignKeyExternalizedParentCheckIntentKey(mutation.key)) continue;
        const raw = mutation.value orelse continue;
        const check = try parseForeignKeyExternalizedParentCheckIntentValueAlloc(alloc, raw);
        var check_owned = true;
        errdefer if (check_owned) {
            var owned = check;
            freeExternalizedForeignKeyParentCheck(alloc, &owned);
        };
        const skip_key = try alloc.dupe(u8, mutation.key);
        var skip_key_owned = true;
        errdefer if (skip_key_owned) alloc.free(skip_key);
        try skip_keys.append(alloc, skip_key);
        skip_key_owned = false;
        try out.append(alloc, check);
        check_owned = false;
    }
    return try out.toOwnedSlice(alloc);
}

fn collectTransactionForeignKeyConstraintTimingOverridesAlloc(
    alloc: Allocator,
    mutations: []const transactions_mod.OwnedIntentMutation,
    skip_keys: *std.ArrayListUnmanaged([]const u8),
) ![]relational_store_mod.ForeignKeyConstraintTimingOverride {
    var out = std.ArrayListUnmanaged(relational_store_mod.ForeignKeyConstraintTimingOverride).empty;
    errdefer {
        for (out.items) |*override| freeRelationalForeignKeyConstraintTimingOverride(alloc, override);
        out.deinit(alloc);
    }
    for (mutations) |mutation| {
        if (!isForeignKeyConstraintTimingOverrideIntentKey(mutation.key)) continue;
        const raw = mutation.value orelse continue;
        const override = try parseForeignKeyConstraintTimingOverrideIntentValueAlloc(alloc, raw);
        var override_owned = true;
        errdefer if (override_owned) {
            var owned = override;
            freeRelationalForeignKeyConstraintTimingOverride(alloc, &owned);
        };
        const skip_key = try alloc.dupe(u8, mutation.key);
        var skip_key_owned = true;
        errdefer if (skip_key_owned) alloc.free(skip_key);
        try skip_keys.append(alloc, skip_key);
        skip_key_owned = false;
        try out.append(alloc, override);
        override_owned = false;
    }
    return try out.toOwnedSlice(alloc);
}

fn parseRelationalIdentityRewriteIntentValueAlloc(alloc: Allocator, raw: []const u8) !types.RelationalIdentityRewrite {
    var parsed = try std.json.parseFromSlice(std.json.Value, alloc, raw, .{});
    defer parsed.deinit();
    const obj = switch (parsed.value) {
        .object => |object| object,
        else => return error.InvalidQueryRequest,
    };
    const old_key = try alloc.dupe(u8, jsonObjectString(obj, "old_key") orelse return error.InvalidQueryRequest);
    errdefer alloc.free(old_key);
    const new_key = try alloc.dupe(u8, jsonObjectString(obj, "new_key") orelse return error.InvalidQueryRequest);
    errdefer alloc.free(new_key);
    const value = try alloc.dupe(u8, jsonObjectString(obj, "value") orelse return error.InvalidQueryRequest);
    errdefer alloc.free(value);
    return .{
        .old_key = old_key,
        .new_key = new_key,
        .value = value,
    };
}

fn parseForeignKeyExternalizedParentCheckIntentValueAlloc(alloc: Allocator, raw: []const u8) !relational_store_mod.ExternalizedForeignKeyParentCheck {
    var parsed = try std.json.parseFromSlice(std.json.Value, alloc, raw, .{});
    defer parsed.deinit();
    const obj = switch (parsed.value) {
        .object => |object| object,
        else => return error.ForeignKeyViolation,
    };
    const timing = jsonObjectString(obj, "timing") orelse return error.ForeignKeyViolation;
    if (!std.mem.eql(u8, timing, "deferred") and !std.mem.eql(u8, timing, "immediate")) return error.ForeignKeyViolation;
    const constraint_name = try alloc.dupe(u8, jsonObjectString(obj, "constraint_name") orelse return error.ForeignKeyViolation);
    errdefer alloc.free(constraint_name);
    const child_table = try alloc.dupe(u8, jsonObjectString(obj, "child_table") orelse return error.ForeignKeyViolation);
    errdefer alloc.free(child_table);
    const child_key = try alloc.dupe(u8, jsonObjectString(obj, "child_key") orelse return error.ForeignKeyViolation);
    errdefer alloc.free(child_key);
    const parent_table = try alloc.dupe(u8, jsonObjectString(obj, "parent_table") orelse return error.ForeignKeyViolation);
    errdefer alloc.free(parent_table);
    const parent_key = try alloc.dupe(u8, jsonObjectString(obj, "parent_key") orelse return error.ForeignKeyViolation);
    errdefer alloc.free(parent_key);
    const parent_constraint_name = if (jsonObjectString(obj, "parent_constraint_name")) |name|
        try alloc.dupe(u8, name)
    else
        null;
    errdefer if (parent_constraint_name) |name| alloc.free(name);
    const child_period_start_json = if (obj.get("child_period_start")) |value|
        try std.json.Stringify.valueAlloc(alloc, value, .{ .emit_null_optional_fields = false })
    else
        null;
    errdefer if (child_period_start_json) |json| alloc.free(json);
    const child_period_end_json = if (obj.get("child_period_end")) |value|
        try std.json.Stringify.valueAlloc(alloc, value, .{ .emit_null_optional_fields = false })
    else
        null;
    errdefer if (child_period_end_json) |json| alloc.free(json);
    if ((child_period_start_json == null) != (child_period_end_json == null)) return error.ForeignKeyViolation;
    return .{
        .constraint_name = constraint_name,
        .child_table = child_table,
        .child_key = child_key,
        .parent_table = parent_table,
        .parent_key = parent_key,
        .parent_constraint_name = parent_constraint_name,
        .child_period_start_json = child_period_start_json,
        .child_period_end_json = child_period_end_json,
        .timing = if (std.mem.eql(u8, timing, "deferred")) .deferred else .immediate,
    };
}

fn parseForeignKeyConstraintTimingOverrideIntentValueAlloc(alloc: Allocator, raw: []const u8) !relational_store_mod.ForeignKeyConstraintTimingOverride {
    var parsed = try std.json.parseFromSlice(std.json.Value, alloc, raw, .{});
    defer parsed.deinit();
    const obj = switch (parsed.value) {
        .object => |object| object,
        else => return error.ForeignKeyViolation,
    };
    const timing = jsonObjectString(obj, "timing") orelse return error.ForeignKeyViolation;
    if (!std.mem.eql(u8, timing, "deferred") and !std.mem.eql(u8, timing, "immediate")) return error.ForeignKeyViolation;
    const constraint_name = try alloc.dupe(u8, jsonObjectString(obj, "constraint_name") orelse return error.ForeignKeyViolation);
    errdefer alloc.free(constraint_name);
    return .{
        .constraint_name = constraint_name,
        .timing = if (std.mem.eql(u8, timing, "deferred")) .deferred else .immediate,
    };
}

fn jsonObjectString(obj: std.json.ObjectMap, key: []const u8) ?[]const u8 {
    const value = obj.get(key) orelse return null;
    return switch (value) {
        .string => |text| text,
        else => null,
    };
}

fn freeRelationalIdentityRewrites(alloc: Allocator, rewrites: []types.RelationalIdentityRewrite) void {
    for (rewrites) |*rewrite| freeRelationalIdentityRewrite(alloc, rewrite);
    if (rewrites.len > 0) alloc.free(rewrites);
}

fn freeRelationalIdentityRewrite(alloc: Allocator, rewrite: *types.RelationalIdentityRewrite) void {
    alloc.free(@constCast(rewrite.old_key));
    alloc.free(@constCast(rewrite.new_key));
    alloc.free(@constCast(rewrite.value));
    rewrite.* = undefined;
}

fn isRelationalIdentityRewriteEndpoint(rewrites: []const types.RelationalIdentityRewrite, key: []const u8) bool {
    for (rewrites) |rewrite| {
        if (std.mem.eql(u8, rewrite.old_key, key) or std.mem.eql(u8, rewrite.new_key, key)) return true;
    }
    return false;
}

fn freeExternalizedForeignKeyParentChecks(alloc: Allocator, checks: []relational_store_mod.ExternalizedForeignKeyParentCheck) void {
    for (checks) |*check| freeExternalizedForeignKeyParentCheck(alloc, check);
    if (checks.len > 0) alloc.free(checks);
}

fn freeExternalizedForeignKeyParentCheck(alloc: Allocator, check: *relational_store_mod.ExternalizedForeignKeyParentCheck) void {
    alloc.free(@constCast(check.constraint_name));
    alloc.free(@constCast(check.child_table));
    alloc.free(@constCast(check.child_key));
    alloc.free(@constCast(check.parent_table));
    alloc.free(@constCast(check.parent_key));
    if (check.parent_constraint_name) |name| alloc.free(@constCast(name));
    if (check.child_period_start_json) |json| alloc.free(@constCast(json));
    if (check.child_period_end_json) |json| alloc.free(@constCast(json));
    check.* = undefined;
}

fn freeRelationalForeignKeyConstraintTimingOverrides(alloc: Allocator, overrides: []relational_store_mod.ForeignKeyConstraintTimingOverride) void {
    for (overrides) |*override| freeRelationalForeignKeyConstraintTimingOverride(alloc, override);
    if (overrides.len > 0) alloc.free(overrides);
}

fn freeRelationalForeignKeyConstraintTimingOverride(alloc: Allocator, override: *relational_store_mod.ForeignKeyConstraintTimingOverride) void {
    alloc.free(@constCast(override.constraint_name));
    override.* = undefined;
}

fn shouldWriteTimestamp(key: []const u8) bool {
    return !isMetadataKey(key) and !internal_keys.isInternalPhysicalTableDataKey(key);
}

fn makeTimestampKey(alloc: Allocator, key: []const u8) ![]u8 {
    return try internal_keys.ttlKeyAlloc(alloc, key);
}

fn resolveWriteTimestampNs(self: *DB, fallback_timestamp_ns: u64, value_json: []const u8) !u64 {
    const schema = self.core.schema orelse return fallback_timestamp_ns;
    if (schema.ttl_duration_ns == 0) return fallback_timestamp_ns;
    return (try ttlTimestampNsFromDocumentValue(self.alloc, schema, value_json)) orelse fallback_timestamp_ns;
}

fn ttlTimestampNsFromDocumentValue(
    alloc: Allocator,
    schema: schema_mod.TableSchema,
    value_json: []const u8,
) !?u64 {
    var parsed = try std.json.parseFromSlice(std.json.Value, alloc, value_json, .{});
    defer parsed.deinit();
    const root = switch (parsed.value) {
        .object => |object| object,
        else => return null,
    };
    const ttl_value = root.get(schema.ttl_field) orelse return null;
    if (ttl_value == .null) return null;
    return try ttlTimestampNsFromJsonValue(ttl_value);
}

fn ttlTimestampNsFromJsonValue(value: std.json.Value) !u64 {
    return switch (value) {
        .integer => |integer| blk: {
            if (integer < 0) return error.InvalidArgument;
            break :blk std.math.cast(u64, integer) orelse return error.InvalidArgument;
        },
        .number_string => |text| std.fmt.parseInt(u64, std.mem.trim(u8, text, " \t\r\n"), 10) catch return error.InvalidArgument,
        .string => |text| ttlTimestampNsFromString(text),
        else => error.InvalidArgument,
    };
}

fn ttlTimestampNsFromString(text: []const u8) !u64 {
    const trimmed = std.mem.trim(u8, text, " \t\r\n");
    if (trimmed.len == 0) return error.InvalidArgument;
    if (std.fmt.parseInt(u64, trimmed, 10)) |ts| return ts else |_| {}
    if (try parsePatternRfc3339ToNs(trimmed)) |ts| return ts;
    return error.InvalidArgument;
}

fn encodeTimestampValue(alloc: Allocator, timestamp_ns: u64) ![]u8 {
    const buf = try alloc.alloc(u8, 8);
    std.mem.writeInt(u64, buf[0..8], timestamp_ns, .little);
    return buf;
}

fn ttlDurationNs(self: *DB) u64 {
    return if (self.core.schema) |schema| schema.ttl_duration_ns else 0;
}

fn isExpiredDocumentKey(self: *DB, alloc: Allocator, key: []const u8) !bool {
    const duration_ns = ttlDurationNs(self);
    if (duration_ns == 0) return false;
    const ts = try self.getTimestamp(alloc, key);
    if (ts == 0) return false;
    return ttl_mod.isExpired(ts, duration_ns, currentTimeNs());
}

fn loadDocumentTimestampsMany(self: *DB, alloc: Allocator, keys: []const []const u8) ![]u64 {
    const timestamps = try alloc.alloc(u64, keys.len);
    errdefer alloc.free(timestamps);
    @memset(timestamps, 0);
    if (keys.len == 0) return timestamps;

    const PendingTimestampLoad = struct {
        original_index: usize,
        store_key: []u8,
    };

    var pending = std.ArrayListUnmanaged(PendingTimestampLoad).empty;
    defer {
        for (pending.items) |item| alloc.free(item.store_key);
        pending.deinit(alloc);
    }

    for (keys, 0..) |key, i| {
        if (internal_keys.isInternalPhysicalTableDataKey(key)) continue;
        try pending.append(alloc, .{
            .original_index = i,
            .store_key = try internal_keys.ttlKeyAlloc(alloc, key),
        });
    }
    if (pending.items.len == 0) return timestamps;

    std.mem.sort(PendingTimestampLoad, pending.items, {}, struct {
        fn lessThan(_: void, lhs: PendingTimestampLoad, rhs: PendingTimestampLoad) bool {
            return std.mem.order(u8, lhs.store_key, rhs.store_key) == .lt;
        }
    }.lessThan);

    const read_keys = try alloc.alloc([]const u8, pending.items.len);
    defer alloc.free(read_keys);
    const read_values = try alloc.alloc(?[]const u8, pending.items.len);
    defer alloc.free(read_values);
    @memset(read_values, null);

    for (pending.items, 0..) |item, i| read_keys[i] = item.store_key;

    var txn = try self.core.store.beginProbeTxn();
    defer txn.abort();
    try txn.getManySorted(read_keys, read_values);

    for (pending.items, 0..) |item, i| {
        const raw = read_values[i] orelse continue;
        if (raw.len != 8) continue;
        timestamps[item.original_index] = std.mem.readInt(u64, raw[0..8], .little);
    }
    return timestamps;
}

fn filterVisibleSearchHitsMany(self: *DB, alloc: Allocator, hits: []const types.SearchHit) ![]bool {
    const keep = try alloc.alloc(bool, hits.len);
    errdefer alloc.free(keep);
    @memset(keep, true);

    const duration_ns = ttlDurationNs(self);
    if (duration_ns == 0 or hits.len == 0) return keep;

    const expiry_now = currentTimeNs();
    const parent_ids = try alloc.alloc([]const u8, hits.len);
    defer alloc.free(parent_ids);

    const needs_stored = try alloc.alloc(bool, hits.len);
    defer alloc.free(needs_stored);
    @memset(needs_stored, false);

    const fallback_to_hit = try alloc.alloc(bool, hits.len);
    defer alloc.free(fallback_to_hit);
    @memset(fallback_to_hit, false);

    for (hits, 0..) |hit, i| {
        if (internal_keys.isChunkArtifactRecordKey(hit.id)) {
            const parent = (try internal_keys.decodeDocumentComponentAlloc(alloc, hit.id)) orelse {
                fallback_to_hit[i] = true;
                parent_ids[i] = hit.id;
                continue;
            };
            parent_ids[i] = parent;
            continue;
        }
        if (hit.stored_data != null) {
            parent_ids[i] = parseChunkParentIdFromStoredAlloc(alloc, hit.stored_data.?) catch {
                fallback_to_hit[i] = true;
                parent_ids[i] = hit.id;
                continue;
            };
            continue;
        }
        needs_stored[i] = true;
        parent_ids[i] = hit.id;
    }
    defer {
        for (hits, 0..) |_, i| {
            if (!needs_stored[i] and !std.mem.eql(u8, parent_ids[i], hits[i].id)) alloc.free(parent_ids[i]);
        }
    }

    var pending_indices = std.ArrayListUnmanaged(usize).empty;
    defer pending_indices.deinit(alloc);
    for (needs_stored, 0..) |needed, i| if (needed) try pending_indices.append(alloc, i);
    if (pending_indices.items.len > 0) {
        const pending_keys = try alloc.alloc([]const u8, pending_indices.items.len);
        defer alloc.free(pending_keys);
        for (pending_indices.items, 0..) |hit_index, i| pending_keys[i] = hits[hit_index].id;

        const loaded = try loadStoredSearchDocumentsMany(self, alloc, pending_keys);
        defer freeOptionalOwnedBytes(alloc, loaded);
        for (pending_indices.items, 0..) |hit_index, i| {
            const stored = loaded[i] orelse {
                fallback_to_hit[hit_index] = true;
                continue;
            };
            parent_ids[hit_index] = parseChunkParentIdFromStoredAlloc(alloc, stored) catch {
                fallback_to_hit[hit_index] = true;
                continue;
            };
        }
    }

    const timestamps = try loadDocumentTimestampsMany(self, alloc, parent_ids);
    defer alloc.free(timestamps);
    for (timestamps, 0..) |ts, i| {
        if (ts == 0) continue;
        keep[i] = !ttl_mod.isExpired(ts, duration_ns, expiry_now);
    }
    return keep;
}

fn filterExpiredSearchResult(self: *DB, alloc: Allocator, raw: types.SearchResult) !types.SearchResult {
    if (ttlDurationNs(self) == 0) return raw;
    return try db_query_result_shape.filterVisibleSearchResult(alloc, raw, .{
        .ctx = self,
        .func = isVisibleSearchHitCallback,
        .filter_many = filterVisibleSearchHitsManyCallback,
    });
}

fn isVisibleSearchHit(self: *DB, alloc: Allocator, hit: types.SearchHit) !bool {
    return try db_query_result_shape.isVisibleSearchHit(alloc, hit, .{
        .ctx = self,
        .load_stored = loadStoredForHitCallback,
        .is_expired_key = isExpiredDocumentKeyCallback,
    });
}

fn isVisibleSearchHitCallback(
    ctx: ?*anyopaque,
    alloc: Allocator,
    hit: types.SearchHit,
) anyerror!bool {
    const self: *DB = @ptrCast(@alignCast(ctx orelse return error.InvalidArgument));
    return try isVisibleSearchHit(self, alloc, hit);
}

fn filterVisibleSearchHitsManyCallback(
    ctx: ?*anyopaque,
    alloc: Allocator,
    hits: []const types.SearchHit,
) anyerror![]bool {
    const self: *DB = @ptrCast(@alignCast(ctx orelse return error.InvalidArgument));
    return try filterVisibleSearchHitsMany(self, alloc, hits);
}

fn isVisibleNonChunkSearchHitCallback(
    ctx: ?*anyopaque,
    alloc: Allocator,
    hit: types.SearchHit,
) anyerror!bool {
    const self: *DB = @ptrCast(@alignCast(ctx orelse return error.InvalidArgument));
    return !(try isExpiredDocumentKey(self, alloc, hit.id));
}

fn reshapeChunkBackedResult(self: *DB, alloc: Allocator, req: types.SearchRequest, raw: types.SearchResult) !types.SearchResult {
    return try db_query_result_shape.reshapeChunkBackedResult(alloc, req, raw, .{
        .ctx = self,
        .resolve_parent_id = resolveChunkParentIdCallback,
        .load_parent_stored = loadParentStoredForSearchCallback,
    });
}

fn resolveChunkParentId(self: *DB, alloc: Allocator, hit: types.SearchHit) ![]u8 {
    return try db_query_result_shape.resolveChunkParentId(alloc, hit, .{
        .ctx = self,
        .load_stored = loadStoredForHitCallback,
    });
}

fn parseChunkParentIdFromStoredAlloc(alloc: Allocator, stored: []const u8) ![]u8 {
    const parsed = try std.json.parseFromSlice(std.json.Value, alloc, stored, .{});
    defer parsed.deinit();
    if (parsed.value != .object) return error.InvalidChunkArtifact;
    const parent = parsed.value.object.get("_parent_doc_key") orelse parsed.value.object.get("parent_doc_key") orelse return error.InvalidChunkArtifact;
    if (parent != .string) return error.InvalidChunkArtifact;
    return try alloc.dupe(u8, parent.string);
}

fn resolveChunkParentIdCallback(
    ctx: ?*anyopaque,
    alloc: Allocator,
    hit: types.SearchHit,
) anyerror![]u8 {
    const self: *DB = @ptrCast(@alignCast(ctx orelse return error.InvalidArgument));
    return try resolveChunkParentId(self, alloc, hit);
}

fn loadParentStoredForSearchCallback(
    ctx: ?*anyopaque,
    alloc: Allocator,
    req: types.SearchRequest,
    parent_id: []const u8,
) anyerror!?[]u8 {
    const self: *DB = @ptrCast(@alignCast(ctx orelse return error.InvalidArgument));
    return if (try self.loadStoredSearchDocumentProbe(alloc, parent_id)) |stored|
        try projectOwnedStoredBytesForSearch(self, alloc, req, parent_id, stored)
    else
        null;
}

fn loadParentStoredForSearchManyCallback(
    ctx: ?*anyopaque,
    alloc: Allocator,
    req: types.SearchRequest,
    parent_ids: []const []const u8,
) anyerror![]?[]u8 {
    const self: *DB = @ptrCast(@alignCast(ctx orelse return error.InvalidArgument));
    return try self.loadProjectedSearchDocumentMany(alloc, req, parent_ids);
}

fn loadStoredForHitCallback(
    ctx: ?*anyopaque,
    alloc: Allocator,
    key: []const u8,
) anyerror!?[]u8 {
    const self: *DB = @ptrCast(@alignCast(ctx orelse return error.InvalidArgument));
    return try self.loadStoredSearchDocumentProbe(alloc, key);
}

fn isExpiredDocumentKeyCallback(
    ctx: ?*anyopaque,
    alloc: Allocator,
    key: []const u8,
) anyerror!bool {
    const self: *DB = @ptrCast(@alignCast(ctx orelse return error.InvalidArgument));
    return try isExpiredDocumentKey(self, alloc, key);
}

fn patternNodeFilterEvaluator(ctx: ?*anyopaque, key: []const u8, filter: graph_pattern_mod.NodeFilter) anyerror!bool {
    const self: *DB = @ptrCast(@alignCast(ctx orelse return error.UnsupportedNodeFilterQuery));
    return try matchesPatternNodeFilter(self, key, filter);
}

fn matchesPatternNodeFilter(self: *DB, key: []const u8, filter: graph_pattern_mod.NodeFilter) !bool {
    if (filter.filter_query_json == null) return true;
    const stored = (try self.get(self.alloc, key)) orelse return false;
    defer self.alloc.free(stored);
    return try storedDocMatchesPatternFilter(self.alloc, key, stored, filter.filter_query_json.?);
}

fn storedDocMatchesPatternFilter(alloc: Allocator, key: []const u8, stored: []const u8, filter_query_json: []const u8) !bool {
    return try db_query_graph.storedDocMatchesPatternFilter(alloc, key, stored, filter_query_json);
}

fn jsonDocMatchesPatternFilter(alloc: Allocator, key: []const u8, doc: std.json.Value, filter_query: std.json.Value) !bool {
    return try db_query_graph.jsonDocMatchesPatternFilter(alloc, key, doc, filter_query);
}

fn parsePatternRfc3339ToNs(text: []const u8) !?u64 {
    return try db_query_graph.parsePatternRfc3339ToNs(text);
}

fn buildDerivedBatch(
    alloc: Allocator,
    req: types.BatchRequest,
    extracted: []const mapper.ExtractedWrite,
    deleted_artifact_keys: []const []u8,
    changed_artifact_keys: []const []u8,
) !derived_types.DerivedBatch {
    var documents = try alloc.alloc(derived_types.DerivedDocument, req.writes.len);
    var initialized: usize = 0;
    errdefer {
        var tmp = derived_types.DerivedBatch{ .documents = documents[0..initialized] };
        derived_types.deinitDerivedBatch(alloc, &tmp);
    }

    for (req.writes, 0..) |write, i| {
        var targets = std.ArrayListUnmanaged(derived_types.DerivedTargetRef).empty;
        defer targets.deinit(alloc);

        if (extracted[i].cleaned_value != null) {
            try targets.append(alloc, .{
                .kind = .full_text,
                .index_name = try alloc.dupe(u8, "*"),
            });
        }
        for (extracted[i].dense_embeddings) |embedding| {
            try targets.append(alloc, .{
                .kind = .dense_vector,
                .index_name = try alloc.dupe(u8, embedding.index_name),
            });
        }
        for (extracted[i].sparse_embeddings) |embedding| {
            try targets.append(alloc, .{
                .kind = .sparse_vector,
                .index_name = try alloc.dupe(u8, embedding.index_name),
            });
        }
        for (extracted[i].mentioned_graph_indexes) |index_name| {
            try targets.append(alloc, .{
                .kind = .graph,
                .index_name = try alloc.dupe(u8, index_name),
            });
        }
        for (req.graph_writes) |graph_write| {
            if (std.mem.eql(u8, graph_write.source, write.key)) {
                try targets.append(alloc, .{
                    .kind = .graph,
                    .index_name = try alloc.dupe(u8, graph_write.index_name),
                });
            }
        }

        documents[i] = .{
            .key = try alloc.dupe(u8, write.key),
            .action = if (extracted[i].cleaned_value == null) .preserve_base_document else .upsert,
            .cleaned_value = null,
            .targets = try targets.toOwnedSlice(alloc),
        };
        initialized += 1;
    }

    var deleted_keys = try alloc.alloc([]const u8, req.deletes.len + deleted_artifact_keys.len);
    var deleted_initialized: usize = 0;
    errdefer {
        for (deleted_keys[0..deleted_initialized]) |key| alloc.free(key);
        alloc.free(deleted_keys);
    }
    for (req.deletes, 0..) |key, i| {
        deleted_keys[i] = try alloc.dupe(u8, key);
        deleted_initialized += 1;
    }
    for (deleted_artifact_keys) |key| {
        deleted_keys[deleted_initialized] = try alloc.dupe(u8, key);
        deleted_initialized += 1;
    }

    var overwritten_doc_keys_list = std.ArrayListUnmanaged([]const u8).empty;
    defer overwritten_doc_keys_list.deinit(alloc);
    for (req.writes, 0..) |write, i| {
        if (extracted[i].cleaned_value != null) {
            try overwritten_doc_keys_list.append(alloc, try alloc.dupe(u8, write.key));
        }
    }

    var changed_artifact_keys_list = std.ArrayListUnmanaged([]const u8).empty;
    errdefer {
        for (changed_artifact_keys_list.items) |key| alloc.free(@constCast(key));
        changed_artifact_keys_list.deinit(alloc);
    }
    for (changed_artifact_keys) |key| {
        try changed_artifact_keys_list.append(alloc, try alloc.dupe(u8, key));
    }
    for (deleted_artifact_keys) |key| {
        if (!internal_keys.isAssetArtifactKey(key) and !internal_keys.isGraphEdgeArtifactKey(key)) continue;
        try changed_artifact_keys_list.append(alloc, try alloc.dupe(u8, key));
    }

    var graph_doc_clears = std.ArrayListUnmanaged(derived_types.DerivedGraphDocClear).empty;
    errdefer {
        for (graph_doc_clears.items) |clear| {
            alloc.free(clear.key);
            for (clear.index_names) |index_name| alloc.free(index_name);
            if (clear.index_names.len > 0) alloc.free(clear.index_names);
        }
        graph_doc_clears.deinit(alloc);
    }
    for (req.writes, 0..) |write, i| {
        if (extracted[i].mentioned_graph_indexes.len == 0) continue;
        var index_names = try alloc.alloc([]const u8, extracted[i].mentioned_graph_indexes.len);
        for (extracted[i].mentioned_graph_indexes, 0..) |index_name, j| {
            index_names[j] = try alloc.dupe(u8, index_name);
        }
        try graph_doc_clears.append(alloc, .{
            .key = try alloc.dupe(u8, write.key),
            .index_names = index_names,
        });
    }

    var graph_writes = std.ArrayListUnmanaged(types.GraphEdgeWrite).empty;
    errdefer {
        for (graph_writes.items) |write| {
            alloc.free(@constCast(write.index_name));
            alloc.free(@constCast(write.source));
            alloc.free(@constCast(write.target));
            alloc.free(@constCast(write.edge_type));
            if (write.metadata_json.len > 0) alloc.free(@constCast(write.metadata_json));
        }
        graph_writes.deinit(alloc);
    }
    for (extracted) |item| {
        for (item.graph_writes) |write| {
            try graph_writes.append(alloc, .{
                .index_name = try alloc.dupe(u8, write.index_name),
                .source = try alloc.dupe(u8, write.source),
                .target = try alloc.dupe(u8, write.target),
                .edge_type = try alloc.dupe(u8, write.edge_type),
                .weight = write.weight,
                .created_at = write.created_at,
                .updated_at = write.updated_at,
                .metadata_json = if (write.metadata_json.len > 0) try alloc.dupe(u8, write.metadata_json) else "",
            });
        }
    }
    for (req.graph_writes) |write| {
        try graph_writes.append(alloc, .{
            .index_name = try alloc.dupe(u8, write.index_name),
            .source = try alloc.dupe(u8, write.source),
            .target = try alloc.dupe(u8, write.target),
            .edge_type = try alloc.dupe(u8, write.edge_type),
            .weight = write.weight,
            .created_at = write.created_at,
            .updated_at = write.updated_at,
            .metadata_json = if (write.metadata_json.len > 0) try alloc.dupe(u8, write.metadata_json) else "",
        });
    }

    var graph_deletes = std.ArrayListUnmanaged(types.GraphEdgeDelete).empty;
    errdefer {
        for (graph_deletes.items) |delete| {
            alloc.free(@constCast(delete.index_name));
            alloc.free(@constCast(delete.source));
            alloc.free(@constCast(delete.target));
            alloc.free(@constCast(delete.edge_type));
        }
        graph_deletes.deinit(alloc);
    }
    for (req.graph_deletes) |delete| {
        try graph_deletes.append(alloc, .{
            .index_name = try alloc.dupe(u8, delete.index_name),
            .source = try alloc.dupe(u8, delete.source),
            .target = try alloc.dupe(u8, delete.target),
            .edge_type = try alloc.dupe(u8, delete.edge_type),
        });
    }

    var dense_embeddings = std.ArrayListUnmanaged(derived_types.DerivedDenseEmbeddingWrite).empty;
    errdefer {
        for (dense_embeddings.items) |embedding| {
            alloc.free(embedding.index_name);
            if (embedding.parent_doc_key) |parent_doc_key| alloc.free(parent_doc_key);
            alloc.free(embedding.doc_key);
            if (embedding.artifact_key) |artifact_key| alloc.free(artifact_key);
            if (embedding.vector.len > 0) alloc.free(embedding.vector);
        }
        dense_embeddings.deinit(alloc);
    }
    for (extracted) |item| {
        for (item.dense_embeddings) |embedding| {
            try dense_embeddings.append(alloc, .{
                .index_name = try alloc.dupe(u8, embedding.index_name),
                .doc_key = try alloc.dupe(u8, embedding.doc_key),
                .artifact_key = if (embedding.artifact_key) |artifact_key| try alloc.dupe(u8, artifact_key) else null,
                .vector = if (embedding.artifact_key != null) &.{} else try alloc.dupe(f32, embedding.vector),
            });
        }
    }

    var sparse_embeddings = std.ArrayListUnmanaged(derived_types.DerivedSparseEmbeddingWrite).empty;
    errdefer {
        for (sparse_embeddings.items) |embedding| {
            alloc.free(embedding.index_name);
            alloc.free(embedding.doc_key);
            if (embedding.indices.len > 0) alloc.free(embedding.indices);
            if (embedding.values.len > 0) alloc.free(embedding.values);
        }
        sparse_embeddings.deinit(alloc);
    }
    for (extracted) |item| {
        for (item.sparse_embeddings) |embedding| {
            try sparse_embeddings.append(alloc, .{
                .index_name = try alloc.dupe(u8, embedding.index_name),
                .doc_key = try alloc.dupe(u8, embedding.doc_key),
                .artifact_key = if (embedding.artifact_key) |artifact_key| try alloc.dupe(u8, artifact_key) else null,
                .indices = try alloc.dupe(u32, embedding.indices),
                .values = try alloc.dupe(f32, embedding.values),
            });
        }
    }

    return .{
        .sequence = 0,
        .documents = documents,
        .deleted_keys = deleted_keys,
        .overwritten_doc_keys = try overwritten_doc_keys_list.toOwnedSlice(alloc),
        .changed_artifact_keys = try changed_artifact_keys_list.toOwnedSlice(alloc),
        .graph_doc_clears = try graph_doc_clears.toOwnedSlice(alloc),
        .dense_embeddings = try dense_embeddings.toOwnedSlice(alloc),
        .sparse_embeddings = try sparse_embeddings.toOwnedSlice(alloc),
        .generated_enrichment_refs = &.{},
        .graph_writes = try graph_writes.toOwnedSlice(alloc),
        .graph_deletes = try graph_deletes.toOwnedSlice(alloc),
    };
}

fn appendGeneratedEnrichments(
    self: *DB,
    batch: *derived_types.DerivedBatch,
    req: types.BatchRequest,
    extracted: []const mapper.ExtractedWrite,
) !void {
    var planned = std.ArrayListUnmanaged(enrichment_types.GeneratedEnrichmentRef).empty;
    errdefer enrichment_types.deinitGeneratedRefs(self.alloc, planned.items);

    for (req.writes, 0..) |write, i| {
        const cleaned = extracted[i].cleaned_value orelse continue;
        var explicit_dense = std.ArrayListUnmanaged(types.EnrichmentDenseEmbeddingWrite).empty;
        defer {
            for (explicit_dense.items) |*embedding| embedding.deinit(self.alloc);
            explicit_dense.deinit(self.alloc);
        }
        for (extracted[i].dense_embeddings) |embedding| {
            try explicit_dense.append(self.alloc, .{
                .index_name = try self.alloc.dupe(u8, embedding.index_name),
                .doc_key = try self.alloc.dupe(u8, embedding.doc_key),
                .vector = try self.alloc.dupe(f32, embedding.vector),
            });
        }
        var explicit_sparse = std.ArrayListUnmanaged(types.EnrichmentSparseEmbeddingWrite).empty;
        defer {
            for (explicit_sparse.items) |*embedding| embedding.deinit(self.alloc);
            explicit_sparse.deinit(self.alloc);
        }
        for (extracted[i].sparse_embeddings) |embedding| {
            try explicit_sparse.append(self.alloc, .{
                .index_name = try self.alloc.dupe(u8, embedding.index_name),
                .doc_key = try self.alloc.dupe(u8, embedding.doc_key),
                .indices = try self.alloc.dupe(u32, embedding.indices),
                .values = try self.alloc.dupe(f32, embedding.values),
            });
        }
        const generated = try self.core.planGeneratedEnrichments(
            self.alloc,
            write.key,
            cleaned,
            explicit_dense.items,
            explicit_sparse.items,
        );
        defer enrichment_types.deinitGeneratedRequests(self.alloc, generated);
        for (generated) |request| {
            try planned.append(self.alloc, try enrichment_types.requestToRef(self.alloc, request));
        }
    }

    batch.generated_enrichment_refs = try planned.toOwnedSlice(self.alloc);
}

fn deleteEnrichmentArtifactsForBatch(self: *DB, req: types.BatchRequest, extracted: []const mapper.ExtractedWrite) ![][]u8 {
    _ = extracted;
    if (!self.core.hasArtifactCleanupMaybe()) return try self.alloc.alloc([]u8, 0);

    var deleted = std.ArrayListUnmanaged([]u8).empty;
    errdefer freeOwnedKeySlice(self.alloc, deleted.items);

    for (req.deletes) |key| {
        try self.core.collectAndDeleteEnrichmentArtifactsForDocContext(self.alloc, key, &deleted);
    }
    return try deleted.toOwnedSlice(self.alloc);
}

fn collectAndDeleteEnrichmentArtifactsForDocContext(
    alloc: Allocator,
    store: *docstore_mod.DocStore,
    doc_key: []const u8,
    deleted: *std.ArrayListUnmanaged([]u8),
) !void {
    var deletes = std.ArrayListUnmanaged([]const u8).empty;
    defer deletes.deinit(alloc);
    var unrecorded_delete_keys = std.ArrayListUnmanaged([]u8).empty;
    defer {
        for (unrecorded_delete_keys.items) |key| alloc.free(key);
        unrecorded_delete_keys.deinit(alloc);
    }

    const artifact_prefix = try internal_keys.artifactRootPrefixAlloc(alloc, doc_key);
    defer alloc.free(artifact_prefix);
    try collectDeleteKeysForPrefix(alloc, store, artifact_prefix, &deletes, deleted, &unrecorded_delete_keys);

    const asset_state_prefix = try internal_keys.assetStateRootPrefixAlloc(alloc, doc_key);
    defer alloc.free(asset_state_prefix);
    try collectDeleteKeysForPrefix(alloc, store, asset_state_prefix, &deletes, null, &unrecorded_delete_keys);

    const graph_asset_state_prefix = try internal_keys.graphAssetStateRootPrefixAlloc(alloc, doc_key);
    defer alloc.free(graph_asset_state_prefix);
    try collectDeleteKeysForPrefix(alloc, store, graph_asset_state_prefix, &deletes, null, &unrecorded_delete_keys);

    if (deletes.items.len > 0) {
        try store.putBatch(&.{}, deletes.items);
    }
}

fn collectDeleteKeysForPrefix(
    alloc: Allocator,
    store: *docstore_mod.DocStore,
    prefix: []const u8,
    deletes: *std.ArrayListUnmanaged([]const u8),
    recorded: ?*std.ArrayListUnmanaged([]u8),
    unrecorded: *std.ArrayListUnmanaged([]u8),
) !void {
    const existing = try store.scanPrefix(alloc, prefix);
    defer docstore_mod.DocStore.freeResults(alloc, existing);
    for (existing) |entry| {
        const owned = try alloc.dupe(u8, entry.key);
        errdefer alloc.free(owned);
        try deletes.append(alloc, owned);
        if (recorded) |out| {
            try out.append(alloc, owned);
        } else {
            try unrecorded.append(alloc, owned);
        }
    }
}

fn collectGraphArtifactsForDocIndex(
    alloc: Allocator,
    store: *docstore_mod.DocStore,
    doc_key: []const u8,
    index_name: []const u8,
) ![]docstore_mod.OwnedKVPair {
    const prefix = try internal_keys.graphArtifactIndexPrefixAlloc(alloc, doc_key, index_name);
    defer alloc.free(prefix);
    return try store.scanPrefix(alloc, prefix);
}

fn executeDeleteBatchContext(ctx: *const BatchExecutionContext, keys: []const []const u8, sync_level: types.SyncLevel) !void {
    if (keys.len == 0) return;

    var store_writes = std.ArrayListUnmanaged(docstore_mod.KVPair).empty;
    defer store_writes.deinit(ctx.alloc);
    var owned_store_keys = std.ArrayListUnmanaged([]u8).empty;
    defer {
        for (owned_store_keys.items) |key| ctx.alloc.free(key);
        owned_store_keys.deinit(ctx.alloc);
    }
    var owned_store_values = std.ArrayListUnmanaged([]u8).empty;
    defer {
        for (owned_store_values.items) |value| ctx.alloc.free(value);
        owned_store_values.deinit(ctx.alloc);
    }
    var identity_writes = std.ArrayListUnmanaged(docstore_mod.KVPair).empty;
    defer {
        for (identity_writes.items) |item| {
            ctx.alloc.free(@constCast(item.key));
            ctx.alloc.free(@constCast(item.value));
        }
        identity_writes.deinit(ctx.alloc);
    }
    var delete_keys = std.ArrayListUnmanaged([]const u8).empty;
    defer delete_keys.deinit(ctx.alloc);
    var timestamp_delete_keys = std.ArrayListUnmanaged([]const u8).empty;
    defer {
        for (timestamp_delete_keys.items) |key| ctx.alloc.free(@constCast(key));
        timestamp_delete_keys.deinit(ctx.alloc);
    }
    var owned_delete_keys = std.ArrayListUnmanaged([]u8).empty;
    defer {
        for (owned_delete_keys.items) |key| ctx.alloc.free(key);
        owned_delete_keys.deinit(ctx.alloc);
    }

    for (keys) |key| {
        if (ctx.relational_base_rows) {
            try relational_store_mod.appendDelete(ctx.alloc, ctx.store, &delete_keys, &owned_delete_keys, key);
            const primary_key = try internal_keys.documentKeyAlloc(ctx.alloc, key);
            var primary_key_owned = true;
            errdefer if (primary_key_owned) ctx.alloc.free(primary_key);
            try owned_delete_keys.append(ctx.alloc, primary_key);
            primary_key_owned = false;
            try delete_keys.append(ctx.alloc, primary_key);
        } else {
            const store_key = try internal_keys.documentKeyAlloc(ctx.alloc, key);
            try owned_delete_keys.append(ctx.alloc, store_key);
            try delete_keys.append(ctx.alloc, store_key);
        }
        if (!shouldWriteTimestamp(key)) continue;
        const timestamp_key = try makeTimestampKey(ctx.alloc, key);
        try timestamp_delete_keys.append(ctx.alloc, timestamp_key);
        try delete_keys.append(ctx.alloc, timestamp_key);
    }

    var deleted_artifact_keys = std.ArrayListUnmanaged([]u8).empty;
    defer freeOwnedKeySlice(ctx.alloc, deleted_artifact_keys.items);
    const should_scan_artifacts = if (ctx.artifact_cleanup_maybe) |artifact_cleanup_maybe|
        artifact_cleanup_maybe.load(.acquire) or ctx.index_manager.hasGeneratedEnrichmentTargets()
    else
        true;
    if (should_scan_artifacts) {
        for (keys) |key| {
            try collectAndDeleteEnrichmentArtifactsForDocContext(ctx.alloc, ctx.store, key, &deleted_artifact_keys);
        }
    }

    const req = types.BatchRequest{
        .deletes = keys,
        .sync_level = sync_level,
    };
    var derived_batch = try buildDerivedBatch(ctx.alloc, req, &.{}, deleted_artifact_keys.items, &.{});
    defer derived_types.deinitDerivedBatch(ctx.alloc, &derived_batch);
    const sequence = ctx.store.reserveNextReplaySequence(1);
    derived_batch.sequence = sequence;
    try doc_identity.appendBatchIdentityMetadataForNamespaceAlloc(
        ctx.alloc,
        ctx.store,
        ctx.identity_namespace,
        sequence,
        &identity_writes,
        &.{},
        keys,
    );
    try store_writes.appendSlice(ctx.alloc, identity_writes.items);
    try appendAssetArtifactSourceIndexMutations(
        ctx.alloc,
        &store_writes,
        deleted_artifact_keys.items,
        &delete_keys,
        &owned_store_keys,
        &owned_store_values,
        &owned_delete_keys,
    );
    const replay_payload = try encodeChangeRecordPayload(ctx, derived_batch, sequence);
    defer ctx.alloc.free(replay_payload);
    try ctx.store.putBatchWithReplay(ctx.io, store_writes.items, delete_keys.items, .{
        .sequence = sequence,
        .payload = replay_payload,
    });
    var sync_targets = try collectManagedSyncTargets(ctx.alloc, ctx.index_manager, derived_batch);
    defer sync_targets.deinit(ctx.alloc);
    ctx.executor.trackBacklogBytes(sequence, @intCast(replay_payload.len)) catch {};
    try markPrecomputedEnrichmentAppliedForSyncContext(ctx, sync_level, sequence);
    try applyDerivedBacklogPressureContext(ctx, sequence, sync_level, sync_targets);
    if (ctx.executor.hasWorkers()) {
        notifyExecutorForSyncLevelWithDenseBulkDeferral(ctx.async_context, ctx.executor, sync_level, sequence, sync_targets);
        try waitForSyncLevelContext(ctx, sync_level, sequence, sync_targets);
    } else {
        if (syncLevelRequiresDerivedVisibility(sync_level)) {
            ctx.apply_mutex.lockExclusive();
            defer ctx.apply_mutex.unlockExclusive();
            if (sync_level == .full_text) {
                try applyDerivedBatchTargetsContext(ctx, derived_batch, sync_targets.full_text_indexes);
            } else {
                try applyDerivedBatchContext(ctx, derived_batch);
            }
        }
        try waitForSyncLevelContext(ctx, sync_level, sequence, sync_targets);
    }
    if (ctx.enrichment_runtime) |runtime| runtime.notifySequence(sequence);
    notifyResolverReplayRuntimesForCatalog(ctx.index_manager, ctx.resolution_runtime, ctx.promotion_runtime, sequence);
}

fn deleteExpiredDocumentsFromCandidates(ctx_ptr: *anyopaque, candidates: []const ttl_runtime_mod.DeleteCandidate) !u32 {
    const ctx: *TtlCleanupContext = @ptrCast(@alignCast(ctx_ptr));
    const loaded_schema = try schema_mod.loadSchema(ctx.batch.store, ctx.batch.alloc);
    defer if (loaded_schema) |schema| schema_mod.freeSchema(ctx.batch.alloc, schema);

    const duration_ns = if (loaded_schema) |schema|
        schema.ttl_duration_ns
    else
        0;
    if (duration_ns == 0) return 0;

    const now_ns = currentTimeNs();
    var deletes = std.ArrayListUnmanaged([]const u8).empty;
    defer deletes.deinit(ctx.batch.alloc);

    for (candidates) |candidate| {
        const current_ts = (try ttl_mod.readTimestamp(ctx.batch.store, ctx.batch.alloc, candidate.key)) orelse continue;
        if (current_ts != candidate.timestamp_ns) continue;
        if (!ttl_mod.isExpiredWithGrace(current_ts, duration_ns, ctx.grace_period_ns, now_ns)) continue;
        try deletes.append(ctx.batch.alloc, candidate.key);
    }
    if (deletes.items.len == 0) return 0;

    try executeDeleteBatchContext(&ctx.batch, deletes.items, .full_index);
    return @intCast(deletes.items.len);
}

fn appendDerivedBatchRecord(self: *DB, batch: derived_types.DerivedBatch) !u64 {
    var ctx = self.batchContext();
    return try appendDerivedBatchRecordContext(&ctx, batch);
}

fn appendDerivedBatchRecordContext(ctx: *const BatchExecutionContext, batch: derived_types.DerivedBatch) !u64 {
    const sequence = ctx.store.reserveNextReplaySequence(1);
    const payload = try encodeChangeRecordPayload(ctx, batch, sequence);
    defer ctx.alloc.free(payload);
    try ctx.store.appendReplayOpaque(ctx.alloc, sequence, payload);
    ctx.executor.trackBacklogBytes(sequence, @intCast(payload.len)) catch {};
    return sequence;
}

fn encodeChangeRecordPayload(ctx: *const BatchExecutionContext, batch: derived_types.DerivedBatch, sequence: u64) ![]u8 {
    var record = try change_journal_mod.recordFromDerivedBatch(ctx.alloc, batch, sequence);
    defer change_journal_mod.deinitRecord(ctx.alloc, &record);
    return try change_journal_mod.encodeRecord(ctx.alloc, record);
}

fn applyDerivedBacklogPressureContext(ctx: *const BatchExecutionContext, sequence: u64, sync_level: types.SyncLevel, sync_targets: ManagedSyncTargets) !void {
    switch (sync_level) {
        .propose, .write => return,
        .enrichments, .full_text, .aknn, .full_index => {},
    }
    if (!ctx.executor.shouldThrottleBacklog()) return;
    if (sync_level == .full_text) {
        try runDerivedUntilTargetsContext(ctx, sequence, sync_targets.full_text_indexes);
        return;
    }
    if (shouldDeferBacklogPressureForExternalDenseBulk(ctx, sync_level)) return;
    runDerivedUntilContext(ctx, sequence) catch |err| switch (err) {
        error.WriterLocked, error.ReplayDocumentNotVisible => {
            ctx.executor.notifySequence(sequence);
            return;
        },
        else => return err,
    };
}

fn shouldDeferBacklogPressureForExternalDenseBulk(ctx: *const BatchExecutionContext, sync_level: types.SyncLevel) bool {
    switch (sync_level) {
        .propose, .write, .enrichments => {},
        .full_text, .aknn, .full_index => return false,
    }
    const async_context = ctx.async_context orelse return false;
    return async_context.active_external_dense_bulk_sessions.load(.acquire) != 0;
}

fn runDerivedUntilContext(ctx: *const BatchExecutionContext, sequence: u64) !void {
    if (sequence == 0) return;
    if (!ctx.executor.hasWorkers()) {
        try replayPendingDerivedBatchesContext(ctx);
        return;
    }
    ctx.executor.notifySequence(sequence);
    try ctx.executor.waitForAll(sequence);
}

fn runDerivedUntilTargetsContext(ctx: *const BatchExecutionContext, sequence: u64, index_names: []const []const u8) !void {
    if (sequence == 0 or index_names.len == 0) return;
    if (!ctx.executor.hasWorkers()) return;
    ctx.executor.notifyIndexes(sequence, index_names);
    try ctx.executor.waitForIndexes(sequence, index_names);
}

fn runEnrichmentUntilContext(ctx: *const BatchExecutionContext, sequence: u64) !void {
    if (sequence == 0) return;
    if (ctx.enrichment_runtime) |runtime| {
        runtime.notifySequence(sequence);
        try runtime.waitForApplied(sequence);
    }
}

fn markPrecomputedEnrichmentAppliedForSyncContext(ctx: *const BatchExecutionContext, sync_level: types.SyncLevel, sequence: u64) !void {
    if (sync_level != .enrichments or sequence == 0) return;
    const runtime = ctx.enrichment_runtime orelse return;
    const runtime_stats = runtime.stats();
    if (runtime_stats.applied_sequence >= sequence -| 1 or
        try noPendingEnrichmentReplayThroughContext(ctx, runtime_stats.applied_sequence, sequence))
    {
        try runtime.markAppliedThrough(sequence);
    }
}

fn noPendingEnrichmentReplayThroughContext(ctx: *const BatchExecutionContext, applied_sequence: u64, sequence: u64) !bool {
    const pending = try enrichment_worker.collectPendingDocumentGroups(ctx.alloc, ctx.replay_source, applied_sequence);
    defer enrichment_worker.freePendingDocumentGroups(ctx.alloc, pending);
    for (pending) |group| {
        if (group.sequence <= sequence) return false;
    }
    return true;
}

fn runMaintenanceUntilContext(ctx: *const BatchExecutionContext, sequence: u64, sync_targets: ManagedSyncTargets) !void {
    var stable_target = sequence;
    while (true) {
        try runDerivedUntilContext(ctx, stable_target);
        try runEnrichmentUntilContext(ctx, stable_target);

        const next_target = currentReplayTargetSequenceContext(ctx);
        if (next_target <= stable_target) {
            try waitForManagedIndexesAppliedContext(ctx, sequence, sync_targets.all_indexes);
            return;
        }
        stable_target = next_target;
    }
}

fn runMaintenanceUntilTargetsContext(ctx: *const BatchExecutionContext, sequence: u64, index_names: []const []const u8) !void {
    if (index_names.len == 0) return;
    var stable_target = sequence;
    while (true) {
        try runDerivedUntilTargetsContext(ctx, stable_target, index_names);
        try runEnrichmentUntilContext(ctx, stable_target);

        const next_target = currentReplayTargetSequenceContext(ctx);
        if (next_target <= stable_target) {
            try waitForManagedIndexesAppliedContext(ctx, sequence, index_names);
            return;
        }
        stable_target = next_target;
    }
}

fn currentReplayTargetSequenceContext(ctx: *const BatchExecutionContext) u64 {
    return ctx.store.lastReplaySequence(0);
}

fn waitForSyncLevelContext(ctx: *const BatchExecutionContext, sync_level: types.SyncLevel, sequence: u64, sync_targets: ManagedSyncTargets) !void {
    switch (sync_level) {
        .propose, .write => try ctx.executor.failIfUnhealthy(),
        .enrichments => {
            try ctx.executor.failIfUnhealthy();
            try runEnrichmentUntilContext(ctx, sequence);
        },
        .full_text => {
            try runMaintenanceUntilTargetsContext(ctx, sequence, sync_targets.full_text_indexes);
        },
        .aknn, .full_index => try runMaintenanceUntilContext(ctx, sequence, sync_targets),
    }
}

fn syncLevelRequiresDerivedVisibility(sync_level: types.SyncLevel) bool {
    return switch (sync_level) {
        .propose, .write, .enrichments => false,
        .full_text, .aknn, .full_index => true,
    };
}

fn denseCatchUpFinishOptions() backend_types.BulkIngestFinishOptions {
    return .{
        .compact = false,
        .flush = true,
        .max_deferred_l0_runs = denseCatchUpDeferredL0Limit(),
        .max_deferred_hbc_leaf_splits_per_publish = denseCatchUpDeferredHbcLeafSplitsPerPublish(),
        .max_deferred_hbc_leaf_split_members_per_publish = denseCatchUpDeferredHbcLeafSplitMembersPerPublish(),
        .bulk_rebuild_hbc_leaf_min_members = denseCatchUpBulkRebuildHbcLeafMinMembers(),
    };
}

