    try std.testing.expectEqual(@as(usize, 1), sparse_filtered.hits.len);
    try std.testing.expectEqualStrings("doc:b", sparse_filtered.hits[0].id);

    var dense_empty_text_filter = try db.searchDenseProfiled(alloc, .{
