    errdefer alloc.free(authority_value);
    try writes.append(alloc, .{ .key = authority_key, .value = authority_value });

    try local_db.batch(.{
        .writes = writes.items,
        .sync_level = .write,
    });
    try planned_db.batch(.{
        .writes = writes.items,
        .sync_level = .write,
    });
