        .exclusion_query_json = "{\"bool\":{\"must_not\":[{\"term_range\":{\"field\":\"tag\",\"min\":\"a\",\"max\":\"m\"}},{\"ip_range\":{\"field\":\"ip\",\"cidr\":\"10.0.0.0/8\"}}]}}",
