        seen: usize = 0,
        last: ReplayProgress = .{},

        fn run(ptr: *anyopaque, _: []const u8, progress: ReplayProgress) !void {
            const self: *@This() = @ptrCast(@alignCast(ptr));
            self.seen += 1;
            self.last = progress;
        }
