    try std.testing.expectEqual(@as(u32, 3), prefix_results.total_hits);

    const multi_match_fields = [_]types.TextMultiMatchField{
        .{ .field = "name" },
    };
    var bool_prefix_results = try db.search(alloc, .{
        .index_name = "ft_v1",
