    defer db.abortTransaction(txn_id, 2_001) catch {};
    const predicates = [_]schema_mod.RelationalCheck{.{
        .name = "",
        .field = "sku",
        .op = .eq,
        .value_json = "\"sku:a\"",
    }};
    const operations = [_]types.TransformOp{.{
        .op = .set,
        .path = "price",
        .value_json = "99",
