        },
        .transforms = &.{
            .{
                .key = "doc:coalesce",
                .operations = &.{
                    .{ .op = .inc, .path = "count", .value_json = "2" },
                    .{ .op = .add_to_set, .path = "tags", .value_json = "\"zig\"" },
                },
