test "db batch enforces optimistic version predicates" {
    const alloc = std.testing.allocator;

    var path_buf: [256]u8 = undefined;
    const path = tempPath(&path_buf);
    defer cleanupTempDir(path);

    var db = try DB.open(alloc, std.mem.span(path), .{});
    defer db.close();

    try db.batch(.{
        .writes = &.{.{ .key = "doc:cas", .value = "{\"title\":\"v1\"}" }},
        .timestamp_ns = 10_000,
    });

    try std.testing.expectError(transactions_mod.TxnError.VersionConflict, db.batch(.{
        .writes = &.{.{ .key = "doc:cas", .value = "{\"title\":\"v2\"}" }},
        .predicates = &.{.{ .key = "doc:cas", .expected_version = 0 }},
        .timestamp_ns = 11_000,
    }));

    try db.batch(.{
        .writes = &.{.{ .key = "doc:cas", .value = "{\"title\":\"v2\"}" }},
        .predicates = &.{.{ .key = "doc:cas", .expected_version = 10_000 }},
        .timestamp_ns = 11_000,
    });

    const raw = (try db.get(alloc, "doc:cas")) orelse return error.TestExpectedEqual;
    defer alloc.free(raw);
    try std.testing.expectEqualStrings("{\"title\":\"v2\"}", raw);
    try std.testing.expectEqual(@as(u64, 11_000), try db.getTimestamp(alloc, "doc:cas"));
}

test "db persists byte range across reopen" {
    const alloc = std.testing.allocator;

    var path_buf: [256]u8 = undefined;
    const path = tempPath(&path_buf);
    defer cleanupTempDir(path);

    {
        var db = try DB.open(alloc, std.mem.span(path), .{});
        defer db.close();

        try db.updateRange(.{ .start = "doc:b", .end = "doc:m" });
        const byte_range = db.getRange();
        try std.testing.expectEqualStrings("doc:b", byte_range.start);
        try std.testing.expectEqualStrings("doc:m", byte_range.end);
    }

    {
        var db = try DB.open(alloc, std.mem.span(path), .{});
        defer db.close();

        const byte_range = db.getRange();
        try std.testing.expectEqualStrings("doc:b", byte_range.start);
        try std.testing.expectEqualStrings("doc:m", byte_range.end);
        try std.testing.expectError(error.KeyOutOfRange, db.batch(.{
            .writes = &.{.{ .key = "doc:z", .value = "{\"title\":\"outside\"}" }},
        }));
        try db.batchWithoutRangeValidation(.{
            .writes = &.{.{ .key = "doc:z", .value = "{\"title\":\"outside\"}" }},
        });
        const outside = (try db.get(alloc, "doc:z")).?;
        defer alloc.free(outside);
        try std.testing.expectEqualStrings("{\"title\":\"outside\"}", outside);
    }
}

test "db split state and split deltas are exposed through public api" {
    const alloc = std.testing.allocator;

    var path_buf: [256]u8 = undefined;
