            .{ .key = "row:3", .value = "{\"id\":\"3\",\"customer\":\"alice\"}" },
            .{ .key = "row:4", .value = "{\"id\":\"4\",\"customer\":\"bob\"}" },
            .{ .key = "row:5", .value = "{\"id\":\"5\",\"customer\":\"carol\",\"enabled\":false}" },
